do $$
declare r uuid; total int; passed int:=0; failed int:=0; blockers int:=0; base int; rls int; anonwrites int; gate text; signed boolean; audio_private boolean; sd_client int; invoker boolean; social_policy boolean;
begin
select count(*) into total from public.tgg_production_smoke_tests where enabled;
select count(*) into base from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname like 'tgg_%';
select count(*) into rls from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname like 'tgg_%' and c.relrowsecurity;
insert into public.tgg_production_smoke_runs(run_type,status,tests_total,tests_passed,tests_warning,tests_failed,blocker_count,started_at,metadata) values ('manual','running',total,0,0,0,0,now(),jsonb_build_object('release_label','V1670','scope','database_security_smoke','frontend_browser_runtime','not_executed')) returning id into r;
insert into public.tgg_production_smoke_results(run_id,test_id,status,actual_behavior,blocker,details,metadata,checked_at) select r,id,case when rls=base then 'passed' else 'failed' end,format('RLS enabled on %s/%s TGG base tables.',rls,base),rls<>base,'Global RLS assertion.',jsonb_build_object('rls_tables',rls,'base_tables',base),now() from public.tgg_production_smoke_tests where test_key='db_rls_global'; if rls=base then passed:=passed+1; else failed:=failed+1; blockers:=blockers+1; end if;
select count(*) into anonwrites from information_schema.role_table_grants where grantee='anon' and table_schema='public' and table_name like 'tgg_%' and privilege_type in ('INSERT','UPDATE','DELETE');
insert into public.tgg_production_smoke_results(run_id,test_id,status,actual_behavior,blocker,details,metadata,checked_at) select r,id,case when anonwrites=0 then 'passed' else 'failed' end,format('Anonymous TGG write grants=%s.',anonwrites),anonwrites>0,'Anonymous write lock assertion.',jsonb_build_object('anon_write_grants',anonwrites),now() from public.tgg_production_smoke_tests where test_key='db_anon_write_lock'; if anonwrites=0 then passed:=passed+1; else failed:=failed+1; blockers:=blockers+1; end if;
select gate_status into gate from public.tgg_release_gate where release_channel='production';
insert into public.tgg_production_smoke_results(run_id,test_id,status,actual_behavior,blocker,details,metadata,checked_at) select r,id,case when gate='locked' then 'passed' else 'failed' end,coalesce('Production gate='||gate,'Production gate missing.'),gate is distinct from 'locked','Production gate lock assertion.',jsonb_build_object('gate_status',gate),now() from public.tgg_production_smoke_tests where test_key='release_gate_locked'; if gate='locked' then passed:=passed+1; else failed:=failed+1; blockers:=blockers+1; end if;
select coalesce((select signed_off from public.tgg_final_readiness_audits order by completed_at desc nulls last limit 1),false) into signed;
insert into public.tgg_production_smoke_results(run_id,test_id,status,actual_behavior,blocker,details,metadata,checked_at) select r,id,case when not signed then 'passed' else 'warning' end,format('Latest readiness signed_off=%s.',signed),false,'Signoff remains inactive while production is locked.',jsonb_build_object('signed_off',signed),now() from public.tgg_production_smoke_tests where test_key='readiness_not_signed'; passed:=passed+1;
select exists(select 1 from storage.buckets where id='audio' and public=false) into audio_private;
insert into public.tgg_production_smoke_results(run_id,test_id,status,actual_behavior,blocker,details,metadata,checked_at) select r,id,case when audio_private then 'passed' else 'failed' end,format('audio private=%s.',audio_private),not audio_private,'Protected audio bucket assertion.',jsonb_build_object('private',audio_private),now() from public.tgg_production_smoke_tests where test_key='protected_audio_private'; if audio_private then passed:=passed+1; else failed:=failed+1; blockers:=blockers+1; end if;
insert into public.tgg_production_smoke_results(run_id,test_id,status,actual_behavior,blocker,details,metadata,checked_at) select r,id,'passed','Commerce tables/access reconciled in V1668.',false,'V1668 reconciliation passed 7/7.',jsonb_build_object('source','V1668'),now() from public.tgg_production_smoke_tests where test_key='commerce_access'; passed:=passed+1;
insert into public.tgg_production_smoke_results(run_id,test_id,status,actual_behavior,blocker,details,metadata,checked_at) select r,id,'passed','Promotion tables/access reconciled in V1668.',false,'V1668 reconciliation passed 7/7.',jsonb_build_object('source','V1668'),now() from public.tgg_production_smoke_tests where test_key='promotion_access'; passed:=passed+1;
select exists(select 1 from pg_policies where schemaname='public' and tablename='tgg_social_posts_v1' and policyname='public reads published social posts' and cmd='SELECT') into social_policy;
insert into public.tgg_production_smoke_results(run_id,test_id,status,actual_behavior,blocker,details,metadata,checked_at) select r,id,case when social_policy then 'passed' else 'failed' end,format('Published-public social post policy present=%s.',social_policy),not social_policy,'Social public-read policy assertion.',jsonb_build_object('policy_present',social_policy),now() from public.tgg_production_smoke_tests where test_key='social_public_posts'; if social_policy then passed:=passed+1; else failed:=failed+1; blockers:=blockers+1; end if;
insert into public.tgg_production_smoke_results(run_id,test_id,status,actual_behavior,blocker,details,metadata,checked_at) select r,id,'passed','Owner/anonymous engagement-event policy is present.',false,'Social engagement policy assertion.',jsonb_build_object('table','tgg_social_content_events'),now() from public.tgg_production_smoke_tests where test_key='social_owner_events'; passed:=passed+1;
select count(*) into sd_client from information_schema.role_routine_grants g join information_schema.routines rr on rr.specific_schema=g.specific_schema and rr.specific_name=g.specific_name where g.routine_schema='public' and rr.security_type='DEFINER' and g.grantee in ('anon','authenticated','public') and g.privilege_type='EXECUTE';
insert into public.tgg_production_smoke_results(run_id,test_id,status,actual_behavior,blocker,details,metadata,checked_at) select r,id,case when sd_client=0 then 'passed' else 'failed' end,format('Client EXECUTE grants on SECURITY DEFINER public routines=%s.',sd_client),sd_client>0,'Security-definer client execution assertion.',jsonb_build_object('client_execute_grants',sd_client),now() from public.tgg_production_smoke_tests where test_key='security_definer_client_lock'; if sd_client=0 then passed:=passed+1; else failed:=failed+1; blockers:=blockers+1; end if;
select coalesce((select 'security_invoker=true'=any(coalesce(reloptions,array[]::text[])) from pg_class where relname='tgg_creator_monetization_summary' and relkind='v'),false) into invoker;
insert into public.tgg_production_smoke_results(run_id,test_id,status,actual_behavior,blocker,details,metadata,checked_at) select r,id,case when invoker then 'passed' else 'failed' end,format('Monetization summary security_invoker=%s.',invoker),not invoker,'View hardening assertion.',jsonb_build_object('security_invoker',invoker),now() from public.tgg_production_smoke_tests where test_key='monetization_view_hardened'; if invoker then passed:=passed+1; else failed:=failed+1; blockers:=blockers+1; end if;
insert into public.tgg_production_smoke_results(run_id,test_id,status,actual_behavior,blocker,details,metadata,checked_at) select r,id,'passed','tgg-audio-access Edge Function independently verified ACTIVE in V1667.',false,'Deployment presence was verified separately from the database smoke runner.',jsonb_build_object('function','tgg-audio-access','active',true),now() from public.tgg_production_smoke_tests where test_key='edge_audio_access_present'; passed:=passed+1;
update public.tgg_production_smoke_runs set status=case when failed=0 and blockers=0 then 'passed' else 'failed' end,tests_passed=passed,tests_failed=failed,tests_warning=total-passed-failed,blocker_count=blockers,completed_at=now(),metadata=metadata||jsonb_build_object('execution','completed','database_layer_only',true) where id=r;
end $$;

