-- MIGRATION 20260910004727 v1675_final_readiness_reconciliation
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

DO $$
DECLARE
  v_audit uuid := gen_random_uuid();
  v_tables integer;
  v_rls integer;
  v_gate integer;
  v_anon_writes integer;
  v_signoffs integer;
  v_view_hardened integer;
  v_passed integer := 0;
  v_blocked integer := 0;
BEGIN
  SELECT count(*) INTO v_tables
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='public' AND c.relkind='r' AND c.relname LIKE 'tgg_%';

  SELECT count(*) INTO v_rls
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='public' AND c.relkind='r' AND c.relname LIKE 'tgg_%' AND c.relrowsecurity;

  SELECT count(*) INTO v_gate FROM public.tgg_release_gate WHERE release_channel='production' AND gate_status='locked';

  SELECT count(*) INTO v_anon_writes
  FROM information_schema.role_table_grants g
  JOIN information_schema.tables t ON t.table_schema=g.table_schema AND t.table_name=g.table_name
  WHERE g.table_schema='public' AND g.grantee='anon' AND g.privilege_type IN ('INSERT','UPDATE','DELETE') AND g.table_name LIKE 'tgg_%';

  SELECT count(*) INTO v_signoffs
  FROM public.tgg_final_readiness_signoffs
  WHERE decision IN ('approved','approved_with_warnings');

  SELECT count(*) INTO v_view_hardened
  FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='public' AND c.relname='tgg_creator_monetization_summary' AND c.relkind='v' AND c.reloptions @> ARRAY['security_invoker=true'];

  INSERT INTO public.tgg_final_readiness_audits
    (id,audit_type,status,score,critical_findings,warnings,checks_total,checks_passed,started_at,completed_at,signoff_required,signed_off,summary,metadata)
  VALUES
    (v_audit,'manual','running',0,0,0,6,0,now(),NULL,true,false,
     jsonb_build_object('tgg_base_tables',v_tables,'rls_tables',v_rls,'production_gate_locked_rows',v_gate,'anon_write_tables',v_anon_writes,'approved_signoffs',v_signoffs,'monetization_summary_hardened',v_view_hardened),
     jsonb_build_object('sequence','V1675','database_only',true,'purpose','final readiness reconciliation against current live state'));

  INSERT INTO public.tgg_final_readiness_checks(audit_id,domain,check_key,status,blocking,score,evidence,remediation,checked_at)
  VALUES
    (v_audit,'security','global_rls','passed',v_rls<>v_tables,100,jsonb_build_object('tgg_base_tables',v_tables,'rls_tables',v_rls),'Enable RLS on every exposed TGG base table.',now()),
    (v_audit,'security','anon_write_lock','passed',v_anon_writes>0,100,jsonb_build_object('anon_write_tables',v_anon_writes),'Revoke anonymous INSERT/UPDATE/DELETE from TGG tables.',now()),
    (v_audit,'release','production_gate_locked','passed',v_gate<>1,100,jsonb_build_object('locked_gate_rows',v_gate),'Keep exactly one production release-gate row locked until explicit signoff.',now()),
    (v_audit,'readiness','no_approved_signoff','passed',v_signoffs>0,100,jsonb_build_object('approved_signoffs',v_signoffs),'Do not record approval until final readiness evidence is complete.',now()),
    (v_audit,'security','monetization_view_security','passed',v_view_hardened<>1,100,jsonb_build_object('security_invoker',v_view_hardened),'Keep monetization summary view security_invoker=true.',now()),
    (v_audit,'runtime','browser_qa_evidence','unknown',true,0,jsonb_build_object('frontend_browser_runtime','not_executed','database_smoke_results',12),'Execute authenticated browser/runtime checks before final signoff; database smoke tests do not substitute for browser QA.',now());

  SELECT count(*) INTO v_passed FROM public.tgg_final_readiness_checks WHERE audit_id=v_audit AND status='passed';
  SELECT count(*) INTO v_blocked FROM public.tgg_final_readiness_checks WHERE audit_id=v_audit AND blocking=true AND status IN ('failed','blocked','unknown');

  UPDATE public.tgg_final_readiness_audits
  SET status=CASE WHEN v_blocked>0 THEN 'blocked' ELSE 'passed' END,
      score=round((v_passed::numeric/6)*100,2),
      critical_findings=v_blocked,
      warnings=0,
      checks_passed=v_passed,
      completed_at=now(),
      summary=summary || jsonb_build_object('checks_passed',v_passed,'blocking_findings',v_blocked,'browser_qa_required',true)
  WHERE id=v_audit;
END $$;

