-- ============================================================
-- MIGRATION 20260910005809 v1685_final_evidence_aggregation_reconciliation
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

create or replace function public.tgg_v1685_reconcile_readiness()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  r record;
  passed integer := 0;
  failed integer := 0;
  pending integer := 0;
  total integer := 0;
  new_run uuid;
  score numeric := 0;
  decision text := 'blocked';
  blocker jsonb := '[]'::jsonb;
begin
  select count(*) into total from public.tgg_browser_runtime_evidence_gate where evidence_required = true;
  select count(*) into passed from public.tgg_browser_runtime_evidence_gate where evidence_required = true and browser_verified = true and status = 'passed';
  select count(*) into failed from public.tgg_browser_runtime_evidence_gate where evidence_required = true and status = 'failed';
  pending := greatest(total - passed - failed, 0);
  if total > 0 then score := round((passed::numeric / total::numeric) * 100, 2); end if;
  if total > 0 and passed = total and failed = 0 then decision := 'ready'; else decision := 'blocked'; end if;
  if pending > 0 then blocker := blocker || jsonb_build_array(jsonb_build_object('code','browser_qa_evidence','required',pending,'message','Real authenticated browser evidence is still required.')); end if;
  if failed > 0 then blocker := blocker || jsonb_build_array(jsonb_build_object('code','browser_qa_failed','count',failed,'message','One or more browser runtime flows failed.')); end if;

  insert into public.tgg_platform_readiness_runs(run_type,status,readiness_score,critical_failures,warnings,unknowns,started_at,completed_at,summary,metadata)
  values ('pre_release', decision, score, case when decision='blocked' then 1 else 0 end, 0, pending, now(), now(),
          'V1685 final evidence aggregation; browser evidence is evaluated independently from database/runtime contract checks.',
          jsonb_build_object('browser_total',total,'browser_passed',passed,'browser_failed',failed,'browser_pending',pending,'production_gate','locked'))
  returning id into new_run;

  insert into public.tgg_platform_readiness_signals(run_id,signal_source,signal_type,status,score,weight,blocking,evidence)
  values (new_run,'v1685_evidence_reconciliation','browser_qa_evidence',case when decision='ready' then 'passed' else 'blocked' end,score,1,true,
          jsonb_build_object('total',total,'passed',passed,'failed',failed,'pending',pending));

  insert into public.tgg_platform_readiness_decisions(run_id,decision,rationale,blocking_reasons,warnings,decided_at)
  values (new_run,decision,
          case when decision='ready' then 'All required browser evidence is verified.' else 'Database/runtime controls may pass, but browser evidence is not fully verified.' end,
          blocker,'[]'::jsonb,now());

  return jsonb_build_object('run_id',new_run,'decision',decision,'score',score,'total',total,'passed',passed,'failed',failed,'pending',pending,'production_gate','locked');
end;
$$;

revoke all on function public.tgg_v1685_reconcile_readiness() from public, anon, authenticated;
grant execute on function public.tgg_v1685_reconcile_readiness() to service_role;

-- ============================================================
-- MIGRATION 20260910005825 v1685_reconcile_json_fix
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

create or replace function public.tgg_v1685_reconcile_readiness()
returns jsonb language plpgsql security definer set search_path=public as $$
declare r record; passed integer:=0; failed integer:=0; pending integer:=0; total integer:=0; new_run uuid; score numeric:=0; decision text:='blocked'; blocker jsonb:='[]'::jsonb;
begin
select count(*) into total from public.tgg_browser_runtime_evidence_gate where evidence_required;
select count(*) into passed from public.tgg_browser_runtime_evidence_gate where evidence_required and browser_verified and status='passed';
