-- ============================================================
-- MIGRATION 20260910005954 v1687_evidence_aggregation_blocker_aware_readiness
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

create or replace function public.tgg_v1687_refresh_readiness()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_run_id uuid;
  v_verified int := 0;
  v_required int := 0;
  v_contracts int := 0;
  v_contract_passed int := 0;
  v_gate text;
  v_score numeric := 0;
  v_status text := 'blocked';
begin
  select count(*) into v_required from public.tgg_browser_runtime_evidence_gate where evidence_required = true;
  select count(*) into v_verified from public.tgg_browser_runtime_evidence_gate where evidence_required = true and browser_verified = true and status = 'passed';
  select count(*) into v_contracts from public.tgg_runtime_contracts where active = true;
  select count(*) into v_contract_passed from public.tgg_runtime_contract_checks c join public.tgg_runtime_contracts r on r.id=c.contract_id where r.active=true and c.status='passed';
  select gate_status into v_gate from public.tgg_release_gate where release_channel='production' limit 1;
  if v_required > 0 and v_verified = v_required and v_contracts = v_contract_passed and coalesce(v_gate,'locked') <> 'locked' then
    v_score := 100; v_status := 'ready';
  elsif v_required > 0 then
    v_score := round(((v_contract_passed::numeric / greatest(v_contracts,1)) * 90) + ((v_verified::numeric / greatest(v_required,1)) * 10),2);
    v_status := 'blocked';
  else
    v_score := 0; v_status := 'blocked';
  end if;
  insert into public.tgg_platform_readiness_runs(run_type,status,readiness_score,critical_failures,warnings,unknowns,started_at,completed_at,summary,metadata)
  values ('pre_release',v_status,v_score,case when v_verified < v_required then 1 else 0 end,0,case when v_verified < v_required then 1 else 0 end,now(),now(),jsonb_build_object('browser_evidence',jsonb_build_object('required',v_required,'verified',v_verified),'runtime_contracts',jsonb_build_object('active',v_contracts,'passed',v_contract_passed),'production_gate',coalesce(v_gate,'missing')),jsonb_build_object('engine','V1687','browser_execution_required',true))
  returning id into v_run_id;
  insert into public.tgg_platform_readiness_signals(run_id,signal_source,signal_type,status,score,weight,blocking,evidence)
  values(v_run_id,'V1687','browser_qa_evidence',case when v_verified=v_required then 'passed' else 'blocked' end,case when v_required=0 then 0 else round(v_verified::numeric/greatest(v_required,1)*100,2) end,1,true,jsonb_build_object('required',v_required,'verified',v_verified,'note','Only actual browser evidence can satisfy this signal'));
  insert into public.tgg_platform_readiness_decisions(run_id,decision,rationale,blocking_reasons,warnings,decided_at,decided_by)
  values(v_run_id,v_status,'V1687 blocker-aware aggregation; browser evidence is independent from database contract checks',case when v_verified<v_required then jsonb_build_array('browser_qa_evidence') else '[]'::jsonb end,'[]'::jsonb,now(),'V1687');
  return jsonb_build_object('run_id',v_run_id,'status',v_status,'score',v_score,'browser_required',v_required,'browser_verified',v_verified,'contracts',v_contracts,'contracts_passed',v_contract_passed,'production_gate',v_gate);
end;
$$;
revoke all on function public.tgg_v1687_refresh_readiness() from public, anon, authenticated;
grant execute on function public.tgg_v1687_refresh_readiness() to service_role;

