create table if not exists public.tgg_browser_evidence_integrity_audit (
 id uuid primary key default gen_random_uuid(),
 audit_version text not null,
 required_flows integer not null,
 verified_flows integer not null,
 fabricated_flows integer not null default 0,
 expired_flows integer not null default 0,
 missing_flows integer not null,
 integrity_status text not null check (integrity_status in ('pass','blocked','fail')),
 details jsonb not null default '{}'::jsonb,
 created_at timestamptz not null default now()
);

alter table public.tgg_browser_evidence_integrity_audit enable row level security;
revoke all on public.tgg_browser_evidence_integrity_audit from anon, authenticated;
grant all on public.tgg_browser_evidence_integrity_audit to service_role;

create or replace function public.tgg_v1689_browser_evidence_integrity()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
 required_count integer;
 verified_count integer;
 fabricated_count integer;
 expired_count integer;
 missing_count integer;
 result_status text;
begin
 select count(*) filter (where evidence_required),
        count(*) filter (where evidence_required and browser_verified),
        count(*) filter (where evidence_required and browser_verified and (evidence ? 'synthetic') and coalesce((evidence->>'synthetic')::boolean,false)),
        count(*) filter (where evidence_required and browser_verified and checked_at is not null and checked_at < now() - interval '30 days')
 into required_count, verified_count, fabricated_count, expired_count
 from public.tgg_browser_runtime_evidence_gate;
 missing_count := greatest(required_count - verified_count,0);
 result_status := case when fabricated_count > 0 then 'fail' when missing_count > 0 or expired_count > 0 then 'blocked' else 'pass' end;
 insert into public.tgg_browser_evidence_integrity_audit(audit_version,required_flows,verified_flows,fabricated_flows,expired_flows,missing_flows,integrity_status,details)
 values('V1689',required_count,verified_count,fabricated_count,expired_count,missing_count,result_status,jsonb_build_object('browser_evidence_only',true,'production_gate_remains_locked',true));
 return jsonb_build_object('required_flows',required_count,'verified_flows',verified_count,'fabricated_flows',fabricated_count,'expired_flows',expired_count,'missing_flows',missing_count,'integrity_status',result_status);
end;
$$;
revoke all on function public.tgg_v1689_browser_evidence_integrity() from public, anon, authenticated;
grant execute on function public.tgg_v1689_browser_evidence_integrity() to service_role;

