create table if not exists public.tgg_final_launch_orchestrator (
  id uuid primary key default gen_random_uuid(),
  run_at timestamptz not null default now(),
  tgg_base_tables integer not null default 0,
  rls_enabled integer not null default 0,
  active_contracts integer not null default 0,
  passed_contract_checks integer not null default 0,
  browser_required integer not null default 0,
  browser_verified integer not null default 0,
  workflow_passed integer not null default 0,
  production_gate text not null default 'locked',
  decision text not null default 'blocked',
  blocker text,
  created_at timestamptz not null default now()
);
alter table public.tgg_final_launch_orchestrator enable row level security;
revoke all on public.tgg_final_launch_orchestrator from anon, authenticated;
insert into public.tgg_final_launch_orchestrator
(tgg_base_tables, rls_enabled, active_contracts, passed_contract_checks, browser_required, browser_verified, workflow_passed, production_gate, decision, blocker)
select
  (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname like 'tgg_%'),
  (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname like 'tgg_%' and c.relrowsecurity),
  (select count(*) from public.tgg_runtime_contracts where status='active'),
  (select count(*) from public.tgg_runtime_contract_checks where status='passed'),
  (select count(*) from public.tgg_browser_runtime_evidence_gate where evidence_required=true),
  (select count(*) from public.tgg_browser_runtime_evidence_gate where browser_verified=true),
  (select count(*) from public.tgg_runtime_evidence_capture_workflow where status='passed'),
  coalesce((select gate_status from public.tgg_release_gate where release_channel='production' limit 1),'locked'),
  case when exists (select 1 from public.tgg_browser_runtime_evidence_gate where evidence_required=true and browser_verified=false) then 'blocked' else 'ready' end,
  case when exists (select 1 from public.tgg_browser_runtime_evidence_gate where evidence_required=true and browser_verified=false) then 'browser_qa_evidence' else null end;

