create or replace function public.tgg_one_jack_refresh()
returns jsonb
language plpgsql
security definer
set search_path to ''
as $$
declare
  v_h jsonb:=public.tgg_one_hunter_state();
  v_s jsonb:=public.tgg_one_scout_state();
  v_type text;
  v_key text;
  v_status text:='idle';
  v_review boolean:=false;
  v_id uuid;
begin
  if coalesce(v_h->>'status','idle')='tracking' and nullif(v_h->>'target_key','') is not null then
    v_type:=v_h->>'target_type'; v_key:=v_h->>'target_key'; v_status:='watching'; v_review:=false;
  else
    select x->>'type', coalesce(x->>'key',x->>'type','scout_finding'), coalesce((x->>'auto_fix_allowed')::boolean,false)=false
    into v_type,v_key,v_review
    from jsonb_array_elements(coalesce(v_s->'findings','[]'::jsonb)) x limit 1;
    v_review:=coalesce(v_review,false);
    if found then v_status:=case when v_review then 'gated' else 'watching' end; end if;
  end if;
  insert into public.tgg_one_jack_snapshots(status,target_type,target_key,target_status,evidence_count,review_only,watch)
  values(v_status,v_type,v_key,case when v_review then 'review_only' when v_status='watching' then 'tracking' else null end,case when v_key is null then 0 else 1 end,coalesce(v_review,false),jsonb_build_object('role','single_target_deep_watch','can_execute',false,'one_target_only',true)) returning id into v_id;
  return jsonb_build_object('ok',true,'snapshot_id',v_id,'status',v_status,'target_type',v_type,'target_key',v_key,'review_only',coalesce(v_review,false));
end
$$;
revoke all on function public.tgg_one_jack_refresh() from public, anon, authenticated;
grant execute on function public.tgg_one_jack_refresh() to service_role;

