-- ============================================================
-- MIGRATION 20260910043017 fix_codesync_retirement_hold_false_positive
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

do $do$
declare
  v_def text;
begin
  select pg_get_functiondef(p.oid)
    into v_def
  from pg_proc p
  join pg_namespace n on n.oid=p.pronamespace
  where n.nspname='private'
    and p.proname='tgg_codesync_known_regressions'
  limit 1;

  if v_def is null then
    raise exception 'tgg_codesync_known_regressions not found';
  end if;

  if position('where approved_state in (''ready'',''hold'')' in v_def)=0 then
    raise exception 'expected retirement-state predicate not found';
  end if;

  v_def:=replace(
    v_def,
    'where approved_state in (''ready'',''hold'')',
    'where approved_state = ''ready'''
  );

  execute v_def;
end
$do$;

