-- ============================================================
-- MIGRATION 20260910060516 prefer_active_claimed_call_validation_room
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

CREATE OR REPLACE FUNCTION private.tgg_call_validation_invite_status()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_inv private.tgg_call_validation_invites%rowtype;
  v_effective_status text;
  v_role text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  -- Prefer the newest claimed invite whose room is still active and where
  -- the signed-in user is one of the two legitimate participants. This
  -- prevents a newer pending invite from hiding an already-claimed room.
  select i.*
  into v_inv
  from private.tgg_call_validation_invites i
  join public.tgg_call_rooms r on r.id=i.room_id
  where i.status='claimed'
    and r.status='active'
    and r.ended_at is null
    and (i.inviter_user_id=v_uid or i.claimed_by_user_id=v_uid)
  order by i.claimed_at desc nulls last, i.created_at desc
  limit 1;

  if not found then
    -- No active claimed room: show the user's newest invite as before.
    select *
    into v_inv
    from private.tgg_call_validation_invites
    where inviter_user_id=v_uid
    order by created_at desc
    limit 1;
  end if;

  if not found then
    return jsonb_build_object(
      'ok',true,
      'has_invite',false,
      'status','none',
      'can_create',true,
      'current_user_role',null
    );
  end if;

  v_effective_status:=case
    when v_inv.status='pending' and v_inv.expires_at<=now() then 'expired'
    else v_inv.status
  end;

  v_role:=case
    when v_inv.inviter_user_id=v_uid then 'offerer'
    when v_inv.claimed_by_user_id=v_uid then 'responder'
    else null
  end;

  return jsonb_build_object(
    'ok',true,
    'has_invite',true,
    'invite_token',v_inv.invite_id,
    'status',v_effective_status,
    'expires_at',v_inv.expires_at,
    'claimed_at',v_inv.claimed_at,
    'completed_at',v_inv.completed_at,
    'conversation_id',v_inv.conversation_id,
    'room_id',v_inv.room_id,
    'can_create',v_effective_status in ('claimed','expired','completed'),
    'second_user_claimed',v_inv.claimed_by_user_id is not null,
    'current_user_role',v_role,
    'claim_url','https://trugogettamixtapes.blogspot.com/p/artist-dashboard_0633467215.html?join_validation_code=' || v_inv.invite_id::text
  );
end;
$function$;

-- ============================================================
-- MIGRATION 20260910094913 video_studio_bridge_api_v1
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

create or replace function public.tgg_video_studio_create_project(
  p_title text,
  p_description text default null,
  p_aspect_ratio text default '16:9'
)
returns jsonb
language plpgsql
set search_path to 'public','pg_catalog'
as $$
declare
  v_uid uuid := auth.uid();
  v_id uuid := gen_random_uuid();
  v_title text := btrim(coalesce(p_title,''));
  v_ratio text := btrim(coalesce(p_aspect_ratio,'16:9'));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(v_title) < 1 or char_length(v_title) > 160 then raise exception 'TITLE_INVALID'; end if;
  if v_ratio not in ('16:9','9:16','1:1','4:5') then raise exception 'ASPECT_RATIO_INVALID'; end if;

  insert into public.tgg_creative_projects(
    id,user_id,project_type,title,description,status,aspect_ratio,settings
  ) values (
    v_id,v_uid,'video',v_title,nullif(btrim(coalesce(p_description,'')),''),'draft',v_ratio,
    jsonb_build_object('schema_version',1,'workspace','video-studio','linked_studio_project_id',v_id)
  );

  insert into public.tgg_studio_projects(
    id,user_id,title,bpm,musical_key,status,project_data,project_type,description,revision,collaboration_enabled
  ) values (
    v_id,v_uid,v_title,120,null,'draft',
    jsonb_build_object('schema_version',1,'workspace','video-studio','linked_creative_project_id',v_id),
    'video',nullif(btrim(coalesce(p_description,'')),''),0,false
  );

  return jsonb_build_object(
    'ok',true,'project_id',v_id,'title',v_title,'project_type','video','aspect_ratio',v_ratio,'revision',0
  );
end;
$$;

create or replace function public.tgg_video_studio_bundle(p_project_id uuid default null)
returns jsonb
language plpgsql
stable
set search_path to 'public','pg_catalog'
as $$
declare
  v_uid uuid := auth.uid();
  v_project_id uuid := p_project_id;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  if v_project_id is null then
    select c.id into v_project_id
    from public.tgg_creative_projects c
    where c.user_id=v_uid and c.project_type='video'
    order by c.updated_at desc
    limit 1;
  elsif not exists (
    select 1 from public.tgg_creative_projects c
    where c.id=v_project_id and c.user_id=v_uid and c.project_type='video'
  ) then
    raise exception 'PROJECT_NOT_FOUND_OR_NOT_OWNED';
  end if;

  return jsonb_build_object(
    'ok',true,
    'selected_project_id',v_project_id,
    'projects',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.updated_at desc)
      from (
        select c.id,c.title,c.description,c.status,c.aspect_ratio,c.duration_seconds,c.settings,
               c.created_at,c.updated_at,coalesce(s.revision,0) revision,coalesce(s.collaboration_enabled,false) collaboration_enabled
        from public.tgg_creative_projects c
        left join public.tgg_studio_projects s on s.id=c.id and s.user_id=c.user_id
        where c.user_id=v_uid and c.project_type='video'
        order by c.updated_at desc
      ) x
    ),'[]'::jsonb),
    'project',case when v_project_id is null then null else (
      select to_jsonb(x) from (
        select c.id,c.title,c.description,c.status,c.aspect_ratio,c.duration_seconds,c.settings,
               c.created_at,c.updated_at,coalesce(s.revision,0) revision,coalesce(s.collaboration_enabled,false) collaboration_enabled
        from public.tgg_creative_projects c
        left join public.tgg_studio_projects s on s.id=c.id and s.user_id=c.user_id
        where c.id=v_project_id and c.user_id=v_uid and c.project_type='video'
      ) x
    ) end,
    'assets',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(a) order by a.created_at desc)
      from public.tgg_media_vault_assets a
      where a.project_id=v_project_id and a.user_id=v_uid
    ),'[]'::jsonb) end,
    'timeline',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(t) order by t.track_index,t.start_seconds,t.created_at)
      from public.tgg_video_timeline_items t
      where t.project_id=v_project_id and t.user_id=v_uid
    ),'[]'::jsonb) end,
    'render_jobs',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(r) order by r.created_at desc)
      from public.tgg_video_studio_render_jobs r
      where r.project_id=v_project_id and r.user_id=v_uid
    ),'[]'::jsonb) end,
    'render_outputs',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(o) order by o.created_at desc)
      from public.tgg_video_studio_render_outputs o
      join public.tgg_video_studio_render_jobs r on r.id=o.render_job_id
      where r.project_id=v_project_id and o.user_id=v_uid
    ),'[]'::jsonb) end,
    'publish_manifests',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(m) order by m.created_at desc)
      from public.tgg_video_studio_publish_manifests m
      where m.project_id=v_project_id and m.user_id=v_uid
    ),'[]'::jsonb) end,
    'members',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(m) order by m.joined_at)
      from public.tgg_studio_project_members m
      where m.project_id=v_project_id and m.left_at is null
    ),'[]'::jsonb) end,
    'presence',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(p) order by p.last_seen_at desc)
      from public.tgg_studio_project_presence p
      where p.project_id=v_project_id
    ),'[]'::jsonb) end,
    'generated_at',now()
  );
end;
$$;

create or replace function public.tgg_video_studio_add_timeline_item(
  p_project_id uuid,
  p_asset_id uuid default null,
  p_track_index integer default 0,
  p_item_type text default 'video',
  p_start_seconds numeric default 0,
  p_duration_seconds numeric default 0,
  p_source_in_seconds numeric default 0,
  p_settings jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
set search_path to 'public','pg_catalog'
as $$
declare
  v_uid uuid := auth.uid();
  v_item public.tgg_video_timeline_items;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if not exists(select 1 from public.tgg_creative_projects where id=p_project_id and user_id=v_uid and project_type='video') then raise exception 'PROJECT_NOT_FOUND_OR_NOT_OWNED'; end if;
  if p_track_index < 0 then raise exception 'TRACK_INDEX_INVALID'; end if;
  if p_item_type not in ('video','audio','image','text','caption','overlay') then raise exception 'ITEM_TYPE_INVALID'; end if;
  if coalesce(p_start_seconds,0)<0 or coalesce(p_duration_seconds,0)<0 or coalesce(p_source_in_seconds,0)<0 then raise exception 'TIME_INVALID'; end if;
  if p_asset_id is not null and not exists(select 1 from public.tgg_media_vault_assets where id=p_asset_id and project_id=p_project_id and user_id=v_uid) then raise exception 'ASSET_NOT_FOUND_OR_NOT_OWNED'; end if;

  insert into public.tgg_video_timeline_items(user_id,project_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings)
  values(v_uid,p_project_id,p_asset_id,p_track_index,p_item_type,coalesce(p_start_seconds,0),coalesce(p_duration_seconds,0),coalesce(p_source_in_seconds,0),coalesce(p_settings,'{}'::jsonb))
  returning * into v_item;

  update public.tgg_creative_projects set updated_at=now() where id=p_project_id and user_id=v_uid;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id and user_id=v_uid;
  return to_jsonb(v_item);
end;
$$;

create or replace function public.tgg_video_studio_update_timeline_item(p_item_id uuid,p_patch jsonb)
returns jsonb
language plpgsql
set search_path to 'public','pg_catalog'
as $$
declare
  v_uid uuid := auth.uid();
  v_item public.tgg_video_timeline_items;
  v_project_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select project_id into v_project_id from public.tgg_video_timeline_items where id=p_item_id and user_id=v_uid;
  if v_project_id is null then raise exception 'ITEM_NOT_FOUND_OR_NOT_OWNED'; end if;

  update public.tgg_video_timeline_items
  set track_index=case when p_patch ? 'track_index' then (p_patch->>'track_index')::integer else track_index end,
      start_seconds=case when p_patch ? 'start_seconds' then (p_patch->>'start_seconds')::numeric else start_seconds end,
      duration_seconds=case when p_patch ? 'duration_seconds' then (p_patch->>'duration_seconds')::numeric else duration_seconds end,
      source_in_seconds=case when p_patch ? 'source_in_seconds' then (p_patch->>'source_in_seconds')::numeric else source_in_seconds end,
      settings=case when p_patch ? 'settings' then coalesce(p_patch->'settings','{}'::jsonb) else settings end,
      updated_at=now()
  where id=p_item_id and user_id=v_uid
  returning * into v_item;

  update public.tgg_creative_projects set updated_at=now() where id=v_project_id and user_id=v_uid;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_project_id and user_id=v_uid;
  return to_jsonb(v_item);
end;
$$;

create or replace function public.tgg_video_studio_delete_timeline_item(p_item_id uuid)
returns jsonb
language plpgsql
set search_path to 'public','pg_catalog'
as $$
declare
  v_uid uuid := auth.uid();
  v_project_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select project_id into v_project_id from public.tgg_video_timeline_items where id=p_item_id and user_id=v_uid;
  if v_project_id is null then raise exception 'ITEM_NOT_FOUND_OR_NOT_OWNED'; end if;
  delete from public.tgg_video_timeline_items where id=p_item_id and user_id=v_uid;
  update public.tgg_creative_projects set updated_at=now() where id=v_project_id and user_id=v_uid;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_project_id and user_id=v_uid;
  return jsonb_build_object('ok',true,'item_id',p_item_id,'project_id',v_project_id);
end;
$$;

create or replace function public.tgg_video_studio_queue_render(
  p_project_id uuid,
  p_output_format text default 'mp4',
  p_output_preset text default '1080p',
  p_job_type text default 'master',
  p_request_payload jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
set search_path to 'public','pg_catalog'
as $$
declare
  v_uid uuid := auth.uid();
  v_job public.tgg_video_studio_render_jobs;
  v_revision bigint;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select revision into v_revision from public.tgg_studio_projects where id=p_project_id and user_id=v_uid and project_type='video';
  if not found then raise exception 'PROJECT_NOT_FOUND_OR_NOT_OWNED'; end if;
  if lower(btrim(coalesce(p_output_format,''))) not in ('mp4','webm','mov') then raise exception 'OUTPUT_FORMAT_INVALID'; end if;
  if lower(btrim(coalesce(p_job_type,''))) not in ('master','preview','short','social') then raise exception 'JOB_TYPE_INVALID'; end if;

  insert into public.tgg_video_studio_render_jobs(project_id,user_id,job_type,output_format,output_preset,source_revision,request_payload,status,progress)
  values(p_project_id,v_uid,lower(btrim(p_job_type)),lower(btrim(p_output_format)),btrim(coalesce(p_output_preset,'1080p')),coalesce(v_revision,0),coalesce(p_request_payload,'{}'::jsonb),'queued',0)
  returning * into v_job;
  return to_jsonb(v_job);
end;
$$;

