create or replace function tgg_private.video_studio_permission(p_project_id uuid)
returns jsonb
language sql
stable
security definer
set search_path to ''
as $$
  select case
    when s.id is null then null
    when s.user_id=auth.uid() then jsonb_build_object('allowed',true,'is_owner',true,'role','owner','can_edit',true,'can_record',true,'can_publish',true)
    when m.user_id is not null then jsonb_build_object('allowed',true,'is_owner',false,'role',m.role,'can_edit',m.can_edit,'can_record',m.can_record,'can_publish',m.can_publish)
    else jsonb_build_object('allowed',false,'is_owner',false,'role',null,'can_edit',false,'can_record',false,'can_publish',false)
  end
  from public.tgg_studio_projects s
  left join public.tgg_studio_project_members m
    on m.project_id=s.id and m.user_id=auth.uid() and m.left_at is null
  where s.id=p_project_id and s.project_type='video'
  limit 1;
$$;

revoke all on function tgg_private.video_studio_permission(uuid) from public;

create or replace function public.tgg_video_studio_create_project(
  p_title text,
  p_description text default null,
  p_aspect_ratio text default '16:9'
)
returns jsonb
language plpgsql
set search_path to 'public','pg_catalog'
as $$
declare
  v_uid uuid := auth.uid();
  v_id uuid := gen_random_uuid();
  v_title text := btrim(coalesce(p_title,''));
  v_ratio text := btrim(coalesce(p_aspect_ratio,'16:9'));
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if char_length(v_title) < 1 or char_length(v_title) > 160 then raise exception 'TITLE_INVALID'; end if;
  if v_ratio not in ('16:9','9:16','1:1','4:5') then raise exception 'ASPECT_RATIO_INVALID'; end if;

  insert into public.tgg_creative_projects(
    id,user_id,project_type,title,description,status,aspect_ratio,settings
  ) values (
    v_id,v_uid,'video',v_title,nullif(btrim(coalesce(p_description,'')),''),'draft',v_ratio,
    jsonb_build_object('schema_version',2,'workspace','video-studio','linked_studio_project_id',v_id)
  );

  insert into public.tgg_studio_projects(
    id,user_id,title,bpm,musical_key,status,project_data,project_type,description,revision,collaboration_enabled
  ) values (
    v_id,v_uid,v_title,120,null,'draft',
    jsonb_build_object('schema_version',2,'workspace','video-studio','linked_creative_project_id',v_id),
    'video',nullif(btrim(coalesce(p_description,'')),''),0,true
  );

  insert into public.tgg_studio_project_members(project_id,user_id,role,can_edit,can_record,can_publish,joined_at,left_at)
  values(v_id,v_uid,'owner',true,true,true,now(),null)
  on conflict(project_id,user_id) do update
    set role='owner',can_edit=true,can_record=true,can_publish=true,left_at=null;

  return jsonb_build_object(
    'ok',true,'project_id',v_id,'title',v_title,'project_type','video','aspect_ratio',v_ratio,'revision',0,
    'permission',jsonb_build_object('role','owner','can_edit',true,'can_record',true,'can_publish',true)
  );
end;
$$;

create or replace function public.tgg_video_studio_bundle(p_project_id uuid default null)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','tgg_private','pg_catalog'
as $$
declare
  v_uid uuid := auth.uid();
  v_project_id uuid := p_project_id;
  v_permission jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  if v_project_id is null then
    select c.id into v_project_id
    from public.tgg_creative_projects c
    join public.tgg_studio_projects s on s.id=c.id and s.project_type='video'
    left join public.tgg_studio_project_members m on m.project_id=s.id and m.user_id=v_uid and m.left_at is null
    where c.project_type='video' and (s.user_id=v_uid or m.user_id=v_uid)
    order by c.updated_at desc
    limit 1;
  else
    v_permission:=tgg_private.video_studio_permission(v_project_id);
    if not coalesce((v_permission->>'allowed')::boolean,false) then raise exception 'PROJECT_NOT_FOUND_OR_NOT_ACCESSIBLE'; end if;
  end if;

  if v_project_id is not null then v_permission:=tgg_private.video_studio_permission(v_project_id); end if;

  return jsonb_build_object(
    'ok',true,
    'selected_project_id',v_project_id,
    'permission',v_permission,
    'projects',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.updated_at desc)
      from (
        select c.id,c.title,c.description,c.status,c.aspect_ratio,c.duration_seconds,c.settings,
               c.created_at,c.updated_at,coalesce(s.revision,0) revision,coalesce(s.collaboration_enabled,false) collaboration_enabled,
               case when s.user_id=v_uid then 'owner' else m.role end role
        from public.tgg_creative_projects c
        join public.tgg_studio_projects s on s.id=c.id and s.project_type='video'
        left join public.tgg_studio_project_members m on m.project_id=s.id and m.user_id=v_uid and m.left_at is null
        where c.project_type='video' and (s.user_id=v_uid or m.user_id=v_uid)
        order by c.updated_at desc
      ) x
    ),'[]'::jsonb),
    'project',case when v_project_id is null then null else (
      select to_jsonb(x) from (
        select c.id,c.title,c.description,c.status,c.aspect_ratio,c.duration_seconds,c.settings,
               c.created_at,c.updated_at,coalesce(s.revision,0) revision,coalesce(s.collaboration_enabled,false) collaboration_enabled
        from public.tgg_creative_projects c join public.tgg_studio_projects s on s.id=c.id
        where c.id=v_project_id and c.project_type='video'
      ) x
    ) end,
    'assets',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(a) order by a.created_at desc) from public.tgg_media_vault_assets a where a.project_id=v_project_id
    ),'[]'::jsonb) end,
    'timeline',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(t) order by t.track_index,t.start_seconds,t.created_at) from public.tgg_video_timeline_items t where t.project_id=v_project_id
    ),'[]'::jsonb) end,
    'render_jobs',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(r) order by r.created_at desc) from public.tgg_video_studio_render_jobs r where r.project_id=v_project_id
    ),'[]'::jsonb) end,
    'render_outputs',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(o) order by o.created_at desc)
      from public.tgg_video_studio_render_outputs o join public.tgg_video_studio_render_jobs r on r.id=o.render_job_id
      where r.project_id=v_project_id
    ),'[]'::jsonb) end,
    'publish_manifests',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(m) order by m.created_at desc) from public.tgg_video_studio_publish_manifests m where m.project_id=v_project_id
    ),'[]'::jsonb) end,
    'members',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(m) order by m.joined_at) from public.tgg_studio_project_members m where m.project_id=v_project_id and m.left_at is null
    ),'[]'::jsonb) end,
    'presence',case when v_project_id is null then '[]'::jsonb else coalesce((
      select jsonb_agg(to_jsonb(p) order by p.last_seen_at desc) from public.tgg_studio_project_presence p where p.project_id=v_project_id
    ),'[]'::jsonb) end,
    'generated_at',now()
  );
end;
$$;

create or replace function public.tgg_video_studio_save_project_state(
  p_project_id uuid,
  p_title text,
  p_aspect_ratio text,
  p_editor_state jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path to 'public','tgg_private','pg_catalog'
as $$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_title text:=btrim(coalesce(p_title,''));
  v_ratio text:=btrim(coalesce(p_aspect_ratio,'16:9'));
  v_revision bigint;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if char_length(v_title)<1 or char_length(v_title)>160 then raise exception 'TITLE_INVALID'; end if;
  if v_ratio not in ('16:9','9:16','1:1','4:5') then raise exception 'ASPECT_RATIO_INVALID'; end if;
  if jsonb_typeof(coalesce(p_editor_state,'{}'::jsonb))<>'object' or octet_length(coalesce(p_editor_state,'{}'::jsonb)::text)>32768 then raise exception 'EDITOR_STATE_INVALID'; end if;

  update public.tgg_creative_projects
  set title=v_title,aspect_ratio=v_ratio,settings=coalesce(settings,'{}'::jsonb)||jsonb_build_object('schema_version',2,'workspace','video-studio','editor_state',coalesce(p_editor_state,'{}'::jsonb)),updated_at=now()
  where id=p_project_id and project_type='video';

  update public.tgg_studio_projects
  set title=v_title,project_data=coalesce(project_data,'{}'::jsonb)||jsonb_build_object('schema_version',2,'workspace','video-studio','video_editor_state',coalesce(p_editor_state,'{}'::jsonb)),revision=coalesce(revision,0)+1,updated_at=now()
  where id=p_project_id and project_type='video'
  returning revision into v_revision;

  return jsonb_build_object('ok',true,'project_id',p_project_id,'revision',v_revision,'saved_at',now());
end;
$$;

create or replace function public.tgg_video_studio_finalize_asset(
  p_project_id uuid,
  p_title text,
  p_storage_path text,
  p_mime_type text,
  p_file_size bigint,
  p_duration_seconds numeric default null,
  p_width integer default null,
  p_height integer default null,
  p_metadata jsonb default '{}'::jsonb
)
returns uuid
language plpgsql
security definer
set search_path to 'public','storage','tgg_private','pg_catalog'
as $$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_asset_id uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if p_storage_path is null or p_storage_path !~ ('^'||v_uid::text||'/video/') then raise exception 'INVALID_VIDEO_STORAGE_PATH'; end if;
  if p_mime_type is null or p_mime_type not like 'video/%' then raise exception 'VIDEO_MIME_REQUIRED'; end if;
  if coalesce(p_file_size,0)<=0 or p_file_size>524288000 then raise exception 'INVALID_FILE_SIZE'; end if;
  if p_duration_seconds is not null and (p_duration_seconds<0 or p_duration_seconds>86400) then raise exception 'INVALID_DURATION'; end if;
  if p_width is not null and (p_width<1 or p_width>16384) then raise exception 'INVALID_WIDTH'; end if;
  if p_height is not null and (p_height<1 or p_height>16384) then raise exception 'INVALID_HEIGHT'; end if;
  if jsonb_typeof(coalesce(p_metadata,'{}'::jsonb))<>'object' or octet_length(coalesce(p_metadata,'{}'::jsonb)::text)>16384 then raise exception 'METADATA_INVALID'; end if;
  if not exists(select 1 from public.tgg_pending_media_uploads p where p.user_id=v_uid and p.app_scope='video' and p.storage_bucket='creator-media' and p.storage_path=p_storage_path and p.status='pending') then raise exception 'PENDING_UPLOAD_REQUIRED'; end if;
  if not exists(select 1 from storage.objects o where o.bucket_id='creator-media' and o.name=p_storage_path and (storage.foldername(o.name))[1]=v_uid::text) then raise exception 'UPLOADED_STORAGE_OBJECT_NOT_FOUND'; end if;

  select a.id into v_asset_id from public.tgg_media_vault_assets a where a.project_id=p_project_id and a.storage_path=p_storage_path limit 1;
  if v_asset_id is null then
    insert into public.tgg_media_vault_assets(user_id,project_id,asset_type,title,source_kind,storage_path,mime_type,file_size_bytes,duration_seconds,width,height,metadata)
    values(v_uid,p_project_id,'video',btrim(coalesce(nullif(p_title,''),'Video clip')),'upload',p_storage_path,p_mime_type,p_file_size,p_duration_seconds,p_width,p_height,
      coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('secure_upload',true,'draft_media',true,'uploaded_by',v_uid,'collab_role',v_permission->>'role'))
    returning id into v_asset_id;
  end if;

  update public.tgg_pending_media_uploads set status='finalized',finalized_at=now()
  where user_id=v_uid and storage_bucket='creator-media' and storage_path=p_storage_path;
  return v_asset_id;
end;
$$;

create or replace function public.tgg_video_studio_add_timeline_item(
  p_project_id uuid,
  p_asset_id uuid default null,
  p_track_index integer default 0,
  p_item_type text default 'video',
  p_start_seconds numeric default 0,
  p_duration_seconds numeric default 0,
  p_source_in_seconds numeric default 0,
  p_settings jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path to 'public','tgg_private','pg_catalog'
as $$
declare
  v_uid uuid:=auth.uid(); v_permission jsonb; v_item public.tgg_video_timeline_items;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if p_track_index<0 then raise exception 'TRACK_INDEX_INVALID'; end if;
  if p_item_type not in ('video','audio','image','text','caption','overlay') then raise exception 'ITEM_TYPE_INVALID'; end if;
  if coalesce(p_start_seconds,0)<0 or coalesce(p_duration_seconds,0)<0 or coalesce(p_source_in_seconds,0)<0 then raise exception 'TIME_INVALID'; end if;
  if p_asset_id is not null and not exists(select 1 from public.tgg_media_vault_assets where id=p_asset_id and project_id=p_project_id) then raise exception 'ASSET_NOT_FOUND_IN_PROJECT'; end if;
  if jsonb_typeof(coalesce(p_settings,'{}'::jsonb))<>'object' then raise exception 'SETTINGS_INVALID'; end if;

  insert into public.tgg_video_timeline_items(user_id,project_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings)
  values(v_uid,p_project_id,p_asset_id,p_track_index,p_item_type,coalesce(p_start_seconds,0),coalesce(p_duration_seconds,0),coalesce(p_source_in_seconds,0),coalesce(p_settings,'{}'::jsonb)) returning * into v_item;
  update public.tgg_creative_projects set updated_at=now() where id=p_project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into strict p_track_index;
  return to_jsonb(v_item);
end;
$$;

create or replace function public.tgg_video_studio_update_timeline_item(p_item_id uuid,p_patch jsonb)
returns jsonb
language plpgsql
security definer
set search_path to 'public','tgg_private','pg_catalog'
as $$
declare
  v_uid uuid:=auth.uid(); v_item public.tgg_video_timeline_items; v_project_id uuid; v_permission jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select project_id into v_project_id from public.tgg_video_timeline_items where id=p_item_id;
  if v_project_id is null then raise exception 'ITEM_NOT_FOUND'; end if;
  v_permission:=tgg_private.video_studio_permission(v_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if jsonb_typeof(coalesce(p_patch,'{}'::jsonb))<>'object' then raise exception 'PATCH_INVALID'; end if;

  update public.tgg_video_timeline_items
  set track_index=case when p_patch?'track_index' then greatest(0,(p_patch->>'track_index')::integer) else track_index end,
      start_seconds=case when p_patch?'start_seconds' then greatest(0,(p_patch->>'start_seconds')::numeric) else start_seconds end,
      duration_seconds=case when p_patch?'duration_seconds' then greatest(0,(p_patch->>'duration_seconds')::numeric) else duration_seconds end,
      source_in_seconds=case when p_patch?'source_in_seconds' then greatest(0,(p_patch->>'source_in_seconds')::numeric) else source_in_seconds end,
      settings=case when p_patch?'settings' then coalesce(p_patch->'settings','{}'::jsonb) else settings end,
      updated_at=now()
  where id=p_item_id returning * into v_item;
  update public.tgg_creative_projects set updated_at=now() where id=v_project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_project_id;
  return to_jsonb(v_item);
end;
$$;

create or replace function public.tgg_video_studio_delete_timeline_item(p_item_id uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public','tgg_private','pg_catalog'
as $$
declare
  v_uid uuid:=auth.uid(); v_project_id uuid; v_permission jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select project_id into v_project_id from public.tgg_video_timeline_items where id=p_item_id;
  if v_project_id is null then raise exception 'ITEM_NOT_FOUND'; end if;
  v_permission:=tgg_private.video_studio_permission(v_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  delete from public.tgg_video_timeline_items where id=p_item_id;
  update public.tgg_creative_projects set updated_at=now() where id=v_project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_project_id;
  return jsonb_build_object('ok',true,'item_id',p_item_id,'project_id',v_project_id);
end;
$$;

create or replace function public.tgg_video_studio_queue_render(
  p_project_id uuid,
  p_output_format text default 'mp4',
  p_output_preset text default '1080p',
  p_job_type text default 'master',
  p_request_payload jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path to 'public','tgg_private','pg_catalog'
as $$
declare
  v_uid uuid:=auth.uid(); v_permission jsonb; v_job public.tgg_video_studio_render_jobs; v_revision bigint;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  select revision into v_revision from public.tgg_studio_projects where id=p_project_id and project_type='video';
  if lower(btrim(coalesce(p_output_format,''))) not in ('mp4','webm','mov') then raise exception 'OUTPUT_FORMAT_INVALID'; end if;
  if lower(btrim(coalesce(p_job_type,''))) not in ('master','preview','short','social') then raise exception 'JOB_TYPE_INVALID'; end if;
  insert into public.tgg_video_studio_render_jobs(project_id,user_id,job_type,output_format,output_preset,source_revision,request_payload,status,progress)
  values(p_project_id,v_uid,lower(btrim(p_job_type)),lower(btrim(p_output_format)),btrim(coalesce(p_output_preset,'1080p')),coalesce(v_revision,0),coalesce(p_request_payload,'{}'::jsonb),'queued',0) returning * into v_job;
  return to_jsonb(v_job);
end;
$$;

