alter table private.tgg_baseline_additive_allowances
  drop constraint if exists tgg_baseline_additive_allowances_object_kind_check;

alter table private.tgg_baseline_additive_allowances
  add constraint tgg_baseline_additive_allowances_object_kind_check
  check (object_kind = any(array['route_path'::text,'realtime_table'::text,'blogger_page_hash'::text]));

create or replace function public.tgg_effective_blogger_page_hashes()
returns jsonb
language sql
stable
security definer
set search_path to ''
as $$
  with b as (
    select version,coalesce(notes->'page_hashes','{}'::jsonb) as page_hashes
    from public.tgg_production_baselines
    where status='locked'
    order by locked_at desc
    limit 1
  ), o as (
    select coalesce(jsonb_object_agg(a.object_key,a.approved_contract->>'hash' order by a.object_key),'{}'::jsonb) as overrides
    from private.tgg_baseline_additive_allowances a
    join b on b.version=a.baseline_version
    where a.object_kind='blogger_page_hash'
      and a.active=true
      and a.approved_contract ? 'hash'
      and (a.approved_contract->>'hash') ~ '^[0-9a-f]{64}$'
  )
  select coalesce(b.page_hashes,'{}'::jsonb) || coalesce(o.overrides,'{}'::jsonb)
  from b cross join o;
$$;

revoke all on function public.tgg_effective_blogger_page_hashes() from public;
grant execute on function public.tgg_effective_blogger_page_hashes() to service_role;

