create or replace function public.tgg_video_studio_complete_browser_render(
  p_project_id uuid,
  p_job_id uuid,
  p_asset_id uuid,
  p_storage_path text,
  p_format text default 'webm',
  p_aspect_ratio text default '16:9',
  p_resolution text default null,
  p_duration_seconds numeric default null,
  p_metadata jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path to 'public','tgg_private','pg_catalog'
as $$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_job public.tgg_video_studio_render_jobs;
  v_output public.tgg_video_studio_render_outputs;
  v_format text:=lower(btrim(coalesce(p_format,'webm')));
  v_ratio text:=btrim(coalesce(p_aspect_ratio,'16:9'));
  v_is_owner boolean:=false;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  v_is_owner:=coalesce((v_permission->>'is_owner')::boolean,false);
  select * into v_job from public.tgg_video_studio_render_jobs where id=p_job_id and project_id=p_project_id;
  if v_job.id is null then raise exception 'RENDER_JOB_NOT_FOUND'; end if;
  if v_job.user_id<>v_uid and not v_is_owner then raise exception 'RENDER_JOB_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if v_job.status not in ('queued','processing') then raise exception 'RENDER_JOB_NOT_COMPLETABLE'; end if;
  if v_format not in ('webm','mp4','mov') then raise exception 'FORMAT_INVALID'; end if;
  if v_ratio not in ('16:9','9:16','1:1','4:5') then raise exception 'ASPECT_RATIO_INVALID'; end if;
  if p_storage_path is null or p_storage_path='' then raise exception 'STORAGE_PATH_REQUIRED'; end if;
  if p_duration_seconds is not null and (p_duration_seconds<0 or p_duration_seconds>86400) then raise exception 'DURATION_INVALID'; end if;
  if p_resolution is not null and char_length(p_resolution)>64 then raise exception 'RESOLUTION_INVALID'; end if;
  if jsonb_typeof(coalesce(p_metadata,'{}'::jsonb))<>'object' or octet_length(coalesce(p_metadata,'{}'::jsonb)::text)>16384 then raise exception 'METADATA_INVALID'; end if;
  if not exists(select 1 from public.tgg_media_vault_assets a where a.id=p_asset_id and a.project_id=p_project_id and a.storage_path=p_storage_path and a.asset_type='video') then raise exception 'RENDER_ASSET_NOT_FOUND_IN_PROJECT'; end if;

  update public.tgg_video_studio_render_jobs
  set status='ready',progress=100,started_at=coalesce(started_at,now()),finished_at=now(),updated_at=now(),error_message=null,
      result_payload=coalesce(result_payload,'{}'::jsonb)||jsonb_build_object('mode','browser_export','asset_id',p_asset_id,'storage_path',p_storage_path,'format',v_format,'aspect_ratio',v_ratio,'resolution',p_resolution,'duration_seconds',p_duration_seconds,'completed_by',v_uid,'completed_at',now())
  where id=p_job_id and project_id=p_project_id
  returning * into v_job;

  select * into v_output from public.tgg_video_studio_render_outputs where render_job_id=p_job_id order by created_at desc limit 1;
  if v_output.id is null then
    insert into public.tgg_video_studio_render_outputs(render_job_id,user_id,format,aspect_ratio,resolution,duration_seconds,storage_path,public_url,status,metadata,created_at,updated_at)
    values(p_job_id,v_uid,v_format,v_ratio,p_resolution,p_duration_seconds,p_storage_path,null,'ready',coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('mode','browser_export','asset_id',p_asset_id,'project_id',p_project_id),now(),now())
    returning * into v_output;
  else
    update public.tgg_video_studio_render_outputs
    set user_id=v_uid,format=v_format,aspect_ratio=v_ratio,resolution=p_resolution,duration_seconds=p_duration_seconds,storage_path=p_storage_path,public_url=null,status='ready',metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('mode','browser_export','asset_id',p_asset_id,'project_id',p_project_id),updated_at=now()
    where id=v_output.id returning * into v_output;
  end if;
  return jsonb_build_object('ok',true,'project_id',p_project_id,'job',to_jsonb(v_job),'output',to_jsonb(v_output));
end;
$$;
revoke all on function public.tgg_video_studio_complete_browser_render(uuid,uuid,uuid,text,text,text,text,numeric,jsonb) from public;
grant execute on function public.tgg_video_studio_complete_browser_render(uuid,uuid,uuid,text,text,text,text,numeric,jsonb) to authenticated;

