 insert into public.tgg_world_mission_evidence(user_id,player_mission_id,evidence_type,source_table,source_id,source_key,payload,verified,verified_at) values(v_uid,v_pm.id,p_evidence_type,p_source_table,p_source_id,p_source_key,coalesce(p_payload,'{}'::jsonb),true,now()) on conflict do nothing returning id into v_evidence_id;
 update public.tgg_world_player_missions set status='evidence_pending',evidence=evidence||jsonb_build_array(jsonb_build_object('evidence_type',p_evidence_type,'source_table',p_source_table,'source_id',p_source_id,'source_key',p_source_key)),progress=greatest(progress,1),updated_at=now() where id=v_pm.id and status not in ('completed','rewarded');
 return jsonb_build_object('ok',true,'mission_code',p_mission_code,'evidence_id',v_evidence_id,'verified',true); end $$;

create or replace function public.tgg_world_v4_verify_and_complete_mission(p_mission_code text) returns jsonb language plpgsql security definer set search_path=public,auth as $$
declare v_uid uuid:=auth.uid(); v_mission public.tgg_world_missions; v_pm public.tgg_world_player_missions; v_count integer; begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 select * into v_mission from public.tgg_world_missions where code=p_mission_code and active=true; if v_mission.id is null then raise exception 'MISSION_NOT_FOUND'; end if;
 select * into v_pm from public.tgg_world_player_missions where user_id=v_uid and mission_id=v_mission.id; if v_pm.id is null then raise exception 'MISSION_NOT_ACCEPTED'; end if;
 select count(*) into v_count from public.tgg_world_mission_evidence where player_mission_id=v_pm.id and user_id=v_uid and verified=true and evidence_type=v_mission.objective_type;
 if v_count < v_mission.objective_target then raise exception 'MISSION_EVIDENCE_INCOMPLETE'; end if;
 return public.tgg_world_mvp_v1_complete_mission(p_mission_code,jsonb_build_object('verified_evidence_count',v_count,'objective_type',v_mission.objective_type)); end $$;

create or replace function public.tgg_world_v8_mark_session_launch_opened(p_launch_id uuid) returns jsonb language plpgsql security definer set search_path=public,auth as $$
declare v_uid uuid:=auth.uid(); v_rows integer:=0; begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 update public.tgg_world_session_launches set status=case when status='requested' then 'opened' else status end,updated_at=now() where id=p_launch_id and user_id=v_uid and status in ('requested','opened'); get diagnostics v_rows=row_count; return jsonb_build_object('ok',v_rows=1,'launch_id',p_launch_id); end $$;

