create or replace function public.tgg_world_v10_mark_session_launch_saved(
  p_launch_id uuid,
  p_project_id uuid,
  p_session_id uuid,
  p_artifact_id uuid default null,
  p_save_payload jsonb default '{}'::jsonb
)
returns public.tgg_world_session_launches
language plpgsql
security definer
set search_path=public,auth
as $$
declare
  v_uid uuid:=auth.uid();
  v_row public.tgg_world_session_launches;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  if p_launch_id is null or p_project_id is null or p_session_id is null then
    raise exception 'LAUNCH_PROJECT_SESSION_REQUIRED';
  end if;

  select *
  into v_row
  from public.tgg_world_session_launches
  where id=p_launch_id
    and user_id=v_uid
  for update;

  if v_row.id is null then
    raise exception 'SESSION_LAUNCH_NOT_FOUND';
  end if;

  if v_row.status not in ('requested','opened','active','saved') then
    raise exception 'INVALID_SESSION_SAVE_TRANSITION';
  end if;

  if v_row.project_id is not null and v_row.project_id<>p_project_id then
    raise exception 'PROJECT_ID_MISMATCH';
  end if;

  if v_row.session_id is not null and v_row.session_id<>p_session_id then
    raise exception 'SESSION_ID_MISMATCH';
  end if;

  update public.tgg_world_session_launches
  set project_id=p_project_id,
      session_id=p_session_id,
      status='saved',
      handoff_payload=
        coalesce(handoff_payload,'{}'::jsonb)
        || jsonb_strip_nulls(
             jsonb_build_object(
               'artifact_id',p_artifact_id,
               'creator_session_saved',true,
               'creator_session_saved_at',now()
             )
           )
        || coalesce(p_save_payload,'{}'::jsonb),
      updated_at=now()
  where id=p_launch_id
    and user_id=v_uid
  returning * into v_row;

  update public.tgg_world_players
  set state='active',
      updated_at=now(),
      last_seen_at=now()
  where user_id=v_uid;

  return v_row;
end;
$$;

revoke all on function public.tgg_world_v10_mark_session_launch_saved(uuid,uuid,uuid,uuid,jsonb) from public;
