create or replace function public.tgg_world_v4_accept_offer(p_offer_id uuid) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare v_uid uuid:=auth.uid();v_offer public.tgg_world_contact_offers;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select * into v_offer from public.tgg_world_contact_offers where id=p_offer_id and user_id=v_uid for update;if v_offer.id is null then raise exception 'OFFER_NOT_FOUND';end if;if v_offer.status<>'pending' then raise exception 'OFFER_NOT_PENDING';end if;if v_offer.expires_at is not null and v_offer.expires_at<now() then update public.tgg_world_contact_offers set status='expired',responded_at=now() where id=v_offer.id;raise exception 'OFFER_EXPIRED';end if;update public.tgg_world_contact_offers set status='accepted',responded_at=now() where id=v_offer.id;insert into public.tgg_world_contact_messages(user_id,contact_id,direction,message_type,body,payload) values(v_uid,v_offer.contact_id,'system','offer','Offer accepted: '||v_offer.title,jsonb_build_object('offer_id',v_offer.id,'offer_type',v_offer.offer_type));insert into public.tgg_world_notifications(user_id,notification_type,title,body,action_type,action_payload,priority) values(v_uid,case when v_offer.offer_type='show_booking' then 'calendar' else 'contact' end,'Offer accepted',v_offer.title,case when v_offer.project_id is not null then 'resume' else 'open' end,jsonb_build_object('offer_id',v_offer.id,'project_id',v_offer.project_id,'session_id',v_offer.session_id),'normal');return jsonb_build_object('ok',true,'offer_id',v_offer.id,'status','accepted');end $$;
