_world_property_upgrade_ledger(user_id,property_id,upgrade_key,grant_key,credit_cost,status) values(v_uid,p_property_id,p_upgrade_key,v_grant_key,v_upgrade.credit_cost,'granted') on conflict(grant_key) do nothing;get diagnostics v_inserted=row_count;if v_inserted=1 then update public.tgg_world_wallets_v10 set credits=credits-v_upgrade.credit_cost,updated_at=now() where user_id=v_uid;insert into public.tgg_world_property_upgrades_v10(property_id,upgrade_key,owner_user_id) values(p_property_id,p_upgrade_key,v_uid) on conflict(property_id,upgrade_key) do nothing;update public.tgg_world_properties set upgrades=upgrades||jsonb_build_object(p_upgrade_key,jsonb_build_object('installed_at',now(),'effects',v_upgrade.effects)),updated_at=now() where id=p_property_id;end if;return jsonb_build_object('ok',true,'property_id',p_property_id,'upgrade_key',p_upgrade_key,'new_grant',v_inserted=1,'credit_cost',v_upgrade.credit_cost);end $$;
create or replace function public.tgg_world_v4_record_mission_evidence(p_mission_code text,p_evidence_type text,p_source_table text default null,p_source_id uuid default null,p_source_key text default null,p_payload jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare v_uid uuid:=auth.uid();v_mission public.tgg_world_missions;v_pm public.tgg_world_player_missions;v_evidence_id uuid;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select * into v_mission from public.tgg_world_missions where code=p_mission_code and active=true;if v_mission.id is null then raise exception 'MISSION_NOT_FOUND';end if;select * into v_pm from public.tgg_world_player_missions where user_id=v_uid and mission_id=v_mission.id;if v_pm.id is null then raise exception 'MISSION_NOT_ACCEPTED';end if;insert into public.tgg_world_mission_evidence(user_id,player_mission_id,evidence_type,source_table,source_id,source_key,payload,verified,verified_at) values(v_uid,v_pm.id,p_evidence_type,p_source_table,p_source_id,p_source_key,coalesce(p_payload,'{}'::jsonb),true,now()) on conflict do nothing returning id into v_evidence_id;update public.tgg_world_player_missions set status='evidence_pending',evidence=evidence||jsonb_build_array(jsonb_build_object('evidence_type',p_evidence_type,'source_table',p_source_table,'source_id',p_source_id,'source_key',p_source_key)),progress=greatest(progress,1),updated_at=now() where id=v_pm.id and status not in('completed','rewarded');return jsonb_build_object('ok',true,'mission_code',p_mission_code,'evidence_id',v_evidence_id,'verified',true);end $$;
create or replace function public.tgg_world_v4_verify_and_complete_mission(p_mission_code text) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare v_uid uuid:=auth.uid();v_mission public.tgg_world_missions;v_pm public.tgg_world_player_missions;v_count integer;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select * into v_mission from public.tgg_world_missions where code=p_mission_code and active=true;if v_mission.id is null then raise exception 'MISSION_NOT_FOUND';end if;select * into v_pm from public.tgg_world_player_missions where user_id=v_uid and mission_id=v_mission.id;if v_pm.id is null then raise exception 'MISSION_NOT_ACCEPTED';end if;select count(*) into v_count from public.tgg_world_mission_evidence where player_mission_id=v_pm.id and user_id=v_uid and verified=true and evidence_type=v_mission.objective_type;if v_count<v_mission.objective_target then raise exception 'MISSION_EVIDENCE_INCOMPLETE';end if;return public.tgg_world_mvp_v1_complete_mission(p_mission_code,jsonb_build_object('verified_evidence_count',v_count,'objective_type',v_mission.objective_type));end $$;
create or replace function public.tgg_world_v4_start_crew_mission(p_crew_id uuid,p_mission_code text,p_project_id uuid default null,p_session_id uuid default null) returns public.tgg_world_crew_missions language plpgsql security definer set search_path=public,auth as $$ declare v_uid uuid:=auth.uid();v_mission_id uuid;v_row public.tgg_world_crew_missions;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;if not exists(select 1 from public.tgg_world_crew_members_v10 where crew_id=p_crew_id and user_id=v_uid and status='active') then raise exception 'CREW_MEMBERSHIP_REQUIRED';end if;select id into v_mission_id from public.tgg_world_missions where code=p_mission_code and active=true;if v_mission_id is null then raise exception 'MISSION_NOT_FOUND';end if;insert into public.tgg_world_crew_missions(crew_id,mission_id,status,accepted_by,project_id,session_id,accepted_at) values(p_crew_id,v_mission_id,'in_progress',v_uid,p_project_id,p_session_id,now()) on conflict(crew_id,mission_id) do update set status='in_progress',project_id=coalesce(excluded.project_id,tgg_world_crew_missions.project_id),session_id=coalesce(excluded.session_id,tgg_world_crew_missions.session_id),updated_at=now() returning * into v_row;insert into public.tgg_world_crew_mission_members(crew_mission_id,user_id) values(v_row.id,v_uid) on conflict do nothing;return v_row;end $$;
create or replace function public.tgg_world_v4_verify_crew_mission(p_crew_mission_id uuid) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare v_uid uuid:=auth.uid();v_cm public.tgg_world_crew_missions;v_distinct integer;v_required integer:=2;begin if v_uid is null then raise exception 'AUTH_REQUIRED';end if;select * into v_cm from public.tgg_world_crew_missions where id=p_crew_mission_id for update;if v_cm.id is null then raise exception 'CREW_MISSION_NOT_FOUND';end if;if not exists(select 1 from public.tgg_world_crew_members_v10 where crew_id=v_cm.crew_id and user_id=v_uid and status='active') then raise exception 'CREW_MEMBERSHIP_REQUIRED';end if;select count(distinct user_id) into v_distinct from public.tgg_world_crew_mission_members where crew_mission_id=v_cm.id and verified=true;if v_distinct<v_required then return jsonb_build_object('ok',false,'status','evidence_pending','verified_members',v_distinct,'required_members',v_required);end if;update public.tgg_world_crew_missions set status='completed',completed_at=coalesce(completed_at,now()),updated_at=now() where id=v_cm.id;return jsonb_build_object('ok',true,'status','completed','crew_mission_id',v_cm.id,'verified_members',v_distinct);end $$;

