create table if not exists public.tgg_video_studio_social_publications (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.tgg_creative_projects(id) on delete cascade,
  output_id uuid not null references public.tgg_video_studio_repurpose_outputs(id) on delete cascade,
  user_id uuid not null,
  destination_type text not null check (destination_type in ('short','story')),
  destination_id uuid,
  public_key uuid not null default gen_random_uuid(),
  storage_path text not null,
  status text not null default 'pending' check (status in ('pending','active','revoked','failed')),
  expires_at timestamptz,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(public_key),
  unique(output_id,destination_type)
);

create index if not exists idx_tgg_video_social_publications_project on public.tgg_video_studio_social_publications(project_id);
create index if not exists idx_tgg_video_social_publications_user on public.tgg_video_studio_social_publications(user_id);
create index if not exists idx_tgg_video_social_publications_destination on public.tgg_video_studio_social_publications(destination_type,destination_id);
create index if not exists idx_tgg_video_social_publications_active_key on public.tgg_video_studio_social_publications(public_key) where status='active';

alter table public.tgg_video_studio_social_publications enable row level security;
revoke all on table public.tgg_video_studio_social_publications from anon, authenticated;

create or replace function public.tgg_video_studio_publish_output(
  p_project_id uuid,
  p_output_id uuid,
  p_destination text,
  p_caption text default null,
  p_visibility text default 'public'
)
returns jsonb
language plpgsql
security definer
set search_path to 'public','tgg_private','pg_catalog'
as $$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_dest text:=lower(btrim(coalesce(p_destination,'')));
  v_visibility text:=lower(btrim(coalesce(nullif(p_visibility,''),'public')));
  v_output public.tgg_video_studio_repurpose_outputs;
  v_job public.tgg_content_repurpose_jobs;
  v_pub public.tgg_video_studio_social_publications;
  v_media public.tgg_media_vault_assets;
  v_url text;
  v_result jsonb;
  v_destination_id uuid;
  v_expires timestamptz;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_publish')::boolean,false) then raise exception 'PUBLISH_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if v_dest not in ('short','story') then raise exception 'DESTINATION_INVALID'; end if;
  if v_visibility not in ('public','unlisted','private') then raise exception 'VISIBILITY_INVALID'; end if;
  if p_caption is not null and char_length(p_caption)>2000 then raise exception 'CAPTION_TOO_LONG'; end if;

  select o.* into v_output
  from public.tgg_video_studio_repurpose_outputs o
  join public.tgg_content_repurpose_jobs j on j.id=o.job_id
  where o.id=p_output_id and j.project_id=p_project_id and o.status='ready' and j.status='ready';
  if v_output.id is null then raise exception 'READY_OUTPUT_NOT_FOUND_IN_PROJECT'; end if;

  select * into v_job from public.tgg_content_repurpose_jobs where id=v_output.job_id and project_id=p_project_id;
  if v_output.storage_path is null or btrim(v_output.storage_path)='' then raise exception 'OUTPUT_STORAGE_PATH_REQUIRED'; end if;

  select * into v_media
  from public.tgg_media_vault_assets a
  where a.project_id=p_project_id
    and a.storage_path=v_output.storage_path
    and a.asset_type='video'
  order by a.created_at desc
  limit 1;
  if v_media.id is null then raise exception 'OUTPUT_MEDIA_ASSET_NOT_FOUND'; end if;

  select * into v_pub
  from public.tgg_video_studio_social_publications
  where output_id=p_output_id and destination_type=v_dest
  for update;

  if v_pub.id is not null and v_pub.status='active' and v_pub.destination_id is not null then
    return jsonb_build_object('ok',true,'already_published',true,'publication_id',v_pub.id,'destination_type',v_pub.destination_type,'destination_id',v_pub.destination_id,'public_url','https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-public-video-output?key='||v_pub.public_key::text,'expires_at',v_pub.expires_at);
  end if;

  if v_pub.id is null then
    insert into public.tgg_video_studio_social_publications(project_id,output_id,user_id,destination_type,storage_path,status,metadata)
    values(p_project_id,p_output_id,v_uid,v_dest,v_output.storage_path,'pending',jsonb_build_object('output_type',v_output.output_type,'asset_id',v_media.id,'source','video-studio'))
    returning * into v_pub;
  else
    update public.tgg_video_studio_social_publications
    set user_id=v_uid,project_id=p_project_id,storage_path=v_output.storage_path,status='pending',destination_id=null,expires_at=null,public_key=gen_random_uuid(),updated_at=now(),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('asset_id',v_media.id,'republished_at',now())
    where id=v_pub.id
    returning * into v_pub;
  end if;

  v_url:='https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-public-video-output?key='||v_pub.public_key::text;

  begin
    if v_dest='short' then
      v_result:=public.tgg_short_create_draft(
        coalesce(nullif(btrim(coalesce(p_caption,'')),''),v_output.caption,v_output.title),
        v_url,
        null,
        null,
        v_visibility,
        v_job.duration_seconds
      );
      v_destination_id:=(v_result->>'short_id')::uuid;
      perform public.tgg_short_set_published(v_destination_id,true);
      v_expires:=null;
    else
      v_result:=public.tgg_story_create(
        'video',
        coalesce(nullif(btrim(coalesce(p_caption,'')),''),v_output.caption,v_output.title),
        v_url,
        null
      );
      v_destination_id:=(v_result->>'story_id')::uuid;
      v_expires:=(v_result->>'expires_at')::timestamptz;
    end if;

    update public.tgg_video_studio_social_publications
    set destination_id=v_destination_id,status='active',expires_at=v_expires,updated_at=now(),metadata=metadata||jsonb_build_object('published_at',now(),'visibility',v_visibility)
    where id=v_pub.id
    returning * into v_pub;

    insert into public.tgg_video_publish_jobs(project_id,user_id,destination_type,destination_id,payload,status,error_message,published_at,created_at,updated_at)
    values(p_project_id,v_uid,v_dest,v_destination_id,jsonb_build_object('output_id',p_output_id,'publication_id',v_pub.id,'public_url',v_url,'output_type',v_output.output_type),'published',null,now(),now(),now());
  exception when others then
    update public.tgg_video_studio_social_publications
    set status='failed',metadata=metadata||jsonb_build_object('last_error',sqlerrm,'failed_at',now()),updated_at=now()
    where id=v_pub.id;
    raise;
  end;

  return jsonb_build_object('ok',true,'already_published',false,'publication_id',v_pub.id,'destination_type',v_dest,'destination_id',v_destination_id,'public_url',v_url,'expires_at',v_expires);
end;
$$;

create or replace function public.tgg_video_studio_revoke_output_publication(
  p_project_id uuid,
  p_publication_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path to 'public','tgg_private','pg_catalog'
as $$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_pub public.tgg_video_studio_social_publications;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_publish')::boolean,false) then raise exception 'PUBLISH_PERMISSION_REQUIRED' using errcode='42501'; end if;
  select * into v_pub from public.tgg_video_studio_social_publications where id=p_publication_id and project_id=p_project_id for update;
  if v_pub.id is null then raise exception 'PUBLICATION_NOT_FOUND'; end if;

  if v_pub.destination_type='short' and v_pub.destination_id is not null then
    perform public.tgg_short_set_published(v_pub.destination_id,false);
  elsif v_pub.destination_type='story' and v_pub.destination_id is not null then
    perform public.tgg_story_delete(v_pub.destination_id);
  end if;

  update public.tgg_video_studio_social_publications set status='revoked',updated_at=now(),metadata=metadata||jsonb_build_object('revoked_at',now(),'revoked_by',v_uid) where id=v_pub.id;
  return jsonb_build_object('ok',true,'publication_id',v_pub.id,'status','revoked');
end;
$$;

create or replace function public.tgg_video_studio_output_library(p_project_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public','tgg_private','pg_catalog'
as $$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'allowed')::boolean,false) then raise exception 'PROJECT_NOT_FOUND_OR_NOT_ACCESSIBLE' using errcode='42501'; end if;
  return jsonb_build_object(
    'ok',true,
    'project_id',p_project_id,
    'permission',v_permission,
    'outputs',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',o.id,'job_id',o.job_id,'output_type',o.output_type,'title',o.title,'caption',o.caption,'storage_path',o.storage_path,'metadata',o.metadata,'status',o.status,'created_at',o.created_at,
        'job',jsonb_build_object('aspect_ratio',j.aspect_ratio,'duration_seconds',j.duration_seconds,'status',j.status),
        'asset_id',(select a.id from public.tgg_media_vault_assets a where a.project_id=p_project_id and a.storage_path=o.storage_path and a.asset_type='video' order by a.created_at desc limit 1),
        'publications',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'destination_type',p.destination_type,'destination_id',p.destination_id,'status',p.status,'expires_at',p.expires_at,'public_url','https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-public-video-output?key='||p.public_key::text) order by p.created_at desc) from public.tgg_video_studio_social_publications p where p.output_id=o.id),'[]'::jsonb)
      ) order by o.created_at desc)
      from public.tgg_video_studio_repurpose_outputs o
      join public.tgg_content_repurpose_jobs j on j.id=o.job_id
      where j.project_id=p_project_id and o.status='ready'
    ),'[]'::jsonb),
    'generated_at',now()
  );
end;
$$;

revoke all on function public.tgg_video_studio_publish_output(uuid,uuid,text,text,text) from public;
revoke all on function public.tgg_video_studio_revoke_output_publication(uuid,uuid) from public;
revoke all on function public.tgg_video_studio_output_library(uuid) from public;
grant execute on function public.tgg_video_studio_publish_output(uuid,uuid,text,text,text) to authenticated;
grant execute on function public.tgg_video_studio_revoke_output_publication(uuid,uuid) to authenticated;
grant execute on function public.tgg_video_studio_output_library(uuid) to authenticated;

