 elsif p_evidence_type='live_event' then v_verified:=exists(select 1 from public.tgg_world_events e where e.id=coalesce(v_event_id,p_source_id) and e.status='completed' and(e.host_user_id=v_uid or exists(select 1 from public.tgg_world_event_participants ep where ep.event_id=e.id and ep.user_id=v_uid)));
 else v_verified:=false;end if;
