create or replace function public.tgg_video_studio_publish_output(
  p_project_id uuid,
  p_output_id uuid,
  p_destination text,
  p_caption text default null,
  p_visibility text default 'public'
)
returns jsonb
language plpgsql
security definer
set search_path to 'public','tgg_private','pg_catalog'
as $function$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_dest text:=lower(btrim(coalesce(p_destination,'')));
  v_audit_dest text;
  v_visibility text:=lower(btrim(coalesce(nullif(p_visibility,''),'public')));
  v_output public.tgg_video_studio_repurpose_outputs;
  v_job public.tgg_content_repurpose_jobs;
  v_pub public.tgg_video_studio_social_publications;
  v_media public.tgg_media_vault_assets;
  v_url text;
  v_result jsonb;
  v_destination_id uuid;
  v_expires timestamptz;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_publish')::boolean,false) then raise exception 'PUBLISH_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if v_dest not in ('short','story') then raise exception 'DESTINATION_INVALID'; end if;
  v_audit_dest:=case v_dest when 'short' then 'shorts' when 'story' then 'stories' end;
  if v_visibility not in ('public','unlisted','private') then raise exception 'VISIBILITY_INVALID'; end if;
  if p_caption is not null and char_length(p_caption)>2000 then raise exception 'CAPTION_TOO_LONG'; end if;

  select o.* into v_output
  from public.tgg_video_studio_repurpose_outputs o
  join public.tgg_content_repurpose_jobs j on j.id=o.job_id
  where o.id=p_output_id and j.project_id=p_project_id and o.status='ready' and j.status='ready';
  if v_output.id is null then raise exception 'READY_OUTPUT_NOT_FOUND_IN_PROJECT'; end if;

  select * into v_job from public.tgg_content_repurpose_jobs where id=v_output.job_id and project_id=p_project_id;
  if v_output.storage_path is null or btrim(v_output.storage_path)='' then raise exception 'OUTPUT_STORAGE_PATH_REQUIRED'; end if;

  select * into v_media
  from public.tgg_media_vault_assets a
  where a.project_id=p_project_id
    and a.storage_path=v_output.storage_path
    and a.asset_type='video'
  order by a.created_at desc
  limit 1;
  if v_media.id is null then raise exception 'OUTPUT_MEDIA_ASSET_NOT_FOUND'; end if;

  select * into v_pub
  from public.tgg_video_studio_social_publications
  where output_id=p_output_id and destination_type=v_dest
  for update;

  if v_pub.id is not null and v_pub.status='active' and v_pub.destination_id is not null then
    return jsonb_build_object('ok',true,'already_published',true,'publication_id',v_pub.id,'destination_type',v_pub.destination_type,'destination_id',v_pub.destination_id,'public_url','https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-media-operations?public_output=1&key='||v_pub.public_key::text,'expires_at',v_pub.expires_at);
  end if;

  if v_pub.id is null then
    insert into public.tgg_video_studio_social_publications(project_id,output_id,user_id,destination_type,storage_path,status,metadata)
    values(p_project_id,p_output_id,v_uid,v_dest,v_output.storage_path,'pending',jsonb_build_object('output_type',v_output.output_type,'asset_id',v_media.id,'source','video-studio'))
    returning * into v_pub;
  else
    update public.tgg_video_studio_social_publications
    set user_id=v_uid,project_id=p_project_id,storage_path=v_output.storage_path,status='pending',destination_id=null,expires_at=null,public_key=gen_random_uuid(),updated_at=now(),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('asset_id',v_media.id,'republished_at',now())
    where id=v_pub.id
    returning * into v_pub;
  end if;

  v_url:='https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-media-operations?public_output=1&key='||v_pub.public_key::text;

  begin
    if v_dest='short' then
      v_result:=public.tgg_short_create_draft(
        coalesce(nullif(btrim(coalesce(p_caption,'')),''),v_output.caption,v_output.title),
        v_url,
        null,
        null,
        v_visibility,
        v_job.duration_seconds
      );
      v_destination_id:=(v_result->>'short_id')::uuid;
      perform public.tgg_short_set_published(v_destination_id,true);
      v_expires:=null;
    else
      v_result:=public.tgg_story_create(
        'video',
        coalesce(nullif(btrim(coalesce(p_caption,'')),''),v_output.caption,v_output.title),
        v_url,
        null
      );
      v_destination_id:=(v_result->>'story_id')::uuid;
      v_expires:=(v_result->>'expires_at')::timestamptz;
    end if;

    update public.tgg_video_studio_social_publications
    set destination_id=v_destination_id,status='active',expires_at=v_expires,updated_at=now(),metadata=metadata||jsonb_build_object('published_at',now(),'visibility',v_visibility)
    where id=v_pub.id
    returning * into v_pub;

    insert into public.tgg_video_publish_jobs(project_id,user_id,destination_type,destination_id,payload,status,error_message,published_at,created_at,updated_at)
    values(p_project_id,v_uid,v_audit_dest,v_destination_id,jsonb_build_object('output_id',p_output_id,'publication_id',v_pub.id,'public_url',v_url,'output_type',v_output.output_type),'published',null,now(),now(),now());
  exception when others then
    update public.tgg_video_studio_social_publications
    set status='failed',metadata=metadata||jsonb_build_object('last_error',sqlerrm,'failed_at',now()),updated_at=now()
    where id=v_pub.id;
    raise;
  end;

  return jsonb_build_object('ok',true,'already_published',false,'publication_id',v_pub.id,'destination_type',v_dest,'destination_id',v_destination_id,'public_url',v_url,'expires_at',v_expires);
end;
$function$;


