begin;

create table if not exists public.tgg_video_studio_caption_cues (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.tgg_studio_projects(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  timeline_item_id uuid references public.tgg_video_timeline_items(id) on delete set null,
  track_index integer not null default 0 check (track_index >= 0),
  start_seconds numeric not null default 0 check (start_seconds >= 0),
  end_seconds numeric not null check (end_seconds > start_seconds),
  cue_type text not null default 'caption' check (cue_type in ('caption','subtitle','lyric','title','lower_third')),
  text text not null check (char_length(text) between 1 and 4000),
  speaker text,
  language_code text not null default 'en',
  style jsonb not null default '{}'::jsonb,
  position jsonb not null default '{}'::jsonb,
  auto_generated boolean not null default false,
  confidence numeric,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.tgg_video_studio_markers (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.tgg_studio_projects(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  timeline_item_id uuid references public.tgg_video_timeline_items(id) on delete set null,
  time_seconds numeric not null default 0 check (time_seconds >= 0),
  marker_type text not null default 'marker' check (marker_type in ('marker','chapter','beat','comment','sync','in','out')),
  label text not null default '',
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.tgg_video_studio_transition_instances (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.tgg_studio_projects(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  transition_catalog_id uuid not null references public.tgg_video_studio_transition_catalog(id),
  from_item_id uuid not null references public.tgg_video_timeline_items(id) on delete cascade,
  to_item_id uuid not null references public.tgg_video_timeline_items(id) on delete cascade,
  duration_seconds numeric not null default 0.35 check (duration_seconds > 0 and duration_seconds <= 10),
  settings jsonb not null default '{}'::jsonb,
  enabled boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (from_item_id <> to_item_id)
);

create index if not exists tgg_video_caption_project_time_idx on public.tgg_video_studio_caption_cues(project_id,start_seconds,end_seconds);
create index if not exists tgg_video_marker_project_time_idx on public.tgg_video_studio_markers(project_id,time_seconds);
create index if not exists tgg_video_transition_project_idx on public.tgg_video_studio_transition_instances(project_id,created_at);

alter table public.tgg_video_studio_caption_cues enable row level security;
alter table public.tgg_video_studio_markers enable row level security;
alter table public.tgg_video_studio_transition_instances enable row level security;

