drop policy if exists tgg_video_transition_owner on public.tgg_video_studio_transition_instances;
create policy tgg_video_transition_owner on public.tgg_video_studio_transition_instances for all to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid());

