from (values
 ('YouTube 16:9','export','social',jsonb_build_object('aspect_ratio','16:9','resolution','1080p','fps',30,'video_bitrate_mbps',12,'audio_kbps',320)),
 ('Shorts + Reels 9:16','export','social',jsonb_build_object('aspect_ratio','9:16','resolution','1080x1920','fps',30,'video_bitrate_mbps',10,'audio_kbps',256)),
 ('Square Social 1:1','export','social',jsonb_build_object('aspect_ratio','1:1','resolution','1080x1080','fps',30,'video_bitrate_mbps',10,'audio_kbps',256)),
 ('Feed Portrait 4:5','export','social',jsonb_build_object('aspect_ratio','4:5','resolution','1080x1350','fps',30,'video_bitrate_mbps',10,'audio_kbps',256)),
 ('4K Master','export','master',jsonb_build_object('aspect_ratio','16:9','resolution','2160p','fps',30,'video_bitrate_mbps',45,'audio_kbps',320)),
 ('Music Video Clean','look','music_video',jsonb_build_object('contrast',1.04,'saturation',1.05,'sharpness',0.08,'grain',0.02)),
 ('Performance Cut','look','music_video',jsonb_build_object('cut_style','beat','transition_default','hard_cut','punch_in',0.04)),
 ('Lyric Video','layout','music_video',jsonb_build_object('caption_mode','lyrics','caption_position','center','safe_area',true)),
 ('Podcast Clip','layout','social',jsonb_build_object('caption_mode','word_highlight','caption_position','lower','auto_reframe',true)),
 ('Cinematic','look','film',jsonb_build_object('contrast',1.08,'saturation',0.92,'grain',0.05,'letterbox',false))
) as v(name,preset_type,category,settings)
where not exists (select 1 from public.tgg_video_studio_presets p where p.user_id is null and p.name=v.name);

create or replace function public.tgg_video_studio_split_timeline_item(p_item_id uuid,p_split_at_seconds numeric)
returns jsonb language plpgsql security definer set search_path='public','tgg_private','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_item public.tgg_video_timeline_items; v_new public.tgg_video_timeline_items; v_perm jsonb; v_left numeric; v_end numeric; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into v_item from public.tgg_video_timeline_items where id=p_item_id;
 if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
 v_perm:=tgg_private.video_studio_permission(v_item.project_id);
 if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 v_end:=v_item.start_seconds+v_item.duration_seconds;
 if p_split_at_seconds<=v_item.start_seconds or p_split_at_seconds>=v_end then raise exception 'SPLIT_OUTSIDE_CLIP'; end if;
 v_left:=p_split_at_seconds-v_item.start_seconds;
 update public.tgg_video_timeline_items set duration_seconds=v_left,updated_at=now() where id=v_item.id;
 insert into public.tgg_video_timeline_items(project_id,user_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings)
 values(v_item.project_id,v_uid,v_item.asset_id,v_item.track_index,v_item.item_type,p_split_at_seconds,v_end-p_split_at_seconds,v_item.source_in_seconds+v_left,v_item.settings)
 returning * into v_new;
 insert into public.tgg_video_studio_effect_instances(project_id,timeline_item_id,user_id,effect_catalog_id,effect_type,stack_order,start_seconds,duration_seconds,settings,enabled)
 select project_id,v_new.id,v_uid,effect_catalog_id,effect_type,stack_order,start_seconds,duration_seconds,settings,enabled from public.tgg_video_studio_effect_instances where timeline_item_id=v_item.id;
 update public.tgg_video_studio_keyframes set timeline_item_id=v_new.id,user_id=v_uid,time_seconds=time_seconds-v_left,updated_at=now() where timeline_item_id=v_item.id and time_seconds>=v_left;
 insert into public.tgg_video_studio_timeline_actions(project_id,user_id,action_type,target_item_id,start_seconds,duration_seconds,action,source,status)
 values(v_item.project_id,v_uid,'split',v_item.id,p_split_at_seconds,v_item.duration_seconds,jsonb_build_object('left_item_id',v_item.id,'right_item_id',v_new.id),'manual','applied');
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_item.project_id returning revision into v_rev;
 update public.tgg_creative_projects set updated_at=now() where id=v_item.project_id;
 return jsonb_build_object('ok',true,'left_item',(select to_jsonb(t) from public.tgg_video_timeline_items t where t.id=v_item.id),'right_item',to_jsonb(v_new),'project_revision',v_rev);
end$$;

create or replace function public.tgg_video_studio_duplicate_timeline_item(p_item_id uuid,p_offset_seconds numeric default 0.25)
returns jsonb language plpgsql security definer set search_path='public','tgg_private','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_item public.tgg_video_timeline_items; v_new public.tgg_video_timeline_items; v_perm jsonb; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into v_item from public.tgg_video_timeline_items where id=p_item_id;
 if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
 v_perm:=tgg_private.video_studio_permission(v_item.project_id);
 if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 insert into public.tgg_video_timeline_items(project_id,user_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings)
 values(v_item.project_id,v_uid,v_item.asset_id,v_item.track_index,v_item.item_type,greatest(0,v_item.start_seconds+v_item.duration_seconds+coalesce(p_offset_seconds,0.25)),v_item.duration_seconds,v_item.source_in_seconds,v_item.settings)
 returning * into v_new;
 insert into public.tgg_video_studio_effect_instances(project_id,timeline_item_id,user_id,effect_catalog_id,effect_type,stack_order,start_seconds,duration_seconds,settings,enabled)
 select project_id,v_new.id,v_uid,effect_catalog_id,effect_type,stack_order,start_seconds,duration_seconds,settings,enabled from public.tgg_video_studio_effect_instances where timeline_item_id=v_item.id;
 insert into public.tgg_video_studio_keyframes(project_id,timeline_item_id,user_id,parameter,time_seconds,value,easing)
 select project_id,v_new.id,v_uid,parameter,time_seconds,value,easing from public.tgg_video_studio_keyframes where timeline_item_id=v_item.id;
 insert into public.tgg_video_studio_timeline_actions(project_id,user_id,action_type,target_item_id,start_seconds,duration_seconds,action,source,status)
 values(v_item.project_id,v_uid,'duplicate',v_new.id,v_new.start_seconds,v_new.duration_seconds,jsonb_build_object('source_item_id',v_item.id),'manual','applied');
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_item.project_id returning revision into v_rev;
 update public.tgg_creative_projects set updated_at=now() where id=v_item.project_id;
 return to_jsonb(v_new)||jsonb_build_object('ok',true,'project_revision',v_rev);
end$$;

create or replace function public.tgg_video_studio_apply_effect(p_project_id uuid,p_timeline_item_id uuid,p_effect_catalog_id uuid,p_settings jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path='public','tgg_private','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_perm jsonb; v_fx public.tgg_video_studio_fx_catalog; v_row public.tgg_video_studio_effect_instances; v_order int; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 v_perm:=tgg_private.video_studio_permission(p_project_id); if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 if not exists(select 1 from public.tgg_video_timeline_items where id=p_timeline_item_id and project_id=p_project_id) then raise exception 'ITEM_NOT_FOUND'; end if;
 select * into v_fx from public.tgg_video_studio_fx_catalog where id=p_effect_catalog_id and enabled=true; if v_fx.id is null then raise exception 'EFFECT_NOT_FOUND'; end if;
 select coalesce(max(stack_order),-1)+1 into v_order from public.tgg_video_studio_effect_instances where timeline_item_id=p_timeline_item_id;
 insert into public.tgg_video_studio_effect_instances(project_id,timeline_item_id,user_id,effect_catalog_id,effect_type,stack_order,settings,enabled)
 values(p_project_id,p_timeline_item_id,v_uid,v_fx.id,v_fx.effect_type,v_order,coalesce(p_settings,'{}'::jsonb),true) returning * into v_row;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_rev;
 return to_jsonb(v_row)||jsonb_build_object('project_revision',v_rev);
end$$;

create or replace function public.tgg_video_studio_remove_effect(p_effect_instance_id uuid)
returns jsonb language plpgsql security definer set search_path='public','tgg_private','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_pid uuid; v_perm jsonb; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select project_id into v_pid from public.tgg_video_studio_effect_instances where id=p_effect_instance_id; if v_pid is null then raise exception 'EFFECT_INSTANCE_NOT_FOUND'; end if;
 v_perm:=tgg_private.video_studio_permission(v_pid); if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 delete from public.tgg_video_studio_effect_instances where id=p_effect_instance_id;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_pid returning revision into v_rev;
 return jsonb_build_object('ok',true,'project_revision',v_rev);
end$$;

create or replace function public.tgg_video_studio_apply_transition(p_project_id uuid,p_from_item_id uuid,p_to_item_id uuid,p_transition_catalog_id uuid,p_duration_seconds numeric default 0.35,p_settings jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path='public','tgg_private','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_perm jsonb; v_row public.tgg_video_studio_transition_instances; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 v_perm:=tgg_private.video_studio_permission(p_project_id); if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 if p_from_item_id=p_to_item_id then raise exception 'TRANSITION_ITEMS_MUST_DIFFER'; end if;
 if (select count(*) from public.tgg_video_timeline_items where project_id=p_project_id and id in (p_from_item_id,p_to_item_id))<>2 then raise exception 'TRANSITION_ITEMS_INVALID'; end if;
 if not exists(select 1 from public.tgg_video_studio_transition_catalog where id=p_transition_catalog_id and enabled=true) then raise exception 'TRANSITION_NOT_FOUND'; end if;
 insert into public.tgg_video_studio_transition_instances(project_id,user_id,transition_catalog_id,from_item_id,to_item_id,duration_seconds,settings)
 values(p_project_id,v_uid,p_transition_catalog_id,p_from_item_id,p_to_item_id,least(10,greatest(0.05,coalesce(p_duration_seconds,0.35))),coalesce(p_settings,'{}'::jsonb)) returning * into v_row;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_rev;
 return to_jsonb(v_row)||jsonb_build_object('project_revision',v_rev);
end$$;

create or replace function public.tgg_video_studio_upsert_caption(p_project_id uuid,p_caption_id uuid,p_start_seconds numeric,p_end_seconds numeric,p_text text,p_track_index integer default 0,p_cue_type text default 'caption',p_style jsonb default '{}'::jsonb,p_language_code text default 'en',p_speaker text default null,p_timeline_item_id uuid default null)
returns jsonb language plpgsql security definer set search_path='public','tgg_private','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_perm jsonb; v_row public.tgg_video_studio_caption_cues; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 v_perm:=tgg_private.video_studio_permission(p_project_id); if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 if coalesce(p_start_seconds,-1)<0 or coalesce(p_end_seconds,0)<=coalesce(p_start_seconds,-1) then raise exception 'CAPTION_TIME_INVALID'; end if;
 if nullif(btrim(coalesce(p_text,'')),'') is null then raise exception 'CAPTION_TEXT_REQUIRED'; end if;
 if p_caption_id is null then
  insert into public.tgg_video_studio_caption_cues(project_id,user_id,timeline_item_id,track_index,start_seconds,end_seconds,cue_type,text,speaker,language_code,style)
  values(p_project_id,v_uid,p_timeline_item_id,greatest(0,coalesce(p_track_index,0)),p_start_seconds,p_end_seconds,coalesce(p_cue_type,'caption'),p_text,nullif(btrim(coalesce(p_speaker,'')),''),coalesce(nullif(p_language_code,''),'en'),coalesce(p_style,'{}'::jsonb)) returning * into v_row;
 else
  update public.tgg_video_studio_caption_cues set timeline_item_id=p_timeline_item_id,track_index=greatest(0,coalesce(p_track_index,track_index)),start_seconds=p_start_seconds,end_seconds=p_end_seconds,cue_type=coalesce(p_cue_type,cue_type),text=p_text,speaker=nullif(btrim(coalesce(p_speaker,'')),''),language_code=coalesce(nullif(p_language_code,''),language_code),style=coalesce(p_style,style),updated_at=now() where id=p_caption_id and project_id=p_project_id returning * into v_row;
  if v_row.id is null then raise exception 'CAPTION_NOT_FOUND'; end if;
 end if;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_rev;
 return to_jsonb(v_row)||jsonb_build_object('project_revision',v_rev);
end$$;

create or replace function public.tgg_video_studio_delete_caption(p_caption_id uuid)
returns jsonb language plpgsql security definer set search_path='public','tgg_private','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_pid uuid; v_perm jsonb; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select project_id into v_pid from public.tgg_video_studio_caption_cues where id=p_caption_id; if v_pid is null then raise exception 'CAPTION_NOT_FOUND'; end if;
 v_perm:=tgg_private.video_studio_permission(v_pid); if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 delete from public.tgg_video_studio_caption_cues where id=p_caption_id;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_pid returning revision into v_rev;
 return jsonb_build_object('ok',true,'project_revision',v_rev);
end$$;

create or replace function public.tgg_video_studio_upsert_marker(p_project_id uuid,p_marker_id uuid,p_time_seconds numeric,p_label text default '',p_marker_type text default 'marker',p_metadata jsonb default '{}'::jsonb,p_timeline_item_id uuid default null)
returns jsonb language plpgsql security definer set search_path='public','tgg_private','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_perm jsonb; v_row public.tgg_video_studio_markers; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 v_perm:=tgg_private.video_studio_permission(p_project_id); if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 if coalesce(p_time_seconds,-1)<0 then raise exception 'MARKER_TIME_INVALID'; end if;
 if p_marker_id is null then insert into public.tgg_video_studio_markers(project_id,user_id,timeline_item_id,time_seconds,marker_type,label,metadata) values(p_project_id,v_uid,p_timeline_item_id,p_time_seconds,coalesce(p_marker_type,'marker'),coalesce(p_label,''),coalesce(p_metadata,'{}'::jsonb)) returning * into v_row;
 else update public.tgg_video_studio_markers set timeline_item_id=p_timeline_item_id,time_seconds=p_time_seconds,marker_type=coalesce(p_marker_type,marker_type),label=coalesce(p_label,label),metadata=coalesce(p_metadata,metadata),updated_at=now() where id=p_marker_id and project_id=p_project_id returning * into v_row; if v_row.id is null then raise exception 'MARKER_NOT_FOUND'; end if; end if;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_rev;
 return to_jsonb(v_row)||jsonb_build_object('project_revision',v_rev);
end$$;

create or replace function public.tgg_video_studio_set_keyframe(p_project_id uuid,p_timeline_item_id uuid,p_parameter text,p_time_seconds numeric,p_value jsonb,p_easing text default 'linear')
returns jsonb language plpgsql security definer set search_path='public','tgg_private','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_perm jsonb; v_row public.tgg_video_studio_keyframes; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 v_perm:=tgg_private.video_studio_permission(p_project_id); if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 if not exists(select 1 from public.tgg_video_timeline_items where id=p_timeline_item_id and project_id=p_project_id) then raise exception 'ITEM_NOT_FOUND'; end if;
 if nullif(btrim(coalesce(p_parameter,'')),'') is null or coalesce(p_time_seconds,-1)<0 then raise exception 'KEYFRAME_INVALID'; end if;
 delete from public.tgg_video_studio_keyframes where project_id=p_project_id and timeline_item_id=p_timeline_item_id and parameter=p_parameter and time_seconds=p_time_seconds;
 insert into public.tgg_video_studio_keyframes(project_id,timeline_item_id,user_id,parameter,time_seconds,value,easing) values(p_project_id,p_timeline_item_id,v_uid,p_parameter,p_time_seconds,coalesce(p_value,'{}'::jsonb),coalesce(nullif(p_easing,''),'linear')) returning * into v_row;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_rev;
 return to_jsonb(v_row)||jsonb_build_object('project_revision',v_rev);
end$$;

create or replace function public.tgg_video_studio_delete_keyframe(p_keyframe_id uuid)
returns jsonb language plpgsql security definer set search_path='public','tgg_private','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_pid uuid; v_perm jsonb; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select project_id into v_pid from public.tgg_video_studio_keyframes where id=p_keyframe_id; if v_pid is null then raise exception 'KEYFRAME_NOT_FOUND'; end if;
 v_perm:=tgg_private.video_studio_permission(v_pid); if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 delete from public.tgg_video_studio_keyframes where id=p_keyframe_id;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_pid returning revision into v_rev;
 return jsonb_build_object('ok',true,'project_revision',v_rev);
end$$;

create or replace function public.tgg_studio_save_version(p_project_id uuid,p_label text default null)
returns uuid language plpgsql security definer set search_path='public','tgg_private','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_perm jsonb; v_next integer; v_id uuid; v_snapshot jsonb;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 v_perm:=tgg_private.video_studio_permission(p_project_id);
 if coalesce((v_perm->>'allowed')::boolean,false) then
   if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 elsif not exists(select 1 from public.tgg_studio_projects p where p.id=p_project_id and p.user_id=v_uid) then raise exception 'PROJECT_NOT_FOUND'; end if;
 select coalesce(max(version_number),0)+1 into v_next from public.tgg_studio_versions where project_id=p_project_id;
 select jsonb_build_object(
  'project',to_jsonb(p),
  'creative_project',(select to_jsonb(c) from public.tgg_creative_projects c where c.id=p_project_id),
  'patterns',coalesce((select jsonb_agg(to_jsonb(bp) order by bp.updated_at) from public.tgg_beat_patterns bp where bp.project_id=p_project_id),'[]'::jsonb),
  'assets',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at) from public.tgg_studio_assets a where a.project_id=p_project_id),'[]'::jsonb),
  'sessions',coalesce((select jsonb_agg(to_jsonb(s) order by s.created_at) from public.tgg_recording_sessions s where s.project_id=p_project_id),'[]'::jsonb),
  'takes',coalesce((select jsonb_agg(to_jsonb(t) order by t.created_at) from public.tgg_recording_takes t where t.project_id=p_project_id),'[]'::jsonb),
  'timeline_items',coalesce((select jsonb_agg(to_jsonb(t) order by t.track_index,t.start_seconds,t.created_at) from public.tgg_video_timeline_items t where t.project_id=p_project_id),'[]'::jsonb),
  'effects',coalesce((select jsonb_agg(to_jsonb(e) order by e.stack_order,e.created_at) from public.tgg_video_studio_effect_instances e where e.project_id=p_project_id),'[]'::jsonb),
  'keyframes',coalesce((select jsonb_agg(to_jsonb(k) order by k.time_seconds,k.created_at) from public.tgg_video_studio_keyframes k where k.project_id=p_project_id),'[]'::jsonb),
  'captions',coalesce((select jsonb_agg(to_jsonb(cu) order by cu.start_seconds,cu.created_at) from public.tgg_video_studio_caption_cues cu where cu.project_id=p_project_id),'[]'::jsonb),
  'markers',coalesce((select jsonb_agg(to_jsonb(m) order by m.time_seconds,m.created_at) from public.tgg_video_studio_markers m where m.project_id=p_project_id),'[]'::jsonb),
  'transitions',coalesce((select jsonb_agg(to_jsonb(tr) order by tr.created_at) from public.tgg_video_studio_transition_instances tr where tr.project_id=p_project_id),'[]'::jsonb),
  'schema_version',3
 ) into v_snapshot from public.tgg_studio_projects p where p.id=p_project_id;
 insert into public.tgg_studio_versions(project_id,user_id,version_number,label,snapshot) values(p_project_id,v_uid,v_next,nullif(btrim(coalesce(p_label,'')),''),v_snapshot) returning id into v_id;
 return v_id;
end$$;

create or replace function public.tgg_video_studio_restore_version(p_project_id uuid,p_version_id uuid)
returns jsonb language plpgsql security definer set search_path='public','tgg_private','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_perm jsonb; v_snap jsonb; v_rev bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 v_perm:=tgg_private.video_studio_permission(p_project_id); if not coalesce((v_perm->>'is_owner')::boolean,false) then raise exception 'OWNER_REQUIRED' using errcode='42501'; end if;
 select snapshot into v_snap from public.tgg_studio_versions where id=p_version_id and project_id=p_project_id; if v_snap is null then raise exception 'VERSION_NOT_FOUND'; end if;
 delete from public.tgg_video_studio_keyframes where project_id=p_project_id;
 delete from public.tgg_video_studio_effect_instances where project_id=p_project_id;
 delete from public.tgg_video_studio_transition_instances where project_id=p_project_id;
 delete from public.tgg_video_studio_caption_cues where project_id=p_project_id;
 delete from public.tgg_video_studio_markers where project_id=p_project_id;
 delete from public.tgg_video_timeline_items where project_id=p_project_id;
 if jsonb_typeof(v_snap->'timeline_items')='array' then insert into public.tgg_video_timeline_items select * from jsonb_populate_recordset(null::public.tgg_video_timeline_items,v_snap->'timeline_items'); end if;
 if jsonb_typeof(v_snap->'effects')='array' then insert into public.tgg_video_studio_effect_instances select * from jsonb_populate_recordset(null::public.tgg_video_studio_effect_instances,v_snap->'effects'); end if;
 if jsonb_typeof(v_snap->'keyframes')='array' then insert into public.tgg_video_studio_keyframes select * from jsonb_populate_recordset(null::public.tgg_video_studio_keyframes,v_snap->'keyframes'); end if;
 if jsonb_typeof(v_snap->'captions')='array' then insert into public.tgg_video_studio_caption_cues select * from jsonb_populate_recordset(null::public.tgg_video_studio_caption_cues,v_snap->'captions'); end if;
 if jsonb_typeof(v_snap->'markers')='array' then insert into public.tgg_video_studio_markers select * from jsonb_populate_recordset(null::public.tgg_video_studio_markers,v_snap->'markers'); end if;
 if jsonb_typeof(v_snap->'transitions')='array' then insert into public.tgg_video_studio_transition_instances select * from jsonb_populate_recordset(null::public.tgg_video_studio_transition_instances,v_snap->'transitions'); end if;
 if v_snap?'creative_project' then update public.tgg_creative_projects set title=coalesce(v_snap->'creative_project'->>'title',title),description=v_snap->'creative_project'->>'description',status=coalesce(v_snap->'creative_project'->>'status',status),aspect_ratio=v_snap->'creative_project'->>'aspect_ratio',duration_seconds=nullif(v_snap->'creative_project'->>'duration_seconds','')::numeric,settings=coalesce(v_snap->'creative_project'->'settings',settings),updated_at=now() where id=p_project_id; end if;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_rev;
 return jsonb_build_object('ok',true,'project_id',p_project_id,'version_id',p_version_id,'project_revision',v_rev);
end$$;

create or replace function public.tgg_video_studio_editor_bundle(p_project_id uuid default null)
returns jsonb language plpgsql stable security definer set search_path='public','tgg_private','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_base jsonb; v_pid uuid; v_perm jsonb;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 v_base:=public.tgg_video_studio_bundle(p_project_id); v_pid:=nullif(v_base->>'selected_project_id','')::uuid;
 if v_pid is not null then v_perm:=tgg_private.video_studio_permission(v_pid); end if;
 return v_base||jsonb_build_object(
  'editor_schema_version',3,
  'capabilities',jsonb_build_object('split',true,'duplicate',true,'trim',true,'layers',true,'effects',true,'transitions',true,'keyframes',true,'captions',true,'markers',true,'snapshots',true,'restore',coalesce((v_perm->>'is_owner')::boolean,false),'collaboration',true,'render',true,'publishing',true),
  'effects',case when v_pid is null then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(e) order by e.stack_order,e.created_at) from public.tgg_video_studio_effect_instances e where e.project_id=v_pid),'[]'::jsonb) end,
  'keyframes',case when v_pid is null then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(k) order by k.timeline_item_id,k.time_seconds) from public.tgg_video_studio_keyframes k where k.project_id=v_pid),'[]'::jsonb) end,
  'captions',case when v_pid is null then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(c) order by c.start_seconds,c.track_index) from public.tgg_video_studio_caption_cues c where c.project_id=v_pid),'[]'::jsonb) end,
  'markers',case when v_pid is null then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(m) order by m.time_seconds) from public.tgg_video_studio_markers m where m.project_id=v_pid),'[]'::jsonb) end,
  'transitions',case when v_pid is null then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(t) order by t.created_at) from public.tgg_video_studio_transition_instances t where t.project_id=v_pid),'[]'::jsonb) end,
  'versions',case when v_pid is null then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('id',v.id,'version_number',v.version_number,'label',v.label,'created_at',v.created_at,'user_id',v.user_id) order by v.version_number desc) from public.tgg_studio_versions v where v.project_id=v_pid limit 50),'[]'::jsonb) end,
  'fx_catalog',coalesce((select jsonb_agg(to_jsonb(f) order by f.sort_order,f.name) from public.tgg_video_studio_fx_catalog f where f.enabled=true),'[]'::jsonb),
  'transition_catalog',coalesce((select jsonb_agg(to_jsonb(t) order by t.sort_order,t.name) from public.tgg_video_studio_transition_catalog t where t.enabled=true),'[]'::jsonb),
  'presets',coalesce((select jsonb_agg(to_jsonb(p) order by p.category,p.name) from public.tgg_video_studio_presets p where p.enabled=true and (p.is_public=true or p.user_id=v_uid)),'[]'::jsonb)
 );
end$$;

