create or replace function public.tgg_world_v10_creator_session_saved(
  p_launch_id uuid,
  p_project_id uuid,
  p_session_id uuid,
  p_artifact_id uuid default null,
  p_tool text default null,
  p_payload jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path=public,auth
as $$
declare
  v_uid uuid := auth.uid();
  v_launch public.tgg_world_session_launches;
  v_mission public.tgg_world_missions;
  v_evidence jsonb := null;
  v_completion jsonb := null;
  v_evidence_type text := null;
  v_tool text := null;
  v_proven boolean := false;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_launch_id is null or p_project_id is null or p_session_id is null then raise exception 'LAUNCH_PROJECT_SESSION_REQUIRED'; end if;

  select * into v_launch from public.tgg_world_session_launches where id=p_launch_id and user_id=v_uid for update;
  if v_launch.id is null then raise exception 'SESSION_LAUNCH_NOT_FOUND'; end if;
  if v_launch.status not in ('requested','opened','active','saved') then raise exception 'INVALID_SESSION_SAVE_TRANSITION'; end if;
  if v_launch.project_id is not null and v_launch.project_id<>p_project_id then raise exception 'PROJECT_ID_MISMATCH'; end if;
  if v_launch.session_id is not null and v_launch.session_id<>p_session_id then raise exception 'SESSION_ID_MISMATCH'; end if;

  v_tool := coalesce(p_tool, v_launch.requested_tool);
  if v_tool not in ('recording','beat','video') then raise exception 'UNSUPPORTED_AUTHORITATIVE_SAVE_TOOL'; end if;

  if v_tool='recording' then
    if to_regclass('public.tgg_studio_versions') is null or to_regclass('public.tgg_studio_projects') is null then raise exception 'CREATOR_PROVENANCE_TABLE_MISSING'; end if;
    execute $sql$
      select exists(
        select 1 from public.tgg_studio_versions sv
        join public.tgg_studio_projects sp on sp.id=sv.project_id
        where sv.id=$1 and sv.project_id=$2 and sv.user_id=$3 and sp.user_id=$3
      )
    $sql$ into v_proven using p_session_id,p_project_id,v_uid;
  elsif v_tool='beat' then
    if to_regclass('public.tgg_beat_patterns') is null or to_regclass('public.tgg_studio_projects') is null then raise exception 'CREATOR_PROVENANCE_TABLE_MISSING'; end if;
    execute $sql$
      select exists(
        select 1 from public.tgg_beat_patterns bp
        join public.tgg_studio_projects sp on sp.id=bp.project_id
        where bp.id=$1 and bp.project_id=$2 and bp.user_id=$3 and sp.user_id=$3
      )
    $sql$ into v_proven using p_session_id,p_project_id,v_uid;
  elsif v_tool='video' then
    if to_regclass('public.tgg_creative_versions') is null or to_regclass('public.tgg_creative_projects') is null then raise exception 'CREATOR_PROVENANCE_TABLE_MISSING'; end if;
    execute $sql$
      select exists(
        select 1 from public.tgg_creative_versions cv
        join public.tgg_creative_projects cp on cp.id=cv.project_id
        where cv.id=$1 and cv.project_id=$2 and cp.user_id=$3
      )
    $sql$ into v_proven using p_session_id,p_project_id,v_uid;
  end if;

  if not coalesce(v_proven,false) then raise exception 'CREATOR_SESSION_PROVENANCE_NOT_PROVEN'; end if;

  update public.tgg_world_session_launches
  set project_id=p_project_id,
      session_id=p_session_id,
      status='saved',
      handoff_payload=coalesce(handoff_payload,'{}'::jsonb)
        || jsonb_strip_nulls(jsonb_build_object('artifact_id',p_artifact_id,'creator_session_saved',true,'creator_session_saved_at',now(),'tool',v_tool,'creator_session_provenance_verified',true))
        || coalesce(p_payload,'{}'::jsonb),
      updated_at=now()
  where id=p_launch_id and user_id=v_uid
  returning * into v_launch;

  update public.tgg_world_players set state='active',updated_at=now(),last_seen_at=now() where user_id=v_uid;

  if v_launch.mission_id is not null then
    select * into v_mission from public.tgg_world_missions where id=v_launch.mission_id and active=true;
    if v_mission.id is not null then
      v_evidence_type:=v_mission.objective_type;
      v_evidence:=public.tgg_world_v4_record_mission_evidence(
        v_mission.code,v_evidence_type,'tgg_world_session_launches',v_launch.id,
        concat_ws(':',p_project_id::text,p_session_id::text,p_artifact_id::text),
        jsonb_strip_nulls(jsonb_build_object('project_id',p_project_id,'session_id',p_session_id,'artifact_id',p_artifact_id,'launch_id',v_launch.id,'tool',v_tool,'creator_session_provenance_verified',true)) || coalesce(p_payload,'{}'::jsonb)
      );
      if coalesce((v_evidence->>'verified')::boolean,false) then
        begin
          v_completion:=public.tgg_world_v4_verify_and_complete_mission(v_mission.code);
        exception when others then
          if sqlerrm <> 'MISSION_EVIDENCE_INCOMPLETE' then raise; end if;
        end;
      end if;
    end if;
  end if;

  return jsonb_build_object('ok',true,'launch_id',v_launch.id,'project_id',v_launch.project_id,'session_id',v_launch.session_id,'status',v_launch.status,'tool',v_tool,'creator_session_provenance_verified',true,'mission_code',v_mission.code,'evidence_type',v_evidence_type,'evidence',v_evidence,'completion',v_completion);
end;
$$;

revoke all on function public.tgg_world_v10_creator_session_saved(uuid,uuid,uuid,uuid,text,jsonb) from public;
