 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select project_id into v_pid from public.tgg_video_studio_markers where id=p_marker_id;
 if v_pid is null then raise exception 'MARKER_NOT_FOUND'; end if;
 v_perm:=tgg_private.video_studio_permission(v_pid);
 if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 delete from public.tgg_video_studio_markers where id=p_marker_id;
 update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_pid returning revision into v_rev;
 return jsonb_build_object('ok',true,'project_revision',v_rev);
end$$;

