begin;

create or replace function public.tgg_video_render_worker_claim(
  p_worker_id text,
  p_provider_key text default 'external.transcoder',
  p_lease_seconds integer default 300
)
returns jsonb
language plpgsql
security invoker
set search_path='public','pg_catalog'
as $$
declare
  j public.tgg_video_studio_render_jobs;
  tok uuid:=gen_random_uuid();
  lease_s integer:=least(1800,greatest(60,coalesce(p_lease_seconds,300)));
  manifest jsonb;
begin
  if nullif(btrim(coalesce(p_worker_id,'')),'') is null then raise exception 'WORKER_ID_REQUIRED'; end if;

  update public.tgg_video_studio_render_jobs r
  set status='failed',
      error_message='STALE_SOURCE_REVISION_REQUEUE_REQUIRED',
      finished_at=now(),
      lease_token=null,
      leased_by=null,
      lease_expires_at=null,
      worker_heartbeat_at=now(),
      updated_at=now()
  where r.status in ('queued','processing')
    and (r.status='queued' or r.lease_expires_at is null or r.lease_expires_at<now())
    and coalesce(r.request_payload->>'mode','')<>'browser_export'
    and exists (
      select 1
      from public.tgg_studio_projects sp
      where sp.id=r.project_id
        and coalesce(sp.revision,0)<>coalesce(r.source_revision,0)
    );

  select * into j
  from public.tgg_video_studio_render_jobs r
  where (r.status='queued' or (r.status='processing' and r.lease_expires_at<now()))
    and coalesce(r.request_payload->>'mode','')<>'browser_export'
    and exists (
      select 1
      from public.tgg_studio_projects sp
      where sp.id=r.project_id
        and coalesce(sp.revision,0)=coalesce(r.source_revision,0)
    )
  order by r.priority asc,r.created_at asc
  for update skip locked
  limit 1;

  if j.id is null then return jsonb_build_object('ok',true,'job',null); end if;

  update public.tgg_video_studio_render_jobs
  set status='processing',
      provider_key=coalesce(nullif(btrim(p_provider_key),''),'external.transcoder'),
      lease_token=tok,
      leased_by=left(p_worker_id,120),
      lease_expires_at=now()+make_interval(secs=>lease_s),
      worker_heartbeat_at=now(),
      started_at=coalesce(started_at,now()),
      finished_at=null,
      error_message=null,
      attempt_count=attempt_count+1,
      progress=greatest(progress,1),
      updated_at=now()
  where id=j.id
  returning * into j;

  select jsonb_build_object(
    'schema_version',5,
    'job',to_jsonb(j)-'lease_token',
    'lease_token',tok,
    'project',(select to_jsonb(c) from public.tgg_creative_projects c where c.id=j.project_id),
    'studio_project',(select to_jsonb(s) from public.tgg_studio_projects s where s.id=j.project_id),
    'timeline',coalesce((select jsonb_agg(to_jsonb(t) order by t.track_index,t.start_seconds,t.created_at) from public.tgg_video_timeline_items t where t.project_id=j.project_id),'[]'::jsonb),
    'assets',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at) from public.tgg_media_vault_assets a where a.id in (select distinct t.asset_id from public.tgg_video_timeline_items t where t.project_id=j.project_id and t.asset_id is not null)),'[]'::jsonb),
    'effects',coalesce((select jsonb_agg(to_jsonb(e) order by e.timeline_item_id,e.stack_order,e.created_at) from public.tgg_video_studio_effect_instances e where e.project_id=j.project_id),'[]'::jsonb),
    'keyframes',coalesce((select jsonb_agg(to_jsonb(k) order by k.timeline_item_id,k.parameter,k.time_seconds) from public.tgg_video_studio_keyframes k where k.project_id=j.project_id),'[]'::jsonb),
    'captions',coalesce((select jsonb_agg(to_jsonb(cu) order by cu.start_seconds,cu.track_index) from public.tgg_video_studio_caption_cues cu where cu.project_id=j.project_id),'[]'::jsonb),
    'markers',coalesce((select jsonb_agg(to_jsonb(m) order by m.time_seconds) from public.tgg_video_studio_markers m where m.project_id=j.project_id),'[]'::jsonb),
    'transitions',coalesce((select jsonb_agg(to_jsonb(tr) order by tr.created_at) from public.tgg_video_studio_transition_instances tr where tr.project_id=j.project_id),'[]'::jsonb),
    'requested_output',jsonb_build_object('format',j.output_format,'preset',j.output_preset,'job_type',j.job_type,'payload',j.request_payload),
    'output_storage_prefix',j.user_id::text||'/video/'||j.project_id::text||'/server-renders/'||j.id::text||'/'
  ) into manifest;

  return jsonb_build_object('ok',true,'manifest',manifest);
end$$;

create or replace function public.tgg_video_render_worker_complete(
  p_job_id uuid,
  p_lease_token uuid,
  p_storage_path text,
  p_format text,
  p_aspect_ratio text,
  p_resolution text default null,
  p_duration_seconds numeric default null,
  p_metadata jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security invoker
set search_path='public','pg_catalog'
as $$
declare
  j public.tgg_video_studio_render_jobs;
  out_id uuid;
  current_revision bigint;
begin
  select * into j
  from public.tgg_video_studio_render_jobs
  where id=p_job_id and status='processing' and lease_token=p_lease_token
  for update;

  if j.id is null then return jsonb_build_object('ok',false,'lease_valid',false); end if;

  select coalesce(revision,0) into current_revision
  from public.tgg_studio_projects
  where id=j.project_id;

  if current_revision is distinct from coalesce(j.source_revision,0) then
    update public.tgg_video_studio_render_jobs
    set status='failed',
        error_message='STALE_SOURCE_REVISION_RESULT_REJECTED',
        finished_at=now(),
        lease_token=null,
        lease_expires_at=null,
        worker_heartbeat_at=now(),
        updated_at=now()
    where id=j.id;
    return jsonb_build_object('ok',false,'stale_source_revision',true,'queued_revision',j.source_revision,'current_revision',current_revision);
  end if;

  if nullif(btrim(coalesce(p_storage_path,'')),'') is null then raise exception 'OUTPUT_STORAGE_PATH_REQUIRED'; end if;
  if position(j.user_id::text||'/video/'||j.project_id::text||'/server-renders/'||j.id::text||'/' in p_storage_path)<>1 then raise exception 'OUTPUT_STORAGE_PATH_INVALID'; end if;

  insert into public.tgg_video_studio_render_outputs(
    render_job_id,user_id,format,aspect_ratio,resolution,duration_seconds,storage_path,status,metadata
  ) values (
    j.id,j.user_id,coalesce(nullif(p_format,''),j.output_format,'mp4'),
    coalesce(nullif(p_aspect_ratio,''),'16:9'),p_resolution,p_duration_seconds,p_storage_path,'ready',
    coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('provider_key',j.provider_key,'worker',j.leased_by,'source_revision',j.source_revision)
  ) returning id into out_id;

  update public.tgg_video_studio_render_jobs
  set status='ready',
      progress=100,
      result_payload=jsonb_build_object('output_id',out_id,'storage_path',p_storage_path,'format',coalesce(nullif(p_format,''),j.output_format),'completed_by',j.leased_by),
      finished_at=now(),
      lease_token=null,
      lease_expires_at=null,
      worker_heartbeat_at=now(),
      updated_at=now()
  where id=j.id;

  return jsonb_build_object('ok',true,'output_id',out_id,'job_id',j.id,'status','ready');
end$$;

create or replace function public.tgg_video_studio_render_readiness(p_project_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path='public','private','tgg_private','pg_catalog'
as $$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_provider_key text;
  v_provider_status text;
  v_provider_endpoint text;
  v_has_provider_secret boolean:=false;
  v_connected boolean:=false;
  v_revision bigint;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'allowed')::boolean,false) then raise exception 'PROJECT_ACCESS_REQUIRED' using errcode='42501'; end if;

  select revision into v_revision from public.tgg_studio_projects where id=p_project_id;

  select s.provider_key,s.status,s.endpoint_url
    into v_provider_key,v_provider_status,v_provider_endpoint
  from private.tgg_provider_activation_staging s
  where s.status='verified'
    and s.endpoint_url is not null
    and (
      lower(s.provider_key) like '%transcod%'
      or lower(s.provider_key) like '%render%'
      or lower(s.provider_key) like '%mux%'
      or lower(s.provider_key) like '%video.processing%'
      or lower(s.provider_key) like '%media.processing%'
    )
  order by s.updated_at desc
  limit 1;

  if v_provider_key is not null then
    select exists(
      select 1 from private.tgg_provider_secret_registry r
      where r.provider_key=v_provider_key
        and r.status in ('stored','verified','active')
    ) into v_has_provider_secret;
  end if;

  v_connected:=v_provider_key is not null and v_provider_status='verified' and v_provider_endpoint is not null and v_has_provider_secret;

  return jsonb_build_object(
    'ok',true,
    'project_id',p_project_id,
    'project_revision',coalesce(v_revision,0),
    'browser_master_webm',true,
    'private_signed_media',true,
    'multi_track_compositor',true,
    'realtime_collaboration',true,
    'worker_queue_contract',true,
    'worker_manifest_schema_version',5,
    'server_transcoder_connected',v_connected,
    'server_mp4_available',v_connected,
    'provider',case when v_provider_key is null then null else jsonb_build_object('provider_key',v_provider_key,'status',v_provider_status,'endpoint_configured',v_provider_endpoint is not null,'secret_configured',v_has_provider_secret) end,
    'queue_policy',jsonb_build_object('max_attempts',3,'lease_seconds_default',300,'stale_revision_guard',true),
    'recommended_export',case when v_connected then 'server_mp4' else 'browser_webm' end
  );
end$$;

