create or replace function public.tgg_video_studio_trim_clip_v1(
  p_item_id uuid,
  p_edge text,
  p_playhead_seconds numeric,
  p_ripple boolean default false,
  p_base_revision bigint default null
) returns jsonb
language plpgsql
security definer
set search_path to 'public','tgg_private','pg_catalog'
as $$
declare
  v_uid uuid:=auth.uid();
  v_item public.tgg_video_timeline_items;
  v_perm jsonb;
  v_rev bigint;
  v_new_rev bigint;
  v_edge text:=lower(btrim(coalesce(p_edge,'')));
  v_play numeric:=greatest(0,coalesce(p_playhead_seconds,0));
  v_old_start numeric;
  v_old_end numeric;
  v_old_duration numeric;
  v_delta numeric;
  v_new_duration numeric;
  v_speed numeric:=1;
  v_shifted integer:=0;
  v_transitions integer:=0;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if v_edge not in ('in','out') then raise exception 'TRIM_EDGE_INVALID'; end if;

  select * into v_item from public.tgg_video_timeline_items where id=p_item_id for update;
  if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
  v_perm:=tgg_private.video_studio_permission(v_item.project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;

  select revision into v_rev from public.tgg_studio_projects where id=v_item.project_id for update;
  if p_base_revision is not null and p_base_revision<>v_rev then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_rev);
  end if;

  v_old_start:=v_item.start_seconds;
  v_old_duration:=v_item.duration_seconds;
  v_old_end:=v_old_start+v_old_duration;
  if not (v_play>v_old_start and v_play<v_old_end) then
    return jsonb_build_object('ok',false,'outside',true,'reason','PLAYHEAD_MUST_BE_INSIDE_CLIP','current_revision',v_rev);
  end if;

  if v_edge='in' and exists(
    select 1 from public.tgg_video_studio_keyframes where timeline_item_id=v_item.id and parameter='speed'
  ) then
    return jsonb_build_object('ok',false,'unsupported',true,'reason','SPEED_RAMP_TRIM_IN_SPLIT_FIRST','current_revision',v_rev);
  end if;

  delete from public.tgg_video_studio_transition_instances
   where from_item_id=v_item.id or to_item_id=v_item.id;
  get diagnostics v_transitions=row_count;

  if v_edge='in' then
    v_delta:=v_play-v_old_start;
    v_new_duration:=v_old_end-v_play;
    if coalesce(v_item.settings#>>'{editor_state,speed}','') ~ '^[0-9]+([.][0-9]+)?$' then
      v_speed:=greatest(.1,least(4,(v_item.settings#>>'{editor_state,speed}')::numeric/100));
    end if;

    delete from public.tgg_video_studio_effect_instances
     where timeline_item_id=v_item.id
       and start_seconds is not null
       and duration_seconds is not null
       and start_seconds+duration_seconds<=v_delta;

    update public.tgg_video_studio_effect_instances
       set start_seconds=greatest(0,start_seconds-v_delta),
           duration_seconds=case
             when duration_seconds is null then null
             else greatest(0,least(v_new_duration,start_seconds+duration_seconds-v_delta)-greatest(0,start_seconds-v_delta))
           end,
           updated_at=now()
     where timeline_item_id=v_item.id and start_seconds is not null;

    delete from public.tgg_video_studio_effect_instances
     where timeline_item_id=v_item.id and duration_seconds is not null and duration_seconds<=0;

    delete from public.tgg_video_studio_keyframes
     where timeline_item_id=v_item.id and time_seconds<v_delta;
    update public.tgg_video_studio_keyframes
       set time_seconds=time_seconds-v_delta,updated_at=now()
     where timeline_item_id=v_item.id;

    update public.tgg_video_timeline_items
       set start_seconds=v_play,
           duration_seconds=v_new_duration,
           source_in_seconds=v_item.source_in_seconds+(v_delta*v_speed),
           updated_at=now()
     where id=v_item.id;
  else
    v_new_duration:=v_play-v_old_start;
    v_delta:=v_old_duration-v_new_duration;

    delete from public.tgg_video_studio_effect_instances
     where timeline_item_id=v_item.id and start_seconds is not null and start_seconds>=v_new_duration;
    update public.tgg_video_studio_effect_instances
       set duration_seconds=greatest(0,least(duration_seconds,v_new_duration-start_seconds)),updated_at=now()
     where timeline_item_id=v_item.id
       and start_seconds is not null
       and duration_seconds is not null
       and start_seconds<v_new_duration
       and start_seconds+duration_seconds>v_new_duration;
    delete from public.tgg_video_studio_keyframes
     where timeline_item_id=v_item.id and time_seconds>v_new_duration;

    update public.tgg_video_timeline_items
       set duration_seconds=v_new_duration,updated_at=now()
     where id=v_item.id;

    if coalesce(p_ripple,false) then
      update public.tgg_video_timeline_items
         set start_seconds=greatest(v_play,start_seconds-v_delta),updated_at=now()
       where project_id=v_item.project_id
         and track_index=v_item.track_index
         and id<>v_item.id
         and start_seconds>=v_old_end;
      get diagnostics v_shifted=row_count;
    end if;
  end if;

  update public.tgg_creative_projects set updated_at=now() where id=v_item.project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now()
   where id=v_item.project_id returning revision into v_new_rev;

  return jsonb_build_object('ok',true,'conflict',false,'item_id',v_item.id,'edge',v_edge,
    'playhead_seconds',v_play,'shifted_items',v_shifted,'removed_transitions',v_transitions,
    'base_revision',v_rev,'project_revision',v_new_rev);
end$$;

