grant execute on function public.tgg_video_studio_trim_clip_v1(uuid,text,numeric,boolean,bigint) to authenticated;

create or replace function public.tgg_video_studio_overwrite_asset_v1(
  p_project_id uuid,
  p_asset_id uuid,
  p_track_index integer default 0,
  p_start_seconds numeric default 0,
  p_duration_seconds numeric default null,
  p_base_revision bigint default null
) returns jsonb
language plpgsql
security definer
set search_path to 'public','tgg_private','pg_catalog'
as $$
declare
  v_uid uuid:=auth.uid();
  v_perm jsonb;
  v_asset public.tgg_media_vault_assets;
  v_rev bigint;
  v_new_rev bigint;
  v_start numeric:=greatest(0,coalesce(p_start_seconds,0));
  v_duration numeric;
  v_end numeric;
  v_type text;
  v_old public.tgg_video_timeline_items;
  v_right public.tgg_video_timeline_items;
  v_old_start numeric;
  v_old_end numeric;
  v_left_duration numeric;
  v_right_duration numeric;
  v_offset numeric;
  v_speed numeric:=1;
  v_deleted integer:=0;
  v_trimmed integer:=0;
  v_split integer:=0;
  v_transitions integer:=0;
  v_rc integer:=0;
  v_item public.tgg_video_timeline_items;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if coalesce(p_track_index,-1)<0 then raise exception 'TRACK_INDEX_INVALID'; end if;
  v_perm:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;

  select * into v_asset from public.tgg_media_vault_assets where id=p_asset_id and project_id=p_project_id;
  if v_asset.id is null then raise exception 'ASSET_NOT_FOUND_IN_PROJECT'; end if;
  v_type:=case when lower(coalesce(v_asset.mime_type,'')) like 'audio/%' then 'audio'
               when lower(coalesce(v_asset.mime_type,'')) like 'image/%' then 'image'
               else 'video' end;
  v_duration:=coalesce(p_duration_seconds,v_asset.duration_seconds,case when v_type='image' then 5 else null end);
  if v_duration is null or v_duration<=0 then raise exception 'ASSET_DURATION_REQUIRED'; end if;
  if v_type in ('audio','video') and v_asset.duration_seconds is not null and v_duration>v_asset.duration_seconds+.05 then
    raise exception 'DURATION_EXCEEDS_ASSET';
  end if;
  v_end:=v_start+v_duration;

  select revision into v_rev from public.tgg_studio_projects where id=p_project_id for update;
  if v_rev is null then raise exception 'PROJECT_NOT_FOUND'; end if;
  if p_base_revision is not null and p_base_revision<>v_rev then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_rev);
  end if;

  if exists(
    select 1
    from public.tgg_video_timeline_items t
    join public.tgg_video_studio_keyframes k on k.timeline_item_id=t.id and k.parameter='speed'
    where t.project_id=p_project_id and t.track_index=p_track_index
      and t.start_seconds<v_end and t.start_seconds+t.duration_seconds>v_start
      and t.start_seconds+t.duration_seconds>v_end
  ) then
    return jsonb_build_object('ok',false,'unsupported',true,'reason','SPEED_RAMP_OVERWRITE_SPLIT_FIRST','current_revision',v_rev);
  end if;

  for v_old in
    select * from public.tgg_video_timeline_items
    where project_id=p_project_id and track_index=p_track_index
      and start_seconds<v_end and start_seconds+duration_seconds>v_start
    order by start_seconds,id
    for update
  loop
    v_old_start:=v_old.start_seconds;
    v_old_end:=v_old.start_seconds+v_old.duration_seconds;
    v_speed:=1;
    if coalesce(v_old.settings#>>'{editor_state,speed}','') ~ '^[0-9]+([.][0-9]+)?$' then
      v_speed:=greatest(.1,least(4,(v_old.settings#>>'{editor_state,speed}')::numeric/100));
    end if;

    delete from public.tgg_video_studio_transition_instances
     where from_item_id=v_old.id or to_item_id=v_old.id;
    get diagnostics v_rc=row_count;
    v_transitions:=v_transitions+v_rc;

    if v_old_start<v_start and v_old_end>v_end then
      v_left_duration:=v_start-v_old_start;
      v_right_duration:=v_old_end-v_end;
      v_offset:=v_end-v_old_start;

      insert into public.tgg_video_timeline_items(project_id,user_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings)
      values(v_old.project_id,v_uid,v_old.asset_id,v_old.track_index,v_old.item_type,v_end,v_right_duration,
        v_old.source_in_seconds+(v_offset*v_speed),v_old.settings)
      returning * into v_right;

      insert into public.tgg_video_studio_effect_instances(project_id,timeline_item_id,user_id,effect_catalog_id,effect_type,stack_order,start_seconds,duration_seconds,settings,enabled)
      select e.project_id,v_right.id,v_uid,e.effect_catalog_id,e.effect_type,e.stack_order,
        case when e.start_seconds is null then null else greatest(0,e.start_seconds-v_offset) end,
        case when e.duration_seconds is null then null else
          greatest(0,least(v_right_duration,e.start_seconds+e.duration_seconds-v_offset)-greatest(0,e.start_seconds-v_offset)) end,
        e.settings,e.enabled
      from public.tgg_video_studio_effect_instances e
      where e.timeline_item_id=v_old.id
        and (e.start_seconds is null or e.duration_seconds is null or e.start_seconds+e.duration_seconds>v_offset)
        and (e.start_seconds is null or e.start_seconds<v_offset+v_right_duration);
      delete from public.tgg_video_studio_effect_instances where timeline_item_id=v_right.id and duration_seconds is not null and duration_seconds<=0;

      insert into public.tgg_video_studio_keyframes(project_id,timeline_item_id,user_id,parameter,time_seconds,value,easing)
      select k.project_id,v_right.id,v_uid,k.parameter,k.time_seconds-v_offset,k.value,k.easing
      from public.tgg_video_studio_keyframes k
      where k.timeline_item_id=v_old.id and k.time_seconds>=v_offset and k.time_seconds<=v_offset+v_right_duration;

      update public.tgg_video_timeline_items set duration_seconds=v_left_duration,updated_at=now() where id=v_old.id;
      delete from public.tgg_video_studio_effect_instances where timeline_item_id=v_old.id and start_seconds is not null and start_seconds>=v_left_duration;
      update public.tgg_video_studio_effect_instances set duration_seconds=greatest(0,least(duration_seconds,v_left_duration-start_seconds)),updated_at=now()
       where timeline_item_id=v_old.id and start_seconds is not null and duration_seconds is not null and start_seconds<v_left_duration and start_seconds+duration_seconds>v_left_duration;
      delete from public.tgg_video_studio_keyframes where timeline_item_id=v_old.id and time_seconds>v_left_duration;
      v_split:=v_split+1;

    elsif v_old_start<v_start and v_old_end>v_start then
      v_left_duration:=v_start-v_old_start;
      update public.tgg_video_timeline_items set duration_seconds=v_left_duration,updated_at=now() where id=v_old.id;
      delete from public.tgg_video_studio_effect_instances where timeline_item_id=v_old.id and start_seconds is not null and start_seconds>=v_left_duration;
      update public.tgg_video_studio_effect_instances set duration_seconds=greatest(0,least(duration_seconds,v_left_duration-start_seconds)),updated_at=now()
       where timeline_item_id=v_old.id and start_seconds is not null and duration_seconds is not null and start_seconds<v_left_duration and start_seconds+duration_seconds>v_left_duration;
      delete from public.tgg_video_studio_keyframes where timeline_item_id=v_old.id and time_seconds>v_left_duration;
      v_trimmed:=v_trimmed+1;

    elsif v_old_start>=v_start and v_old_end<=v_end then
      delete from public.tgg_video_timeline_items where id=v_old.id;
      v_deleted:=v_deleted+1;

    elsif v_old_start<v_end and v_old_end>v_end then
      v_offset:=v_end-v_old_start;
      v_right_duration:=v_old_end-v_end;

      delete from public.tgg_video_studio_effect_instances
       where timeline_item_id=v_old.id and start_seconds is not null and duration_seconds is not null and start_seconds+duration_seconds<=v_offset;
      update public.tgg_video_studio_effect_instances
         set start_seconds=greatest(0,start_seconds-v_offset),
             duration_seconds=case when duration_seconds is null then null else
               greatest(0,least(v_right_duration,start_seconds+duration_seconds-v_offset)-greatest(0,start_seconds-v_offset)) end,
             updated_at=now()
       where timeline_item_id=v_old.id and start_seconds is not null;
      delete from public.tgg_video_studio_effect_instances where timeline_item_id=v_old.id and duration_seconds is not null and duration_seconds<=0;
      delete from public.tgg_video_studio_keyframes where timeline_item_id=v_old.id and time_seconds<v_offset;
      update public.tgg_video_studio_keyframes set time_seconds=time_seconds-v_offset,updated_at=now() where timeline_item_id=v_old.id;
      update public.tgg_video_timeline_items
         set start_seconds=v_end,duration_seconds=v_right_duration,
             source_in_seconds=v_old.source_in_seconds+(v_offset*v_speed),updated_at=now()
       where id=v_old.id;
      v_trimmed:=v_trimmed+1;
    end if;
  end loop;

  insert into public.tgg_video_timeline_items(user_id,project_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings)
  values(v_uid,p_project_id,v_asset.id,p_track_index,v_type,v_start,v_duration,0,
    jsonb_build_object('source','media-bin-v551','placement_mode','overwrite','asset_id',v_asset.id,'schema_version',5))
  returning * into v_item;

  update public.tgg_creative_projects set updated_at=now() where id=p_project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now()
   where id=p_project_id returning revision into v_new_rev;

  return jsonb_build_object('ok',true,'conflict',false,'item',to_jsonb(v_item),'deleted_items',v_deleted,
    'trimmed_items',v_trimmed,'split_items',v_split,'removed_transitions',v_transitions,
    'base_revision',v_rev,'project_revision',v_new_rev);
end$$;

