grant execute on function public.tgg_video_studio_track_mix_v1(uuid) to authenticated;

create or replace function public.tgg_video_studio_set_track_state_v1(
  p_project_id uuid,
  p_track_index integer,
  p_label text default null,
  p_muted boolean default null,
  p_solo boolean default null,
  p_locked boolean default null,
  p_gain_db numeric default null,
  p_pan numeric default null,
  p_base_revision bigint default null
) returns jsonb
language plpgsql
security definer
set search_path to 'public','private','tgg_private','pg_catalog'
as $$
declare v_uid uuid:=auth.uid(); v_perm jsonb; v_rev bigint; v_new_rev bigint; v_state private.tgg_video_studio_track_states;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if coalesce(p_track_index,-1)<0 then raise exception 'TRACK_INDEX_INVALID'; end if;
  if p_gain_db is not null and (p_gain_db<-60 or p_gain_db>24) then raise exception 'GAIN_DB_INVALID'; end if;
  if p_pan is not null and (p_pan<-1 or p_pan>1) then raise exception 'PAN_INVALID'; end if;
  v_perm:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  select revision into v_rev from public.tgg_studio_projects where id=p_project_id for update;
  if v_rev is null then raise exception 'PROJECT_NOT_FOUND'; end if;
  if p_base_revision is not null and p_base_revision<>v_rev then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_rev);
  end if;

  insert into private.tgg_video_studio_track_states as s(project_id,track_index,label,muted,solo,locked,gain_db,pan,updated_by,updated_at)
  values(p_project_id,p_track_index,left(nullif(btrim(coalesce(p_label,'')),''),60),coalesce(p_muted,false),coalesce(p_solo,false),coalesce(p_locked,false),coalesce(p_gain_db,0),coalesce(p_pan,0),v_uid,now())
  on conflict(project_id,track_index) do update set
    label=coalesce(left(nullif(btrim(coalesce(p_label,'')),''),60),s.label),
    muted=coalesce(p_muted,s.muted),
    solo=coalesce(p_solo,s.solo),
    locked=coalesce(p_locked,s.locked),
    gain_db=coalesce(p_gain_db,s.gain_db),
    pan=coalesce(p_pan,s.pan),
    updated_by=v_uid,
    updated_at=now()
  returning * into v_state;

  update public.tgg_creative_projects set updated_at=now() where id=p_project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_new_rev;
  return jsonb_build_object('ok',true,'conflict',false,'state',jsonb_build_object('track_index',v_state.track_index,'label',v_state.label,'muted',v_state.muted,'solo',v_state.solo,'locked',v_state.locked,'gain_db',v_state.gain_db,'pan',v_state.pan),'base_revision',v_rev,'project_revision',v_new_rev);
end$$;
revoke all on function public.tgg_video_studio_set_track_state_v1(uuid,integer,text,boolean,boolean,boolean,numeric,numeric,bigint) from public,anon;
grant execute on function public.tgg_video_studio_set_track_state_v1(uuid,integer,text,boolean,boolean,boolean,numeric,numeric,bigint) to authenticated;

create or replace function public.tgg_video_studio_detach_audio_v1(
  p_item_id uuid,
  p_target_track integer default null,
  p_base_revision bigint default null
) returns jsonb
language plpgsql
security definer
set search_path to 'public','private','tgg_private','pg_catalog'
as $$
declare
  v_uid uuid:=auth.uid(); v_item public.tgg_video_timeline_items; v_asset public.tgg_media_vault_assets; v_audio public.tgg_video_timeline_items;
  v_perm jsonb; v_rev bigint; v_new_rev bigint; v_track integer; v_audio_settings jsonb; v_video_settings jsonb; v_prev_mute boolean:=false;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_item from public.tgg_video_timeline_items where id=p_item_id for update;
  if v_item.id is null then raise exception 'ITEM_NOT_FOUND'; end if;
  if v_item.item_type<>'video' then raise exception 'VIDEO_CLIP_REQUIRED'; end if;
  v_perm:=tgg_private.video_studio_permission(v_item.project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  select * into v_asset from public.tgg_media_vault_assets where id=v_item.asset_id and project_id=v_item.project_id;
  if v_asset.id is null or lower(coalesce(v_asset.mime_type,'')) not like 'video/%' then raise exception 'VIDEO_ASSET_REQUIRED'; end if;
  select revision into v_rev from public.tgg_studio_projects where id=v_item.project_id for update;
  if p_base_revision is not null and p_base_revision<>v_rev then return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_rev); end if;
  if nullif(v_item.settings->>'detached_audio_item_id','') is not null and exists(select 1 from public.tgg_video_timeline_items t where t.id=(v_item.settings->>'detached_audio_item_id')::uuid) then
    return jsonb_build_object('ok',false,'already_detached',true,'audio_item_id',v_item.settings->>'detached_audio_item_id','current_revision',v_rev);
  end if;
  if p_target_track is null then select coalesce(max(track_index),v_item.track_index)+1 into v_track from public.tgg_video_timeline_items where project_id=v_item.project_id;
  else v_track:=p_target_track; end if;
  if v_track<0 then raise exception 'TRACK_INDEX_INVALID'; end if;
  v_prev_mute:=lower(coalesce(v_item.settings->'audio'->>'mute','false'))='true';
  v_audio_settings:=jsonb_set(v_item.settings - 'detached_audio_item_id' - 'detached_audio_previous_mute','{audio}',coalesce(v_item.settings->'audio','{}'::jsonb)||jsonb_build_object('mute',false),true)||jsonb_build_object('detached_from_item_id',v_item.id,'detached_audio_v552',true);

  insert into public.tgg_video_timeline_items(user_id,project_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings)
  values(v_uid,v_item.project_id,v_item.asset_id,v_track,'audio',v_item.start_seconds,v_item.duration_seconds,v_item.source_in_seconds,v_audio_settings)
  returning * into v_audio;

  insert into public.tgg_video_studio_keyframes(project_id,timeline_item_id,user_id,parameter,time_seconds,value,easing)
  select project_id,v_audio.id,v_uid,parameter,time_seconds,value,easing from public.tgg_video_studio_keyframes where timeline_item_id=v_item.id and parameter='volume';
  delete from public.tgg_video_studio_keyframes where timeline_item_id=v_item.id and parameter='volume';

  v_video_settings:=jsonb_set(v_item.settings,'{audio}',coalesce(v_item.settings->'audio','{}'::jsonb)||jsonb_build_object('mute',true),true)||jsonb_build_object('detached_audio_item_id',v_audio.id,'detached_audio_previous_mute',v_prev_mute,'detached_audio_v552',true);
  update public.tgg_video_timeline_items set settings=v_video_settings,updated_at=now() where id=v_item.id;
  update public.tgg_creative_projects set updated_at=now() where id=v_item.project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_item.project_id returning revision into v_new_rev;
  return jsonb_build_object('ok',true,'conflict',false,'video_item_id',v_item.id,'audio_item',to_jsonb(v_audio),'target_track',v_track,'base_revision',v_rev,'project_revision',v_new_rev);
end$$;
revoke all on function public.tgg_video_studio_detach_audio_v1(uuid,integer,bigint) from public,anon;
grant execute on function public.tgg_video_studio_detach_audio_v1(uuid,integer,bigint) to authenticated;

create or replace function public.tgg_video_studio_reattach_audio_v1(
  p_audio_item_id uuid,
  p_base_revision bigint default null
) returns jsonb
language plpgsql
security definer
set search_path to 'public','private','tgg_private','pg_catalog'
as $$
declare
  v_uid uuid:=auth.uid(); v_audio public.tgg_video_timeline_items; v_video public.tgg_video_timeline_items; v_video_id uuid;
  v_perm jsonb; v_rev bigint; v_new_rev bigint; v_mix jsonb; v_settings jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_audio from public.tgg_video_timeline_items where id=p_audio_item_id for update;
  if v_audio.id is null or v_audio.item_type<>'audio' then raise exception 'DETACHED_AUDIO_CLIP_REQUIRED'; end if;
  if nullif(v_audio.settings->>'detached_from_item_id','') is null then raise exception 'DETACHED_AUDIO_RELATION_MISSING'; end if;
  v_video_id:=(v_audio.settings->>'detached_from_item_id')::uuid;
  select * into v_video from public.tgg_video_timeline_items where id=v_video_id for update;
  if v_video.id is null or v_video.project_id<>v_audio.project_id or v_video.item_type<>'video' then raise exception 'SOURCE_VIDEO_CLIP_MISSING'; end if;
  v_perm:=tgg_private.video_studio_permission(v_audio.project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  select revision into v_rev from public.tgg_studio_projects where id=v_audio.project_id for update;
  if p_base_revision is not null and p_base_revision<>v_rev then return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_rev); end if;
  if abs(v_audio.start_seconds-v_video.start_seconds)>.001 or abs(v_audio.duration_seconds-v_video.duration_seconds)>.001 or abs(v_audio.source_in_seconds-v_video.source_in_seconds)>.001 then
    return jsonb_build_object('ok',false,'timing_changed',true,'reason','DETACHED_AUDIO_TIMING_CHANGED_KEEP_SEPARATE','current_revision',v_rev);
  end if;

  v_mix:=coalesce(v_audio.settings->'audio','{}'::jsonb);
  v_settings:=jsonb_set(v_video.settings - 'detached_audio_item_id' - 'detached_audio_previous_mute','{audio}',v_mix,true);
  update public.tgg_video_timeline_items set settings=v_settings,updated_at=now() where id=v_video.id;
  delete from public.tgg_video_studio_keyframes where timeline_item_id=v_video.id and parameter='volume';
  insert into public.tgg_video_studio_keyframes(project_id,timeline_item_id,user_id,parameter,time_seconds,value,easing)
  select project_id,v_video.id,v_uid,parameter,time_seconds,value,easing from public.tgg_video_studio_keyframes where timeline_item_id=v_audio.id and parameter='volume';
  delete from public.tgg_video_timeline_items where id=v_audio.id;
  update public.tgg_creative_projects set updated_at=now() where id=v_video.project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=v_video.project_id returning revision into v_new_rev;
  return jsonb_build_object('ok',true,'conflict',false,'video_item_id',v_video.id,'removed_audio_item_id',v_audio.id,'base_revision',v_rev,'project_revision',v_new_rev);
end$$;
revoke all on function public.tgg_video_studio_reattach_audio_v1(uuid,bigint) from public,anon;
grant execute on function public.tgg_video_studio_reattach_audio_v1(uuid,bigint) to authenticated;

do $$
declare v_def text; v_marker text:='    ''requested_output'',jsonb_build_object'; v_insert text;
begin
  select pg_get_functiondef(p.oid) into v_def from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='tgg_video_render_worker_claim';
  if v_def is null then raise exception 'RENDER_WORKER_CLAIM_MISSING'; end if;
  if position('''schema_version'',5,' in v_def)=0 then raise exception 'RENDER_MANIFEST_SCHEMA_MARKER_MISSING'; end if;
  if position(v_marker in v_def)=0 then raise exception 'RENDER_MANIFEST_OUTPUT_MARKER_MISSING'; end if;
  v_def:=replace(v_def,'''schema_version'',5,','''schema_version'',6,');
  v_insert:='    ''track_states'',coalesce((select jsonb_agg(to_jsonb(ts) order by ts.track_index) from private.tgg_video_studio_track_states ts where ts.project_id=j.project_id),''[]''::jsonb),'||E'\n'||v_marker;
  v_def:=replace(v_def,v_marker,v_insert);
  execute v_def;
end$$;

