-- MIGRATION 20260910125533 video_source_range_placement_v554
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

create or replace function public.tgg_video_studio_place_asset_range_v1(
  p_project_id uuid,
  p_asset_id uuid,
  p_track_index integer default 0,
  p_start_seconds numeric default 0,
  p_source_in_seconds numeric default 0,
  p_duration_seconds numeric default null,
  p_mode text default 'overlay',
  p_base_revision bigint default null
) returns jsonb
language plpgsql
security definer
set search_path to 'public','tgg_private','pg_catalog'
as $fn$
declare
  v_uid uuid:=auth.uid();
  v_permission jsonb;
  v_asset public.tgg_media_vault_assets;
  v_revision bigint;
  v_new_revision bigint;
  v_start numeric;
  v_source_in numeric:=greatest(0,coalesce(p_source_in_seconds,0));
  v_duration numeric;
  v_mode text:=lower(btrim(coalesce(p_mode,'overlay')));
  v_type text;
  v_item public.tgg_video_timeline_items;
  v_shifted integer:=0;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_permission:=tgg_private.video_studio_permission(p_project_id);
  if not coalesce((v_permission->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if coalesce(p_track_index,-1)<0 then raise exception 'TRACK_INDEX_INVALID'; end if;
  if v_mode not in ('overlay','append','insert') then raise exception 'PLACEMENT_MODE_INVALID'; end if;

  select * into v_asset from public.tgg_media_vault_assets where id=p_asset_id and project_id=p_project_id;
  if v_asset.id is null then raise exception 'ASSET_NOT_FOUND_IN_PROJECT'; end if;

  select revision into v_revision from public.tgg_studio_projects where id=p_project_id for update;
  if v_revision is null then raise exception 'PROJECT_NOT_FOUND'; end if;
  if p_base_revision is not null and p_base_revision<>v_revision then
    return jsonb_build_object('ok',false,'conflict',true,'base_revision',p_base_revision,'current_revision',v_revision);
  end if;

  v_type:=case
    when lower(coalesce(v_asset.mime_type,'')) like 'audio/%' then 'audio'
    when lower(coalesce(v_asset.mime_type,'')) like 'image/%' then 'image'
    else 'video'
  end;

  if v_type='image' then
    if v_source_in<>0 then raise exception 'IMAGE_SOURCE_IN_INVALID'; end if;
    v_duration:=coalesce(p_duration_seconds,5);
  else
    if v_asset.duration_seconds is not null and v_source_in>=v_asset.duration_seconds then raise exception 'SOURCE_IN_OUT_OF_RANGE'; end if;
    v_duration:=coalesce(p_duration_seconds,
      case when v_asset.duration_seconds is not null then v_asset.duration_seconds-v_source_in else null end);
  end if;

  if v_duration is null or v_duration<=0 then raise exception 'SOURCE_RANGE_DURATION_REQUIRED'; end if;
  if v_asset.duration_seconds is not null and v_source_in+v_duration>v_asset.duration_seconds+0.02 then raise exception 'SOURCE_RANGE_EXCEEDS_ASSET'; end if;

  if v_mode='append' then
    select coalesce(max(start_seconds+duration_seconds),0) into v_start
    from public.tgg_video_timeline_items
    where project_id=p_project_id and track_index=p_track_index;
  else
    v_start:=greatest(0,coalesce(p_start_seconds,0));
  end if;

  if v_mode='insert' then
    if exists(
      select 1 from public.tgg_video_timeline_items
      where project_id=p_project_id and track_index=p_track_index
        and start_seconds<v_start and start_seconds+duration_seconds>v_start
    ) then
      return jsonb_build_object('ok',false,'occupied',true,'reason','INSERT_POINT_INSIDE_CLIP_SPLIT_FIRST','current_revision',v_revision);
    end if;
    update public.tgg_video_timeline_items
    set start_seconds=start_seconds+v_duration,updated_at=now()
    where project_id=p_project_id and track_index=p_track_index and start_seconds>=v_start;
    get diagnostics v_shifted=row_count;
  end if;

  insert into public.tgg_video_timeline_items(
    user_id,project_id,asset_id,track_index,item_type,start_seconds,duration_seconds,source_in_seconds,settings
  ) values (
    v_uid,p_project_id,v_asset.id,p_track_index,v_type,v_start,v_duration,v_source_in,
    jsonb_build_object('source','source-monitor-v554','placement_mode',v_mode,'asset_id',v_asset.id,'source_range',jsonb_build_object('in',v_source_in,'duration',v_duration),'schema_version',7)
  ) returning * into v_item;

  update public.tgg_creative_projects set updated_at=now() where id=p_project_id;
  update public.tgg_studio_projects set revision=coalesce(revision,0)+1,updated_at=now() where id=p_project_id returning revision into v_new_revision;

  return jsonb_build_object('ok',true,'conflict',false,'occupied',false,'item',to_jsonb(v_item),'shifted_items',v_shifted,'base_revision',v_revision,'project_revision',v_new_revision);
end
$fn$;

revoke all on function public.tgg_video_studio_place_asset_range_v1(uuid,uuid,integer,numeric,numeric,numeric,text,bigint) from public,anon;
grant execute on function public.tgg_video_studio_place_asset_range_v1(uuid,uuid,integer,numeric,numeric,numeric,text,bigint) to authenticated;

