create or replace function private.tgg_world_v10_verify_crew_shared_session_impl(p_crew_mission_id uuid)
returns jsonb
language plpgsql
security definer
set search_path to 'public','private','auth','pg_temp'
as $function$
declare
  v_uid uuid := auth.uid();
  v_cm public.tgg_world_crew_missions%rowtype;
  v_mission public.tgg_world_missions%rowtype;
  v_session public.tgg_world_studio_sessions%rowtype;
  v_duration integer := 0;
  v_real_members integer := 0;
  v_verified integer := 0;
  v_completion jsonb := '{}'::jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;

  select * into v_cm
  from public.tgg_world_crew_missions
  where id=p_crew_mission_id
  for update;
  if v_cm.id is null then raise exception 'CREW_MISSION_NOT_FOUND'; end if;
  if v_cm.status not in ('in_progress','evidence_pending','completed') then
    raise exception 'CREW_MISSION_NOT_ACTIVE';
  end if;

  select * into v_mission from public.tgg_world_missions where id=v_cm.mission_id and active=true;
  if v_mission.id is null then raise exception 'MISSION_NOT_FOUND'; end if;
  if v_mission.objective_type <> 'shared_session' then raise exception 'SHARED_SESSION_MISSION_REQUIRED'; end if;

  if not exists(
    select 1 from public.tgg_world_crew_members_v10 m
    where m.crew_id=v_cm.crew_id and m.user_id=v_uid and m.status='active'
  ) then raise exception 'CREW_MEMBERSHIP_REQUIRED'; end if;

  if v_cm.session_id is null then raise exception 'CREW_SESSION_REQUIRED'; end if;
  select * into v_session
  from public.tgg_world_studio_sessions
  where id=v_cm.session_id and session_status='ended';
  if v_session.id is null then raise exception 'COMPLETED_STUDIO_SESSION_REQUIRED'; end if;

  if v_cm.project_id is not null and v_session.studio_project_id is distinct from v_cm.project_id then
    raise exception 'CREW_PROJECT_SESSION_MISMATCH';
  end if;

  v_duration := greatest(floor(extract(epoch from (coalesce(v_session.ended_at,now())-v_session.created_at)))::integer,0);
  if v_duration < 60 then raise exception 'QUALIFYING_SESSION_DURATION_REQUIRED'; end if;

  if not exists(
    select 1 from public.tgg_world_studio_session_members sm
    where sm.session_id=v_session.id and sm.user_id=v_uid
  ) then raise exception 'SESSION_PARTICIPATION_REQUIRED'; end if;

  select count(distinct sm.user_id) into v_real_members
  from public.tgg_world_studio_session_members sm
  join public.tgg_world_crew_members_v10 cmem
    on cmem.crew_id=v_cm.crew_id and cmem.user_id=sm.user_id and cmem.status='active'
  where sm.session_id=v_session.id;

  if v_real_members < 2 then raise exception 'TWO_REAL_COLLABORATORS_REQUIRED'; end if;

  insert into public.tgg_world_crew_mission_members(
    crew_mission_id,user_id,contribution,verified,verified_at
  ) values (
    v_cm.id,v_uid,
    jsonb_build_object(
      'source','world_studio_session',
      'session_id',v_session.id,
      'studio_project_id',v_session.studio_project_id,
      'duration_seconds',v_duration,
      'real_crew_members',v_real_members,
      'provenance_verified',true
    ),
    true,now()
  )
  on conflict(crew_mission_id,user_id) do update
    set contribution=coalesce(public.tgg_world_crew_mission_members.contribution,'{}'::jsonb)||excluded.contribution,
        verified=true,
        verified_at=coalesce(public.tgg_world_crew_mission_members.verified_at,excluded.verified_at);

  select count(distinct user_id) into v_verified
  from public.tgg_world_crew_mission_members
  where crew_mission_id=v_cm.id and verified=true;

  if v_verified >= 2 then
    v_completion := public.tgg_world_v4_verify_crew_mission(v_cm.id);
  else
    update public.tgg_world_crew_missions
    set status='evidence_pending',progress=least(99,greatest(progress,50)),updated_at=now()
    where id=v_cm.id and status<>'completed';
  end if;

  return jsonb_build_object(
    'ok',true,
    'crew_mission_id',v_cm.id,
    'session_id',v_session.id,
    'verified_user_id',v_uid,
    'duration_seconds',v_duration,
    'real_collaborators',v_real_members,
    'verified_members',v_verified,
    'required_members',2,
    'completed',coalesce((v_completion->>'ok')::boolean,false),
    'completion',v_completion
  );
end
$function$;

revoke all on function private.tgg_world_v10_verify_crew_shared_session_impl(uuid) from public,anon;
grant execute on function private.tgg_world_v10_verify_crew_shared_session_impl(uuid) to authenticated,service_role;

