create or replace function public.tgg_video_render_worker_complete(
  p_job_id uuid,
  p_lease_token uuid,
  p_storage_path text,
  p_format text,
  p_aspect_ratio text,
  p_resolution text default null,
  p_duration_seconds numeric default null,
  p_metadata jsonb default '{}'::jsonb
) returns jsonb
language plpgsql
set search_path='public','pg_catalog'
as $$
declare
  j public.tgg_video_studio_render_jobs;
  out_id uuid;
  asset_id uuid;
  current_revision bigint;
  v_format text:=lower(btrim(coalesce(p_format,'mp4')));
  v_mime text;
  v_width integer;
  v_height integer;
  v_size bigint;
  v_title text;
begin
  select * into j from public.tgg_video_studio_render_jobs where id=p_job_id and status='processing' and lease_token=p_lease_token for update;
  if j.id is null then return jsonb_build_object('ok',false,'lease_valid',false); end if;

  select coalesce(revision,0) into current_revision from public.tgg_studio_projects where id=j.project_id;
  if current_revision is distinct from coalesce(j.source_revision,0) then
    update public.tgg_video_studio_render_jobs
    set status='failed',error_message='STALE_SOURCE_REVISION_RESULT_REJECTED',finished_at=now(),lease_token=null,lease_expires_at=null,worker_heartbeat_at=now(),updated_at=now()
    where id=j.id;
    return jsonb_build_object('ok',false,'stale_source_revision',true,'queued_revision',j.source_revision,'current_revision',current_revision);
  end if;

  if nullif(btrim(coalesce(p_storage_path,'')),'') is null then raise exception 'OUTPUT_STORAGE_PATH_REQUIRED'; end if;
  if position(j.user_id::text||'/video/'||j.project_id::text||'/server-renders/'||j.id::text||'/' in p_storage_path)<>1 then raise exception 'OUTPUT_STORAGE_PATH_INVALID'; end if;
  if v_format not in ('mp4','webm','mov') then raise exception 'FORMAT_INVALID'; end if;
  if jsonb_typeof(coalesce(p_metadata,'{}'::jsonb))<>'object' then raise exception 'METADATA_INVALID'; end if;

  v_mime:=coalesce(nullif(p_metadata->>'mime_type',''),case v_format when 'mp4' then 'video/mp4' when 'webm' then 'video/webm' else 'video/quicktime' end);
  v_width:=case when coalesce(p_metadata->>'width','') ~ '^[0-9]{1,6}$' then (p_metadata->>'width')::integer else null end;
  v_height:=case when coalesce(p_metadata->>'height','') ~ '^[0-9]{1,6}$' then (p_metadata->>'height')::integer else null end;
  v_size:=case when coalesce(p_metadata->>'file_size_bytes','') ~ '^[0-9]{1,20}$' then (p_metadata->>'file_size_bytes')::bigint else null end;
  v_title:=coalesce(nullif(btrim(p_metadata->>'title'),''),'Server Render · '||coalesce(nullif(p_resolution,''),j.output_preset,'master'));

  insert into public.tgg_media_vault_assets(user_id,project_id,asset_type,title,source_kind,storage_path,public_url,mime_type,duration_seconds,width,height,file_size_bytes,metadata)
  values(j.user_id,j.project_id,'video',left(v_title,220),'render',p_storage_path,null,v_mime,p_duration_seconds,v_width,v_height,v_size,
    coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('kind','server_render','render_job_id',j.id,'provider_key',j.provider_key,'source_revision',j.source_revision))
  returning id into asset_id;

  insert into public.tgg_video_studio_render_outputs(render_job_id,user_id,format,aspect_ratio,resolution,duration_seconds,storage_path,public_url,status,metadata)
  values(j.id,j.user_id,v_format,coalesce(nullif(p_aspect_ratio,''),'16:9'),p_resolution,p_duration_seconds,p_storage_path,null,'ready',
    coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('provider_key',j.provider_key,'worker',j.leased_by,'source_revision',j.source_revision,'asset_id',asset_id))
  returning id into out_id;

  update public.tgg_video_studio_render_jobs
  set status='ready',progress=100,result_payload=jsonb_build_object('output_id',out_id,'asset_id',asset_id,'storage_path',p_storage_path,'format',v_format,'completed_by',j.leased_by),
      finished_at=now(),lease_token=null,lease_expires_at=null,worker_heartbeat_at=now(),updated_at=now()
  where id=j.id;

  return jsonb_build_object('ok',true,'output_id',out_id,'asset_id',asset_id,'job_id',j.id,'status','ready');
end$$;
revoke all on function public.tgg_video_render_worker_complete(uuid,uuid,text,text,text,text,numeric,jsonb) from public,anon,authenticated;
grant execute on function public.tgg_video_render_worker_complete(uuid,uuid,text,text,text,text,numeric,jsonb) to service_role;

