  values(left(btrim(p_worker_key),160),left(coalesce(nullif(btrim(p_provider_key),''),'github.ffmpeg.v1'),120),'online',coalesce(p_capabilities,'{}'::jsonb),coalesce(p_metadata,'{}'::jsonb),now(),now(),now())
  on conflict(worker_key) do update set provider_key=excluded.provider_key,status='online',capabilities=excluded.capabilities,metadata=excluded.metadata,last_seen_at=now(),updated_at=now()
  returning * into v;
  return jsonb_build_object('ok',true,'worker_key',v.worker_key,'provider_key',v.provider_key,'status',v.status,'last_seen_at',v.last_seen_at);
end$$;
