create or replace function public.tgg_video_render_worker_register(
  p_worker_key text,
  p_provider_key text default 'github.ffmpeg.v1',
  p_capabilities jsonb default '{}'::jsonb,
  p_metadata jsonb default '{}'::jsonb
) returns jsonb
language plpgsql
security definer
set search_path to 'private','public','pg_catalog'
as $$
declare
  v private.tgg_video_render_worker_runtime;
  v_provider text:=left(coalesce(nullif(btrim(p_provider_key),''),'github.ffmpeg.v1'),120);
  v_pruned integer:=0;
begin
  if nullif(btrim(coalesce(p_worker_key,'')),'') is null then raise exception 'WORKER_KEY_REQUIRED'; end if;
  if char_length(p_worker_key)>160 or char_length(coalesce(p_provider_key,''))>120 then raise exception 'WORKER_IDENTITY_INVALID'; end if;
  if jsonb_typeof(coalesce(p_capabilities,'{}'::jsonb))<>'object' or jsonb_typeof(coalesce(p_metadata,'{}'::jsonb))<>'object' then raise exception 'WORKER_METADATA_INVALID'; end if;

  insert into private.tgg_video_render_worker_runtime(worker_key,provider_key,status,capabilities,metadata,last_seen_at,created_at,updated_at)
  values(left(btrim(p_worker_key),160),v_provider,'online',coalesce(p_capabilities,'{}'::jsonb),coalesce(p_metadata,'{}'::jsonb),now(),now(),now())
  on conflict(worker_key) do update
    set provider_key=excluded.provider_key,status='online',capabilities=excluded.capabilities,metadata=excluded.metadata,last_seen_at=now(),updated_at=now()
  returning * into v;

  delete from private.tgg_video_render_worker_runtime r
  where r.provider_key=v_provider
    and r.worker_key<>v.worker_key
    and r.last_seen_at<now()-interval '24 hours';
  get diagnostics v_pruned = row_count;

  return jsonb_build_object('ok',true,'worker_key',v.worker_key,'provider_key',v.provider_key,'status',v.status,'last_seen_at',v.last_seen_at,'pruned_stale_rows',v_pruned);
end$$;

revoke all on function public.tgg_video_render_worker_register(text,text,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.tgg_video_render_worker_register(text,text,jsonb,jsonb) to service_role;

-- ============================================================
-- MIGRATION 20260910141934 consolidate_multiple_permissive_select_policies_v1
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

-- Preserve exact effective access while eliminating duplicate permissive SELECT evaluation.

-- 1) content_items
DROP POLICY IF EXISTS "Creators can view own content" ON public.content_items;
DROP POLICY IF EXISTS "Public can view published content" ON public.content_items;
CREATE POLICY "content items public published read" ON public.content_items
  FOR SELECT TO anon
  USING ((status = 'PUBLISHED'::text) AND ((visibility = 'PUBLIC'::text) OR (creator_id = (SELECT auth.uid()))));
CREATE POLICY "content items authenticated read" ON public.content_items
  FOR SELECT TO authenticated
  USING (((SELECT auth.uid()) = creator_id) OR ((status = 'PUBLISHED'::text) AND ((visibility = 'PUBLIC'::text) OR (creator_id = (SELECT auth.uid())))));

-- 2) creator profile highlights: split owner ALL into exact per-command policies.
DROP POLICY IF EXISTS "profile highlights owner manage" ON public.tgg_creator_profile_highlights;
DROP POLICY IF EXISTS "profile highlights public read" ON public.tgg_creator_profile_highlights;
CREATE POLICY "profile highlights anon active read" ON public.tgg_creator_profile_highlights
  FOR SELECT TO anon USING (is_active = true);
CREATE POLICY "profile highlights authenticated read" ON public.tgg_creator_profile_highlights
  FOR SELECT TO authenticated USING (((SELECT auth.uid()) = creator_id) OR (is_active = true));
CREATE POLICY "profile highlights owner insert" ON public.tgg_creator_profile_highlights
  FOR INSERT TO authenticated WITH CHECK ((SELECT auth.uid()) = creator_id);
CREATE POLICY "profile highlights owner update" ON public.tgg_creator_profile_highlights
  FOR UPDATE TO authenticated USING ((SELECT auth.uid()) = creator_id) WITH CHECK ((SELECT auth.uid()) = creator_id);
CREATE POLICY "profile highlights owner delete" ON public.tgg_creator_profile_highlights
  FOR DELETE TO authenticated USING ((SELECT auth.uid()) = creator_id);

-- 3) live activity presence: split owner ALL; preserve public non-offline visibility.
DROP POLICY IF EXISTS "presence owner all" ON public.tgg_live_activity_presence;
DROP POLICY IF EXISTS "presence public read" ON public.tgg_live_activity_presence;
CREATE POLICY "live activity presence anon read" ON public.tgg_live_activity_presence
  FOR SELECT TO anon USING (activity_type <> 'offline'::text);
CREATE POLICY "live activity presence authenticated read" ON public.tgg_live_activity_presence
  FOR SELECT TO authenticated USING (((SELECT auth.uid()) = user_id) OR (activity_type <> 'offline'::text));
CREATE POLICY "live activity presence owner insert" ON public.tgg_live_activity_presence
  FOR INSERT TO authenticated WITH CHECK ((SELECT auth.uid()) = user_id);
CREATE POLICY "live activity presence owner update" ON public.tgg_live_activity_presence
  FOR UPDATE TO authenticated USING ((SELECT auth.uid()) = user_id) WITH CHECK ((SELECT auth.uid()) = user_id);
CREATE POLICY "live activity presence owner delete" ON public.tgg_live_activity_presence
  FOR DELETE TO authenticated USING ((SELECT auth.uid()) = user_id);

-- 4) live presence signals: split owner ALL; preserve non-expired public visibility.
DROP POLICY IF EXISTS "presence owner write" ON public.tgg_live_presence_signals;
DROP POLICY IF EXISTS "presence public read" ON public.tgg_live_presence_signals;
CREATE POLICY "live presence signals anon read" ON public.tgg_live_presence_signals
  FOR SELECT TO anon USING ((expires_at IS NULL) OR (expires_at > now()));
CREATE POLICY "live presence signals authenticated read" ON public.tgg_live_presence_signals
  FOR SELECT TO authenticated USING (((SELECT auth.uid()) = user_id) OR (expires_at IS NULL) OR (expires_at > now()));
CREATE POLICY "live presence signals owner insert" ON public.tgg_live_presence_signals
  FOR INSERT TO authenticated WITH CHECK ((SELECT auth.uid()) = user_id);
CREATE POLICY "live presence signals owner update" ON public.tgg_live_presence_signals
  FOR UPDATE TO authenticated USING ((SELECT auth.uid()) = user_id) WITH CHECK ((SELECT auth.uid()) = user_id);
CREATE POLICY "live presence signals owner delete" ON public.tgg_live_presence_signals
  FOR DELETE TO authenticated USING ((SELECT auth.uid()) = user_id);

-- 5) social activity stream
DROP POLICY IF EXISTS "activity public read" ON public.tgg_social_activity_stream;
DROP POLICY IF EXISTS "activity target read" ON public.tgg_social_activity_stream;
CREATE POLICY "activity anon public read" ON public.tgg_social_activity_stream
  FOR SELECT TO anon USING (target_user_id IS NULL);
CREATE POLICY "activity authenticated read" ON public.tgg_social_activity_stream
  FOR SELECT TO authenticated
  USING ((target_user_id IS NULL) OR ((SELECT auth.uid()) = target_user_id) OR ((SELECT auth.uid()) = actor_id));

-- 6) social feed items
DROP POLICY IF EXISTS "feed items owner read" ON public.tgg_social_feed_items;
DROP POLICY IF EXISTS "feed items public read" ON public.tgg_social_feed_items;
CREATE POLICY "feed items anon public read" ON public.tgg_social_feed_items
  FOR SELECT TO anon USING (user_id IS NULL);
CREATE POLICY "feed items authenticated read" ON public.tgg_social_feed_items
  FOR SELECT TO authenticated USING (((SELECT auth.uid()) = user_id) OR (user_id IS NULL));

-- 7) stories moments
DROP POLICY IF EXISTS "moments owner read" ON public.tgg_stories_moments;
DROP POLICY IF EXISTS "moments public active read" ON public.tgg_stories_moments;
CREATE POLICY "moments anon active read" ON public.tgg_stories_moments
  FOR SELECT TO anon
  USING ((status = 'active'::text) AND ((expires_at IS NULL) OR (expires_at > now())) AND (visibility = 'public'::text));
CREATE POLICY "moments authenticated read" ON public.tgg_stories_moments
  FOR SELECT TO authenticated
  USING (((SELECT auth.uid()) = user_id) OR ((status = 'active'::text) AND ((expires_at IS NULL) OR (expires_at > now())) AND (visibility = 'public'::text)));


