create table if not exists public.tgg_world_household_relationships (
  user_id uuid not null references auth.users(id) on delete cascade,
  member_id uuid not null references public.tgg_world_household_members(id) on delete cascade,
  bond_xp integer not null default 0 check (bond_xp >= 0),
  bond_level integer not null default 1 check (bond_level between 1 and 50),
  trust_score integer not null default 50 check (trust_score between 0 and 100),
  interactions_completed integer not null default 0 check (interactions_completed >= 0),
  last_action_type text,
  last_interaction_at timestamptz,
  metadata jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  primary key (user_id, member_id)
);

create table if not exists public.tgg_world_household_action_log (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  household_id uuid not null references public.tgg_world_households(id) on delete cascade,
  member_id uuid not null references public.tgg_world_household_members(id) on delete cascade,
  action_type text not null check (action_type in ('hangout','meal','studio_session','workout','call','support','celebrate','chore')),
  bond_xp_delta integer not null default 0,
  trust_delta integer not null default 0,
  idempotency_key text not null,
  result jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique(user_id,idempotency_key)
);

create index if not exists tgg_world_household_relationships_member_idx on public.tgg_world_household_relationships(member_id);
create index if not exists tgg_world_household_action_log_user_time_idx on public.tgg_world_household_action_log(user_id,created_at desc);
create index if not exists tgg_world_household_action_log_household_idx on public.tgg_world_household_action_log(household_id);
create index if not exists tgg_world_household_action_log_member_idx on public.tgg_world_household_action_log(member_id);

alter table public.tgg_world_household_relationships enable row level security;
alter table public.tgg_world_household_action_log enable row level security;

drop policy if exists tgg_world_household_relationships_read on public.tgg_world_household_relationships;
create policy tgg_world_household_relationships_read on public.tgg_world_household_relationships
for select to authenticated using (user_id = (select auth.uid()));

drop policy if exists tgg_world_household_action_log_read on public.tgg_world_household_action_log;
create policy tgg_world_household_action_log_read on public.tgg_world_household_action_log
for select to authenticated using (user_id = (select auth.uid()));

create or replace function private.tgg_world_v11_household_action_impl(
  p_member_id uuid,
  p_action_type text,
  p_idempotency_key text
) returns jsonb
language plpgsql
security definer
set search_path to ''
as $$
declare
  v_uid uuid := auth.uid();
  v_member public.tgg_world_household_members%rowtype;
  v_household public.tgg_world_households%rowtype;
  v_existing public.tgg_world_household_action_log%rowtype;
  v_rel public.tgg_world_household_relationships%rowtype;
  v_action text := lower(trim(coalesce(p_action_type,'')));
  v_key text := trim(coalesce(p_idempotency_key,''));
  v_xp integer;
  v_trust integer;
  v_result jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if p_member_id is null then raise exception 'MEMBER_REQUIRED'; end if;
  if length(v_key) < 8 or length(v_key) > 120 then raise exception 'IDEMPOTENCY_KEY_REQUIRED'; end if;

  select * into v_existing
  from public.tgg_world_household_action_log
  where user_id=v_uid and idempotency_key=v_key;
  if found then return v_existing.result || jsonb_build_object('replayed',true); end if;

  select m.* into v_member
  from public.tgg_world_household_members m
  join public.tgg_world_households h on h.id=m.household_id
  where m.id=p_member_id
    and m.status in ('active','away')
    and (
      h.owner_user_id=v_uid
      or exists (
        select 1 from public.tgg_world_household_members mine
        where mine.household_id=h.id
          and mine.member_user_id=v_uid
          and mine.status in ('active','away')
      )
    )
  limit 1;
  if not found then raise exception 'HOUSEHOLD_MEMBER_NOT_AVAILABLE'; end if;
  if v_member.member_user_id=v_uid then raise exception 'CANNOT_TARGET_SELF'; end if;

  select * into v_household from public.tgg_world_households where id=v_member.household_id;

  case v_action
    when 'hangout' then v_xp:=25; v_trust:=3;
    when 'meal' then v_xp:=18; v_trust:=2;
    when 'studio_session' then v_xp:=30; v_trust:=2;
    when 'workout' then v_xp:=22; v_trust:=2;
    when 'call' then v_xp:=15; v_trust:=2;
    when 'support' then v_xp:=35; v_trust:=5;
    when 'celebrate' then v_xp:=28; v_trust:=4;
    when 'chore' then v_xp:=20; v_trust:=2;
    else raise exception 'INVALID_HOUSEHOLD_ACTION';
  end case;

  if exists (
    select 1 from public.tgg_world_household_action_log l
    where l.user_id=v_uid and l.member_id=p_member_id and l.action_type=v_action
      and l.created_at > now() - interval '3 seconds'
  ) then raise exception 'ACTION_TOO_FAST'; end if;

  insert into public.tgg_world_household_relationships(user_id,member_id,bond_xp,bond_level,trust_score,interactions_completed,last_action_type,last_interaction_at)
  values(v_uid,p_member_id,v_xp,least(50,1+(v_xp/250)),least(100,50+v_trust),1,v_action,now())
  on conflict(user_id,member_id) do update
  set bond_xp=public.tgg_world_household_relationships.bond_xp+excluded.bond_xp,
      bond_level=least(50,1+((public.tgg_world_household_relationships.bond_xp+excluded.bond_xp)/250)),
      trust_score=greatest(0,least(100,public.tgg_world_household_relationships.trust_score+v_trust)),
      interactions_completed=public.tgg_world_household_relationships.interactions_completed+1,
      last_action_type=v_action,
      last_interaction_at=now(),
      updated_at=now()
  returning * into v_rel;

  v_result:=jsonb_build_object(
    'ok',true,
    'household_id',v_household.id,
    'household_name',v_household.name,
    'member_id',v_member.id,
    'display_name',coalesce(v_member.display_name,v_member.relationship_role),
    'relationship_role',v_member.relationship_role,
    'action_type',v_action,
    'bond_xp_delta',v_xp,
    'trust_delta',v_trust,
    'bond_xp',v_rel.bond_xp,
    'bond_level',v_rel.bond_level,
    'trust_score',v_rel.trust_score,
    'interactions_completed',v_rel.interactions_completed,
    'virtual_currency_reward',0,
    'real_money',false,
    'replayed',false
  );

  insert into public.tgg_world_household_action_log(user_id,household_id,member_id,action_type,bond_xp_delta,trust_delta,idempotency_key,result)
  values(v_uid,v_household.id,v_member.id,v_action,v_xp,v_trust,v_key,v_result);

  return v_result;
exception
  when unique_violation then
    select * into v_existing from public.tgg_world_household_action_log where user_id=v_uid and idempotency_key=v_key;
    if found then return v_existing.result || jsonb_build_object('replayed',true); end if;
    raise;
end
$$;

create or replace function private.tgg_world_v11_household_gameplay_bundle_impl()
returns jsonb
language plpgsql
stable
security definer
set search_path to ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  return jsonb_build_object(
    'ok',true,
    'version','WORLD-V11.2-HOUSEHOLD-GAMEPLAY-1.0',
    'actions',jsonb_build_array(
      jsonb_build_object('key','hangout','label','Hang Out','bond_xp',25,'trust',3),
      jsonb_build_object('key','meal','label','Share a Meal','bond_xp',18,'trust',2),
      jsonb_build_object('key','studio_session','label','Studio Session','bond_xp',30,'trust',2),
      jsonb_build_object('key','workout','label','Work Out','bond_xp',22,'trust',2),
      jsonb_build_object('key','call','label','Call','bond_xp',15,'trust',2),
      jsonb_build_object('key','support','label','Show Support','bond_xp',35,'trust',5),
      jsonb_build_object('key','celebrate','label','Celebrate','bond_xp',28,'trust',4),
      jsonb_build_object('key','chore','label','Handle a Chore','bond_xp',20,'trust',2)
    ),
    'relationships',coalesce((
      select jsonb_agg(jsonb_build_object(
        'member_id',r.member_id,
        'display_name',coalesce(m.display_name,m.relationship_role),
        'relationship_role',m.relationship_role,
        'is_npc',m.member_user_id is null,
        'bond_xp',r.bond_xp,
        'bond_level',r.bond_level,
        'trust_score',r.trust_score,
        'interactions_completed',r.interactions_completed,
        'last_action_type',r.last_action_type,
        'last_interaction_at',r.last_interaction_at
      ) order by r.bond_level desc,r.bond_xp desc)
      from public.tgg_world_household_relationships r
      join public.tgg_world_household_members m on m.id=r.member_id
      where r.user_id=v_uid
    ),'[]'::jsonb),
    'recent_actions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',l.id,
        'member_id',l.member_id,
        'display_name',coalesce(m.display_name,m.relationship_role),
        'action_type',l.action_type,
        'bond_xp_delta',l.bond_xp_delta,
        'trust_delta',l.trust_delta,
        'created_at',l.created_at
      ) order by l.created_at desc)
      from (
        select * from public.tgg_world_household_action_log
        where user_id=v_uid order by created_at desc limit 25
      ) l join public.tgg_world_household_members m on m.id=l.member_id
    ),'[]'::jsonb),
    'real_money',false
  );
end
$$;

create or replace function public.tgg_world_v11_household_action(p_member_id uuid,p_action_type text,p_idempotency_key text)
returns jsonb language sql set search_path to '' as $$
  select private.tgg_world_v11_household_action_impl(p_member_id,p_action_type,p_idempotency_key);
$$;

create or replace function public.tgg_world_v11_household_gameplay_bundle()
returns jsonb language sql stable set search_path to '' as $$
  select private.tgg_world_v11_household_gameplay_bundle_impl();
$$;

revoke all on function public.tgg_world_v11_household_action(uuid,text,text) from public,anon;
revoke all on function public.tgg_world_v11_household_gameplay_bundle() from public,anon;
grant execute on function public.tgg_world_v11_household_action(uuid,text,text) to authenticated;
grant execute on function public.tgg_world_v11_household_gameplay_bundle() to authenticated;

-- ============================================================
-- MIGRATION 20260910153506 tgg_operational_exposure_audit_guard_aware_v1_1
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

create or replace function private.tgg_operational_exposure_audit()
returns jsonb
language plpgsql
security definer
set search_path to ''
as $function$
declare
  v_tables jsonb;
  v_views jsonb;
  v_functions jsonb;
  v_guarded_functions jsonb;
  v_table_count integer:=0;
  v_view_count integer:=0;
  v_function_count integer:=0;
  v_guarded_function_count integer:=0;
  v_public_anon_count integer:=0;
  v_auth_unguarded_count integer:=0;
  v_payload jsonb;
begin
  with exposed as (
    select c.relname
    from pg_catalog.pg_class c
    join pg_catalog.pg_namespace n on n.oid=c.relnamespace
    where n.nspname='public'
      and c.relkind='r'
      and not c.relrowsecurity
      and (
        pg_catalog.has_table_privilege('anon','public.'||pg_catalog.quote_ident(c.relname),'SELECT')
        or pg_catalog.has_table_privilege('anon','public.'||pg_catalog.quote_ident(c.relname),'INSERT')
        or pg_catalog.has_table_privilege('anon','public.'||pg_catalog.quote_ident(c.relname),'UPDATE')
        or pg_catalog.has_table_privilege('anon','public.'||pg_catalog.quote_ident(c.relname),'DELETE')
        or pg_catalog.has_table_privilege('authenticated','public.'||pg_catalog.quote_ident(c.relname),'SELECT')
        or pg_catalog.has_table_privilege('authenticated','public.'||pg_catalog.quote_ident(c.relname),'INSERT')
        or pg_catalog.has_table_privilege('authenticated','public.'||pg_catalog.quote_ident(c.relname),'UPDATE')
        or pg_catalog.has_table_privilege('authenticated','public.'||pg_catalog.quote_ident(c.relname),'DELETE')
      )
  )
  select count(*),coalesce(jsonb_agg(relname order by relname),'[]'::jsonb)
  into v_table_count,v_tables
  from exposed;

  with exposed as (
    select c.relname
    from pg_catalog.pg_class c
    join pg_catalog.pg_namespace n on n.oid=c.relnamespace
    where n.nspname='public'
      and c.relkind='v'
      and (
        pg_catalog.has_table_privilege('anon','public.'||pg_catalog.quote_ident(c.relname),'SELECT')
        or pg_catalog.has_table_privilege('authenticated','public.'||pg_catalog.quote_ident(c.relname),'SELECT')
      )
      and not ('security_invoker=true'=any(coalesce(c.reloptions,array[]::text[])))
  )
  select count(*),coalesce(jsonb_agg(relname order by relname),'[]'::jsonb)
  into v_view_count,v_views
  from exposed;

  with secdef as (
    select p.oid,
           p.proname||'('||pg_catalog.pg_get_function_identity_arguments(p.oid)||')' signature,
           pg_catalog.has_function_privilege('public',p.oid,'EXECUTE') as public_exec,
           pg_catalog.has_function_privilege('anon',p.oid,'EXECUTE') as anon_exec,
           pg_catalog.has_function_privilege('authenticated',p.oid,'EXECUTE') as auth_exec,
           position('auth.uid()' in lower(pg_catalog.pg_get_functiondef(p.oid)))>0 as has_uid_guard
    from pg_catalog.pg_proc p
    join pg_catalog.pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.prosecdef=true
  ), unsafe as (
    select signature,
           (public_exec or anon_exec) as public_or_anon,
           (auth_exec and not has_uid_guard) as auth_unguarded
    from secdef
    where public_exec or anon_exec or (auth_exec and not has_uid_guard)
  ), guarded as (
    select signature
    from secdef
    where auth_exec and has_uid_guard and not public_exec and not anon_exec
  )
  select
    (select count(*) from unsafe),
    (select coalesce(jsonb_agg(signature order by signature),'[]'::jsonb) from unsafe),
    (select count(*) from unsafe where public_or_anon),
    (select count(*) from unsafe where auth_unguarded),
    (select count(*) from guarded),
    (select coalesce(jsonb_agg(signature order by signature),'[]'::jsonb) from guarded)
  into v_function_count,v_functions,v_public_anon_count,v_auth_unguarded_count,v_guarded_function_count,v_guarded_functions;

  v_payload:=jsonb_build_object(
    'ok',(v_table_count+v_view_count+v_function_count)=0,
    'version','EXPOSURE-AUDIT-1.1',
    'tables_without_rls_with_api_grants',v_table_count,
    'non_invoker_exposed_views',v_view_count,
    'unsafe_security_definer_functions',v_function_count,
    'public_or_anon_security_definer_functions',v_public_anon_count,
    'authenticated_unguarded_security_definer_functions',v_auth_unguarded_count,
    'authenticated_guarded_security_definer_functions',v_guarded_function_count,
    'tables',v_tables,
    'views',v_views,
    'functions',v_functions,
    'guarded_functions_review_inventory',v_guarded_functions,
    'guard_semantics','authenticated SECURITY DEFINER functions are not classified as exposure when direct PUBLIC/anon EXECUTE is absent and the function definition contains auth.uid() ownership/authentication gating',
    'future_default_acl_note','supabase_admin default privileges require platform-level permission; monitor catches newly exposed objects',
    'checked_at',now()
  );

  if (v_table_count+v_view_count+v_function_count)>0 then
    insert into public.tgg_operational_alerts(alert_key,severity,subsystem,last_payload)
    values('security:database_exposure','critical','database_exposure',v_payload)
    on conflict(alert_key) do update
    set status='open',last_seen=now(),occurrence_count=public.tgg_operational_alerts.occurrence_count+1,last_payload=excluded.last_payload,severity='critical';
  else
    update public.tgg_operational_alerts
    set status='resolved',last_seen=now(),last_payload=v_payload
    where alert_key='security:database_exposure' and status<>'resolved';
  end if;

  return v_payload;
end;
$function$;

