  meeting_type text not null default 'intro' check(meeting_type in ('intro','follow_up','business','show','battle')),
  relationship_xp_delta integer not null default 0 check(relationship_xp_delta between 0 and 1000),
  trust_delta integer not null default 0 check(trust_delta between 0 and 100),
  idempotency_key text not null,
  result jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique(user_id,idempotency_key)
);

create table if not exists private.tgg_world_v12_show_bookings(
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  character_id uuid not null references public.world_characters(id) on delete cascade,
  contact_key text not null references public.tgg_world_industry_contacts(contact_key) on delete restrict,
  event_id uuid not null unique references public.tgg_world_events(id) on delete cascade,
  title text not null,
  status text not null default 'booked' check(status in ('booked','completed','cancelled')),
  starts_at timestamptz not null,
  project_id uuid,
  session_id uuid,
  idempotency_key text not null,
  performance_score numeric not null default 0,
  audience_gain bigint not null default 0,
  reputation_gain bigint not null default 0,
  xp_gain bigint not null default 0,
  completed_at timestamptz,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(user_id,idempotency_key)
);

create table if not exists private.tgg_world_v12_rap_battles(
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  character_id uuid not null references public.world_characters(id) on delete cascade,
  event_id uuid not null unique references public.tgg_world_events(id) on delete cascade,
  opponent_user_id uuid references auth.users(id) on delete set null,
  opponent_character_id uuid references public.world_characters(id) on delete set null,
  opponent_contact_key text references public.tgg_world_industry_contacts(contact_key) on delete set null,
  opponent_label text not null,
  status text not null default 'live' check(status in ('live','completed','cancelled')),
  rounds_total integer not null default 3 check(rounds_total between 1 and 9),
  rounds_completed integer not null default 0 check(rounds_completed >= 0),
  player_score numeric not null default 0,
  opponent_score numeric not null default 0,
  crowd_energy numeric not null default 0,
  idempotency_key text not null,
  winner_side text check(winner_side is null or winner_side in ('player','opponent','draw')),
  completed_at timestamptz,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(user_id,idempotency_key),
  check((opponent_user_id is not null)::int + (opponent_contact_key is not null)::int = 1)
);

create table if not exists private.tgg_world_v12_rap_battle_rounds(
  id uuid primary key default gen_random_uuid(),
  battle_id uuid not null references private.tgg_world_v12_rap_battles(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  round_number integer not null check(round_number between 1 and 9),
  player_score numeric not null check(player_score between 0 and 100),
  opponent_score numeric not null check(opponent_score between 0 and 100),
  crowd_energy numeric not null check(crowd_energy between 0 and 100),
  idempotency_key text not null,
  created_at timestamptz not null default now(),
  unique(battle_id,round_number),
  unique(battle_id,idempotency_key)
);

create index if not exists tgg_world_v12_meetings_user_created_idx on private.tgg_world_v12_contact_meetings(user_id,created_at desc);
create index if not exists tgg_world_v12_show_user_status_idx on private.tgg_world_v12_show_bookings(user_id,status,starts_at desc);
create index if not exists tgg_world_v12_battle_user_status_idx on private.tgg_world_v12_rap_battles(user_id,status,created_at desc);
create index if not exists tgg_world_v12_round_battle_idx on private.tgg_world_v12_rap_battle_rounds(battle_id,round_number);

revoke all on private.tgg_world_v12_contact_meetings from public,anon,authenticated;
revoke all on private.tgg_world_v12_show_bookings from public,anon,authenticated;
revoke all on private.tgg_world_v12_rap_battles from public,anon,authenticated;
revoke all on private.tgg_world_v12_rap_battle_rounds from public,anon,authenticated;

create or replace function public.tgg_world_v12_meet_industry_contact(p_contact_key text,p_idempotency_key text)
returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_uid uuid:=auth.uid();
  v_character_id uuid;
  v_rep bigint:=0;
  v_required integer;
  v_meeting_id uuid;
  v_rel record;
  v_existing jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(p_idempotency_key)>160 then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;

  select result into v_existing from private.tgg_world_v12_contact_meetings where user_id=v_uid and idempotency_key=p_idempotency_key limit 1;
  if v_existing is not null then return v_existing||jsonb_build_object('idempotent',true); end if;

  select id into v_character_id from public.world_characters where user_id=v_uid and character_status='active' order by updated_at desc limit 1;
  if v_character_id is null then raise exception 'WORLD_CHARACTER_REQUIRED' using errcode='22023'; end if;
  select coalesce(reputation,0) into v_rep from public.tgg_world_players where user_id=v_uid limit 1;

  select reputation_required into v_required from public.tgg_world_industry_contacts where contact_key=p_contact_key and enabled=true;
  if v_required is null then raise exception 'CONTACT_NOT_FOUND' using errcode='22023'; end if;
  if v_rep<v_required then raise exception 'REPUTATION_REQUIRED:%',v_required using errcode='22023'; end if;

  insert into public.tgg_world_contact_relationships(character_id,contact_key,relationship_xp,relationship_level,trust_score,meetings_completed,last_interaction_at,memory,updated_at)
  values(v_character_id,p_contact_key,20,1,8,1,now(),jsonb_build_object('last_meeting','v12_intro'),now())
  on conflict(character_id,contact_key) do update set
    relationship_xp=public.tgg_world_contact_relationships.relationship_xp+20,
    relationship_level=greatest(public.tgg_world_contact_relationships.relationship_level,1+((public.tgg_world_contact_relationships.relationship_xp+20)/100)),
    trust_score=least(100,public.tgg_world_contact_relationships.trust_score+5),
    meetings_completed=public.tgg_world_contact_relationships.meetings_completed+1,
    last_interaction_at=now(),
    memory=coalesce(public.tgg_world_contact_relationships.memory,'{}'::jsonb)||jsonb_build_object('last_meeting','v12_intro','last_meeting_at',now()),
    updated_at=now()
  returning relationship_xp,relationship_level,trust_score,meetings_completed into v_rel;

  insert into private.tgg_world_v12_contact_meetings(user_id,character_id,contact_key,relationship_xp_delta,trust_delta,idempotency_key)
  values(v_uid,v_character_id,p_contact_key,20,5,p_idempotency_key)
  returning id into v_meeting_id;

  v_existing:=jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','meeting_id',v_meeting_id,'contact_key',p_contact_key,
    'relationship',jsonb_build_object('xp',v_rel.relationship_xp,'level',v_rel.relationship_level,'trust',v_rel.trust_score,'meetings',v_rel.meetings_completed),
    'idempotent',false);
  update private.tgg_world_v12_contact_meetings set result=v_existing where id=v_meeting_id;
  return v_existing;
end $$;

create or replace function public.tgg_world_v12_book_show(
  p_contact_key text,p_title text,p_starts_at timestamptz,p_project_id uuid,p_session_id uuid,p_idempotency_key text
) returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_uid uuid:=auth.uid();
  v_character_id uuid;
  v_player record;
  v_contact record;
  v_rel record;
  v_event_id uuid;
  v_booking_id uuid;
  v_existing private.tgg_world_v12_show_bookings%rowtype;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(p_idempotency_key)>160 then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  if nullif(btrim(coalesce(p_title,'')),'') is null or length(p_title)>120 then raise exception 'SHOW_TITLE_REQUIRED' using errcode='22023'; end if;
  if p_starts_at is null or p_starts_at<now()-interval '15 minutes' or p_starts_at>now()+interval '180 days' then raise exception 'INVALID_SHOW_TIME' using errcode='22023'; end if;

  select * into v_existing from private.tgg_world_v12_show_bookings where user_id=v_uid and idempotency_key=p_idempotency_key limit 1;
  if found then return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','booking_id',v_existing.id,'event_id',v_existing.event_id,'status',v_existing.status,'idempotent',true); end if;

  select id into v_character_id from public.world_characters where user_id=v_uid and character_status='active' order by updated_at desc limit 1;
  if v_character_id is null then raise exception 'WORLD_CHARACTER_REQUIRED' using errcode='22023'; end if;
  select * into v_player from public.tgg_world_players where user_id=v_uid limit 1;
  if not found then raise exception 'WORLD_PLAYER_REQUIRED' using errcode='22023'; end if;

  select * into v_contact from public.tgg_world_industry_contacts where contact_key=p_contact_key and enabled=true;
  if not found then raise exception 'CONTACT_NOT_FOUND' using errcode='22023'; end if;
  if lower(v_contact.role_title) not like '%promoter%' and lower(v_contact.role_title) not like '%booking%' and lower(v_contact.role_title) not like '%director%' and lower(v_contact.role_title) not like '%a&r%' then
    raise exception 'CONTACT_CANNOT_BOOK_SHOWS' using errcode='22023';
  end if;
  if v_player.reputation<v_contact.reputation_required then raise exception 'REPUTATION_REQUIRED:%',v_contact.reputation_required using errcode='22023'; end if;

  select * into v_rel from public.tgg_world_contact_relationships where character_id=v_character_id and contact_key=p_contact_key;
  if not found or v_rel.meetings_completed<1 then raise exception 'MEET_CONTACT_FIRST' using errcode='22023'; end if;

  insert into public.tgg_world_events(host_user_id,event_type,title,status,starts_at,project_id,session_id,visibility,metadata)
  values(v_uid,'concert',btrim(p_title),'scheduled',p_starts_at,p_project_id,p_session_id,'public',
    jsonb_build_object('world_layer','v12','booking_contact',p_contact_key,'booking_type','industry_show'))
  returning id into v_event_id;

  insert into public.tgg_world_event_participants(event_id,user_id,role,joined_at,metadata)
  values(v_event_id,v_uid,'performer',now(),jsonb_build_object('world_layer','v12'))
  on conflict do nothing;

  insert into private.tgg_world_v12_show_bookings(user_id,character_id,contact_key,event_id,title,starts_at,project_id,session_id,idempotency_key,metadata)
  values(v_uid,v_character_id,p_contact_key,v_event_id,btrim(p_title),p_starts_at,p_project_id,p_session_id,p_idempotency_key,
    jsonb_build_object('contact_trust_at_booking',v_rel.trust_score,'player_reputation_at_booking',v_player.reputation))
  returning id into v_booking_id;

  update public.tgg_world_contact_relationships set relationship_xp=relationship_xp+10,trust_score=least(100,trust_score+2),last_interaction_at=now(),updated_at=now()
  where character_id=v_character_id and contact_key=p_contact_key;

  return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','booking_id',v_booking_id,'event_id',v_event_id,'status','booked','starts_at',p_starts_at,'idempotent',false);
end $$;

create or replace function public.tgg_world_v12_perform_show(p_booking_id uuid,p_idempotency_key text)
returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_uid uuid:=auth.uid();
  v_booking private.tgg_world_v12_show_bookings%rowtype;
  v_rep bigint:=0;
  v_trust integer:=0;
  v_jitter integer;
  v_score numeric;
  v_energy numeric;
  v_audience bigint;
  v_rep_gain bigint;
  v_xp bigint;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(p_idempotency_key)>160 then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;

  select * into v_booking from private.tgg_world_v12_show_bookings where id=p_booking_id and user_id=v_uid for update;
  if not found then raise exception 'SHOW_BOOKING_NOT_FOUND' using errcode='22023'; end if;
  if v_booking.status='completed' then
    return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','booking_id',v_booking.id,'event_id',v_booking.event_id,'status','completed','performance_score',v_booking.performance_score,'audience_gain',v_booking.audience_gain,'reputation_gain',v_booking.reputation_gain,'xp_gain',v_booking.xp_gain,'idempotent',true);
  end if;
  if v_booking.status<>'booked' then raise exception 'SHOW_NOT_ACTIVE' using errcode='22023'; end if;
  if v_booking.starts_at>now()+interval '30 minutes' then raise exception 'SHOW_NOT_STARTED_YET' using errcode='22023'; end if;

  select coalesce(reputation,0) into v_rep from public.tgg_world_players where user_id=v_uid limit 1;
  select coalesce(trust_score,0) into v_trust from public.tgg_world_contact_relationships where character_id=v_booking.character_id and contact_key=v_booking.contact_key;
  v_jitter:=(((hashtextextended(v_booking.id::text||':show',0)%21)+21)%21)::integer-10;
  v_score:=greatest(20,least(100,55+least(20,(v_rep/25)::integer)+least(12,(v_trust/8)::integer)+v_jitter));
  v_energy:=greatest(20,least(100,round((v_score+60+v_trust/2.0)/2)));
  v_audience:=greatest(20,round(v_energy*2+least(200,v_rep/5.0))::bigint);
  v_rep_gain:=greatest(3,round(v_score/12)::bigint);
  v_xp:=greatest(50,round(v_score*1.5)::bigint);

  update public.tgg_world_events set status='completed',ends_at=now(),updated_at=now(),metadata=metadata||jsonb_build_object('performance_score',v_score,'crowd_energy',v_energy) where id=v_booking.event_id and host_user_id=v_uid;
  insert into public.tgg_world_event_results(event_id,peak_audience,total_reactions,total_votes,crowd_energy,winner_user_id,result_payload,finalized_at)
  values(v_booking.event_id,v_audience::integer,0,0,v_energy,v_uid,jsonb_build_object('world_layer','v12','kind','concert','performance_score',v_score),now())
  on conflict(event_id) do update set peak_audience=excluded.peak_audience,crowd_energy=excluded.crowd_energy,winner_user_id=excluded.winner_user_id,result_payload=excluded.result_payload,finalized_at=excluded.finalized_at;
  update public.tgg_world_event_participants set score=v_score,left_at=now(),metadata=metadata||jsonb_build_object('performance_complete',true) where event_id=v_booking.event_id and user_id=v_uid;
  update public.tgg_world_players set xp=xp+v_xp,reputation=reputation+v_rep_gain,audience=audience+v_audience,updated_at=now() where user_id=v_uid;
  update public.tgg_world_contact_relationships set relationship_xp=relationship_xp+20,trust_score=least(100,trust_score+4),successful_contracts=successful_contracts+1,last_interaction_at=now(),updated_at=now() where character_id=v_booking.character_id and contact_key=v_booking.contact_key;
  update private.tgg_world_v12_show_bookings set status='completed',performance_score=v_score,audience_gain=v_audience,reputation_gain=v_rep_gain,xp_gain=v_xp,completed_at=now(),updated_at=now(),metadata=metadata||jsonb_build_object('completion_key',p_idempotency_key,'crowd_energy',v_energy) where id=v_booking.id;

  return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','booking_id',v_booking.id,'event_id',v_booking.event_id,'status','completed','performance_score',v_score,'crowd_energy',v_energy,'audience_gain',v_audience,'reputation_gain',v_rep_gain,'xp_gain',v_xp,'idempotent',false);
end $$;

create or replace function public.tgg_world_v12_start_rap_battle(
  p_opponent_user_id uuid,p_opponent_contact_key text,p_title text,p_idempotency_key text
) returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_uid uuid:=auth.uid();
  v_character_id uuid;
  v_player_rep bigint:=0;
  v_opponent_character_id uuid;
  v_opponent_label text;
  v_opponent_rep bigint:=0;
  v_required integer:=0;
  v_event_id uuid;
  v_battle_id uuid;
  v_existing private.tgg_world_v12_rap_battles%rowtype;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(p_idempotency_key)>160 then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  if (p_opponent_user_id is null and nullif(btrim(coalesce(p_opponent_contact_key,'')),'') is null) or (p_opponent_user_id is not null and nullif(btrim(coalesce(p_opponent_contact_key,'')),'') is not null) then raise exception 'ONE_OPPONENT_REQUIRED' using errcode='22023'; end if;
  if p_opponent_user_id=v_uid then raise exception 'SELF_BATTLE_NOT_ALLOWED' using errcode='22023'; end if;

  select * into v_existing from private.tgg_world_v12_rap_battles where user_id=v_uid and idempotency_key=p_idempotency_key limit 1;
  if found then return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','battle_id',v_existing.id,'event_id',v_existing.event_id,'status',v_existing.status,'opponent',v_existing.opponent_label,'idempotent',true); end if;

  select id into v_character_id from public.world_characters where user_id=v_uid and character_status='active' order by updated_at desc limit 1;
  if v_character_id is null then raise exception 'WORLD_CHARACTER_REQUIRED' using errcode='22023'; end if;
  select coalesce(reputation,0) into v_player_rep from public.tgg_world_players where user_id=v_uid limit 1;
  if not found then raise exception 'WORLD_PLAYER_REQUIRED' using errcode='22023'; end if;

  if p_opponent_user_id is not null then
    select id,stage_name into v_opponent_character_id,v_opponent_label from public.world_characters where user_id=p_opponent_user_id and character_status='active' order by updated_at desc limit 1;
    if v_opponent_character_id is null then raise exception 'OPPONENT_WORLD_CHARACTER_REQUIRED' using errcode='22023'; end if;
    select coalesce(reputation,0) into v_opponent_rep from public.tgg_world_players where user_id=p_opponent_user_id limit 1;
  else
    select display_name,reputation_required into v_opponent_label,v_required from public.tgg_world_industry_contacts where contact_key=p_opponent_contact_key and enabled=true and (lower(role_title) like '%battle%' or lower(role_title) like '%rapper%' or lower(role_title) like '%mc%');
    if v_opponent_label is null then raise exception 'BATTLE_OPPONENT_NOT_FOUND' using errcode='22023'; end if;
    if v_player_rep<v_required then raise exception 'REPUTATION_REQUIRED:%',v_required using errcode='22023'; end if;
    v_opponent_rep:=greatest(20,v_required*3);
  end if;

  insert into public.tgg_world_events(host_user_id,event_type,title,status,starts_at,visibility,metadata)
  values(v_uid,'rap_battle',coalesce(nullif(btrim(coalesce(p_title,'')),''),'TGG Rap Battle'),'live',now(),'public',jsonb_build_object('world_layer','v12','opponent_user_id',p_opponent_user_id,'opponent_contact_key',p_opponent_contact_key)) returning id into v_event_id;
  insert into public.tgg_world_event_participants(event_id,user_id,role,joined_at,metadata) values(v_event_id,v_uid,'performer',now(),jsonb_build_object('side','player')) on conflict do nothing;
  if p_opponent_user_id is not null then insert into public.tgg_world_event_participants(event_id,user_id,role,joined_at,metadata) values(v_event_id,p_opponent_user_id,'challenger',now(),jsonb_build_object('side','opponent')) on conflict do nothing; end if;

  insert into private.tgg_world_v12_rap_battles(user_id,character_id,event_id,opponent_user_id,opponent_character_id,opponent_contact_key,opponent_label,idempotency_key,metadata)
  values(v_uid,v_character_id,v_event_id,p_opponent_user_id,v_opponent_character_id,nullif(btrim(coalesce(p_opponent_contact_key,'')),''),v_opponent_label,p_idempotency_key,
    jsonb_build_object('player_reputation_at_start',v_player_rep,'opponent_reputation_basis',v_opponent_rep)) returning id into v_battle_id;

  return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','battle_id',v_battle_id,'event_id',v_event_id,'status','live','opponent',v_opponent_label,'rounds_total',3,'idempotent',false);
end $$;

create or replace function public.tgg_world_v12_play_rap_battle_round(p_battle_id uuid,p_idempotency_key text)
returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_uid uuid:=auth.uid();
  v_battle private.tgg_world_v12_rap_battles%rowtype;
  v_player_rep bigint:=0;
  v_opp_rep bigint:=0;
  v_round integer;
  v_player_jitter integer;
  v_opp_jitter integer;
  v_player numeric;
  v_opp numeric;
  v_energy numeric;
  v_total_player numeric;
  v_total_opp numeric;
  v_winner text;
  v_rep_gain bigint:=0;
  v_xp_gain bigint:=0;
  v_audience_gain bigint:=0;
  v_existing record;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(p_idempotency_key)>160 then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;

  select * into v_existing from private.tgg_world_v12_rap_battle_rounds where battle_id=p_battle_id and user_id=v_uid and idempotency_key=p_idempotency_key limit 1;
  if found then return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','battle_id',p_battle_id,'round_number',v_existing.round_number,'player_score',v_existing.player_score,'opponent_score',v_existing.opponent_score,'crowd_energy',v_existing.crowd_energy,'idempotent',true); end if;

  select * into v_battle from private.tgg_world_v12_rap_battles where id=p_battle_id and user_id=v_uid for update;
  if not found then raise exception 'BATTLE_NOT_FOUND' using errcode='22023'; end if;
  if v_battle.status='completed' then return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','battle_id',v_battle.id,'status','completed','player_score',v_battle.player_score,'opponent_score',v_battle.opponent_score,'winner_side',v_battle.winner_side,'idempotent',true); end if;
  if v_battle.status<>'live' then raise exception 'BATTLE_NOT_ACTIVE' using errcode='22023'; end if;

  v_round:=v_battle.rounds_completed+1;
  if v_round>v_battle.rounds_total then raise exception 'BATTLE_ROUNDS_COMPLETE' using errcode='22023'; end if;
  select coalesce(reputation,0) into v_player_rep from public.tgg_world_players where user_id=v_uid limit 1;
  if v_battle.opponent_user_id is not null then select coalesce(reputation,0) into v_opp_rep from public.tgg_world_players where user_id=v_battle.opponent_user_id limit 1; else v_opp_rep:=coalesce((v_battle.metadata->>'opponent_reputation_basis')::bigint,30); end if;

  v_player_jitter:=(((hashtextextended(v_battle.id::text||':p:'||v_round::text,0)%21)+21)%21)::integer-10;
  v_opp_jitter:=(((hashtextextended(v_battle.id::text||':o:'||v_round::text,0)%21)+21)%21)::integer-10;
  v_player:=greatest(10,least(100,55+least(25,(v_player_rep/20)::integer)+v_player_jitter));
  v_opp:=greatest(10,least(100,52+least(25,(v_opp_rep/20)::integer)+v_opp_jitter));
  v_energy:=greatest(25,least(100,round((v_player+v_opp)/2+8)));

  insert into private.tgg_world_v12_rap_battle_rounds(battle_id,user_id,round_number,player_score,opponent_score,crowd_energy,idempotency_key)
  values(v_battle.id,v_uid,v_round,v_player,v_opp,v_energy,p_idempotency_key);

  v_total_player:=v_battle.player_score+v_player;
  v_total_opp:=v_battle.opponent_score+v_opp;

  if v_round=v_battle.rounds_total then
    v_winner:=case when v_total_player>v_total_opp then 'player' when v_total_player<v_total_opp then 'opponent' else 'draw' end;
    v_rep_gain:=case when v_winner='player' then 12 when v_winner='draw' then 7 else 4 end;
    v_xp_gain:=case when v_winner='player' then 140 when v_winner='draw' then 95 else 65 end;
    v_audience_gain:=case when v_winner='player' then 90 when v_winner='draw' then 55 else 30 end;

    update private.tgg_world_v12_rap_battles set rounds_completed=v_round,player_score=v_total_player,opponent_score=v_total_opp,crowd_energy=(crowd_energy+v_energy)/case when rounds_completed=0 then 1 else 2 end,status='completed',winner_side=v_winner,completed_at=now(),updated_at=now() where id=v_battle.id;
    update public.tgg_world_events set status='completed',ends_at=now(),updated_at=now(),metadata=metadata||jsonb_build_object('winner_side',v_winner,'player_score',v_total_player,'opponent_score',v_total_opp) where id=v_battle.event_id and host_user_id=v_uid;
    insert into public.tgg_world_event_results(event_id,peak_audience,total_reactions,total_votes,crowd_energy,winner_user_id,result_payload,finalized_at)
    values(v_battle.event_id,v_audience_gain::integer,0,0,v_energy,case when v_winner='player' then v_uid when v_winner='opponent' then v_battle.opponent_user_id else null end,
      jsonb_build_object('world_layer','v12','kind','rap_battle','winner_side',v_winner,'player_score',v_total_player,'opponent_score',v_total_opp),now())
    on conflict(event_id) do update set peak_audience=excluded.peak_audience,crowd_energy=excluded.crowd_energy,winner_user_id=excluded.winner_user_id,result_payload=excluded.result_payload,finalized_at=excluded.finalized_at;
    update public.tgg_world_event_participants set score=case when user_id=v_uid then v_total_player else v_total_opp end,left_at=now() where event_id=v_battle.event_id;
    update public.tgg_world_players set xp=xp+v_xp_gain,reputation=reputation+v_rep_gain,audience=audience+v_audience_gain,updated_at=now() where user_id=v_uid;
  else
    update private.tgg_world_v12_rap_battles set rounds_completed=v_round,player_score=v_total_player,opponent_score=v_total_opp,crowd_energy=case when rounds_completed=0 then v_energy else (crowd_energy*rounds_completed+v_energy)/(rounds_completed+1) end,updated_at=now() where id=v_battle.id;
  end if;

  return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','battle_id',v_battle.id,'round_number',v_round,'rounds_total',v_battle.rounds_total,'player_score',v_player,'opponent_score',v_opp,'crowd_energy',v_energy,'battle_player_total',v_total_player,'battle_opponent_total',v_total_opp,'status',case when v_round=v_battle.rounds_total then 'completed' else 'live' end,'winner_side',case when v_round=v_battle.rounds_total then v_winner else null end,'reputation_gain',v_rep_gain,'xp_gain',v_xp_gain,'audience_gain',v_audience_gain,'idempotent',false);
end $$;

