  v_audience bigint;
  v_rep_gain bigint;
  v_xp bigint;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(p_idempotency_key)>160 then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  select * into v_booking from private.tgg_world_v12_show_bookings where id=p_booking_id and user_id=v_uid for update;
  if not found then raise exception 'SHOW_BOOKING_NOT_FOUND' using errcode='22023'; end if;
  if v_booking.status='completed' then return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','booking_id',v_booking.id,'event_id',v_booking.event_id,'status','completed','performance_score',v_booking.performance_score,'audience_gain',v_booking.audience_gain,'reputation_gain',v_booking.reputation_gain,'xp_gain',v_booking.xp_gain,'idempotent',true); end if;
  if v_booking.status<>'booked' then raise exception 'SHOW_NOT_ACTIVE' using errcode='22023'; end if;
  if v_booking.starts_at>now()+interval '30 minutes' then raise exception 'SHOW_NOT_STARTED_YET' using errcode='22023'; end if;
  v_rep:=coalesce((select reputation from public.tgg_world_players where user_id=v_uid limit 1),0);
  v_trust:=coalesce((select trust_score from public.tgg_world_contact_relationships where character_id=v_booking.character_id and contact_key=v_booking.contact_key),0);
  v_jitter:=(((hashtextextended(v_booking.id::text||':show',0)%21)+21)%21)::integer-10;
  v_score:=greatest(20,least(100,55+least(20,(v_rep/25)::integer)+least(12,(v_trust/8)::integer)+v_jitter));
  v_energy:=greatest(20,least(100,round((v_score+60+v_trust/2.0)/2)));
  v_audience:=greatest(20,round(v_energy*2+least(200,v_rep/5.0))::bigint);
  v_rep_gain:=greatest(3,round(v_score/12)::bigint);
  v_xp:=greatest(50,round(v_score*1.5)::bigint);
  update public.tgg_world_events set status='completed',ends_at=now(),updated_at=now(),metadata=metadata||jsonb_build_object('performance_score',v_score,'crowd_energy',v_energy) where id=v_booking.event_id and host_user_id=v_uid;
  insert into public.tgg_world_event_results(event_id,peak_audience,total_reactions,total_votes,crowd_energy,winner_user_id,result_payload,finalized_at)
  values(v_booking.event_id,v_audience::integer,0,0,v_energy,v_uid,jsonb_build_object('world_layer','v12','kind','concert','performance_score',v_score),now())
  on conflict(event_id) do update set peak_audience=excluded.peak_audience,crowd_energy=excluded.crowd_energy,winner_user_id=excluded.winner_user_id,result_payload=excluded.result_payload,finalized_at=excluded.finalized_at;
  update public.tgg_world_event_participants set score=v_score,left_at=now(),metadata=metadata||jsonb_build_object('performance_complete',true) where event_id=v_booking.event_id and user_id=v_uid;
  update public.tgg_world_players set xp=xp+v_xp,reputation=reputation+v_rep_gain,audience=audience+v_audience,updated_at=now() where user_id=v_uid;
  update public.tgg_world_contact_relationships set relationship_xp=relationship_xp+20,trust_score=least(100,trust_score+4),successful_contracts=successful_contracts+1,last_interaction_at=now(),updated_at=now() where character_id=v_booking.character_id and contact_key=v_booking.contact_key;
  update private.tgg_world_v12_show_bookings set status='completed',performance_score=v_score,audience_gain=v_audience,reputation_gain=v_rep_gain,xp_gain=v_xp,completed_at=now(),updated_at=now(),metadata=metadata||jsonb_build_object('completion_key',p_idempotency_key,'crowd_energy',v_energy) where id=v_booking.id;
  return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','booking_id',v_booking.id,'event_id',v_booking.event_id,'status','completed','performance_score',v_score,'crowd_energy',v_energy,'audience_gain',v_audience,'reputation_gain',v_rep_gain,'xp_gain',v_xp,'idempotent',false);
end $$;

