  v_player_rep:=coalesce((select reputation from public.tgg_world_players where user_id=v_uid limit 1),0);
  if v_battle.opponent_user_id is not null then v_opp_rep:=coalesce((select reputation from public.tgg_world_players where user_id=v_battle.opponent_user_id limit 1),0); else v_opp_rep:=coalesce((v_battle.metadata->>'opponent_reputation_basis')::bigint,30); end if;
  v_player_jitter:=(((hashtextextended(v_battle.id::text||':p:'||v_round::text,0)%21)+21)%21)::integer-10;
  v_opp_jitter:=(((hashtextextended(v_battle.id::text||':o:'||v_round::text,0)%21)+21)%21)::integer-10;
  v_player:=greatest(10,least(100,55+least(25,(v_player_rep/20)::integer)+v_player_jitter));
  v_opp:=greatest(10,least(100,52+least(25,(v_opp_rep/20)::integer)+v_opp_jitter));
  v_energy:=greatest(25,least(100,round((v_player+v_opp)/2+8)));
  insert into private.tgg_world_v12_rap_battle_rounds(battle_id,user_id,round_number,player_score,opponent_score,crowd_energy,idempotency_key)
  values(v_battle.id,v_uid,v_round,v_player,v_opp,v_energy,p_idempotency_key);
  v_total_player:=v_battle.player_score+v_player;
  v_total_opp:=v_battle.opponent_score+v_opp;
  if v_round=v_battle.rounds_total then
    v_winner:=case when v_total_player>v_total_opp then 'player' when v_total_player<v_total_opp then 'opponent' else 'draw' end;
    v_rep_gain:=case when v_winner='player' then 12 when v_winner='draw' then 7 else 4 end;
    v_xp_gain:=case when v_winner='player' then 140 when v_winner='draw' then 95 else 65 end;
    v_audience_gain:=case when v_winner='player' then 90 when v_winner='draw' then 55 else 30 end;
    update private.tgg_world_v12_rap_battles set rounds_completed=v_round,player_score=v_total_player,opponent_score=v_total_opp,crowd_energy=case when rounds_completed=0 then v_energy else (crowd_energy*rounds_completed+v_energy)/(rounds_completed+1) end,status='completed',winner_side=v_winner,completed_at=now(),updated_at=now() where id=v_battle.id;
    update public.tgg_world_events set status='completed',ends_at=now(),updated_at=now(),metadata=metadata||jsonb_build_object('winner_side',v_winner,'player_score',v_total_player,'opponent_score',v_total_opp) where id=v_battle.event_id and host_user_id=v_uid;
    insert into public.tgg_world_event_results(event_id,peak_audience,total_reactions,total_votes,crowd_energy,winner_user_id,result_payload,finalized_at)
    values(v_battle.event_id,v_audience_gain::integer,0,0,v_energy,case when v_winner='player' then v_uid when v_winner='opponent' then v_battle.opponent_user_id else null end,jsonb_build_object('world_layer','v12','kind','rap_battle','winner_side',v_winner,'player_score',v_total_player,'opponent_score',v_total_opp),now())
    on conflict(event_id) do update set peak_audience=excluded.peak_audience,crowd_energy=excluded.crowd_energy,winner_user_id=excluded.winner_user_id,result_payload=excluded.result_payload,finalized_at=excluded.finalized_at;
    update public.tgg_world_event_participants set score=case when user_id=v_uid then v_total_player else v_total_opp end,left_at=now() where event_id=v_battle.event_id;
    update public.tgg_world_players set xp=xp+v_xp_gain,reputation=reputation+v_rep_gain,audience=audience+v_audience_gain,updated_at=now() where user_id=v_uid;
  else
    update private.tgg_world_v12_rap_battles set rounds_completed=v_round,player_score=v_total_player,opponent_score=v_total_opp,crowd_energy=case when rounds_completed=0 then v_energy else (crowd_energy*rounds_completed+v_energy)/(rounds_completed+1) end,updated_at=now() where id=v_battle.id;
  end if;
  return jsonb_build_object('ok',true,'version','WORLD-V12-PERFORMANCE-INDUSTRY','battle_id',v_battle.id,'round_number',v_round,'rounds_total',v_battle.rounds_total,'player_score',v_player,'opponent_score',v_opp,'crowd_energy',v_energy,'battle_player_total',v_total_player,'battle_opponent_total',v_total_opp,'status',case when v_round=v_battle.rounds_total then 'completed' else 'live' end,'winner_side',case when v_round=v_battle.rounds_total then v_winner else null end,'reputation_gain',v_rep_gain,'xp_gain',v_xp_gain,'audience_gain',v_audience_gain,'idempotent',false);
end $$;

