create or replace function private.tgg_world_v12_guard_contact_meeting()
returns trigger
language plpgsql
security definer
set search_path=''
as $$
begin
  if exists (
    select 1 from private.tgg_world_v12_contact_meetings m
    where m.user_id=new.user_id
      and m.contact_key=new.contact_key
      and m.created_at>now()-interval '30 minutes'
  ) then
    raise exception 'CONTACT_MEETING_COOLDOWN' using errcode='P0001';
  end if;
  return new;
end $$;

create or replace function private.tgg_world_v12_guard_show_booking()
returns trigger
language plpgsql
security definer
set search_path=''
as $$
begin
  if (select count(*) from private.tgg_world_v12_show_bookings b where b.user_id=new.user_id and b.created_at>now()-interval '24 hours')>=10 then
    raise exception 'SHOW_BOOKING_DAILY_LIMIT' using errcode='P0001';
  end if;
  if exists (
    select 1 from private.tgg_world_v12_show_bookings b
    where b.user_id=new.user_id
      and b.status='booked'
      and abs(extract(epoch from (b.starts_at-new.starts_at)))<5400
  ) then
    raise exception 'SHOW_BOOKING_TIME_CONFLICT' using errcode='P0001';
  end if;
  return new;
end $$;

create or replace function private.tgg_world_v12_guard_rap_battle()
returns trigger
language plpgsql
security definer
set search_path=''
as $$
begin
  if exists (
    select 1 from private.tgg_world_v12_rap_battles b
    where b.user_id=new.user_id and b.status='live'
  ) then
    raise exception 'ACTIVE_BATTLE_EXISTS' using errcode='P0001';
  end if;
  if (select count(*) from private.tgg_world_v12_rap_battles b where b.user_id=new.user_id and b.created_at>now()-interval '1 hour')>=6 then
    raise exception 'BATTLE_HOURLY_LIMIT' using errcode='P0001';
  end if;
  return new;
end $$;

drop trigger if exists tgg_world_v12_guard_contact_meeting on private.tgg_world_v12_contact_meetings;
create trigger tgg_world_v12_guard_contact_meeting before insert on private.tgg_world_v12_contact_meetings for each row execute function private.tgg_world_v12_guard_contact_meeting();

drop trigger if exists tgg_world_v12_guard_show_booking on private.tgg_world_v12_show_bookings;
create trigger tgg_world_v12_guard_show_booking before insert on private.tgg_world_v12_show_bookings for each row execute function private.tgg_world_v12_guard_show_booking();

drop trigger if exists tgg_world_v12_guard_rap_battle on private.tgg_world_v12_rap_battles;
create trigger tgg_world_v12_guard_rap_battle before insert on private.tgg_world_v12_rap_battles for each row execute function private.tgg_world_v12_guard_rap_battle();

revoke all on function private.tgg_world_v12_guard_contact_meeting() from public,anon,authenticated;
revoke all on function private.tgg_world_v12_guard_show_booking() from public,anon,authenticated;
revoke all on function private.tgg_world_v12_guard_rap_battle() from public,anon,authenticated;

