create or replace function private.tgg_world_v3_travel_to_impl(p_location_key text)
returns jsonb
language plpgsql
security definer
set search_path to ''
as $$
declare
  v_uid uuid := auth.uid();
  v_location public.tgg_world_locations_v10%rowtype;
  v_player public.tgg_world_players%rowtype;
  v_canonical_key text;
  v_canonical_id uuid;
  v_character_synced boolean := false;
  v_join jsonb := '{}'::jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select * into v_location
  from public.tgg_world_locations_v10
  where location_key=p_location_key and active=true;
  if v_location.id is null then raise exception 'LOCATION_NOT_FOUND'; end if;

  select * into v_player from public.tgg_world_players where user_id=v_uid;
  if v_player.id is null then
    perform public.tgg_world_mvp_v1_bootstrap_player();
    select * into v_player from public.tgg_world_players where user_id=v_uid;
  end if;
  if v_player.reputation < v_location.unlock_reputation then raise exception 'LOCATION_LOCKED'; end if;

  v_canonical_key := case v_location.location_key
    when 'starter_studio' then 'basement-sound'
    when 'creator_shop' then 'style-shop'
    when 'local_venue' then 'corner-stage'
    when 'garage_one' then 'garage'
    when 'industry_row' then 'music-row'
    when 'spawn_district' then 'the-park'
    else v_location.location_key
  end;

  select id into v_canonical_id
  from public.tgg_world_locations
  where location_key=v_canonical_key and enabled=true
  limit 1;

  update public.tgg_world_players
  set current_location=v_location.location_key,last_seen_at=now(),updated_at=now()
  where user_id=v_uid;

  if v_canonical_id is not null and exists(
    select 1 from public.world_characters where user_id=v_uid and character_status='active'
  ) then
    v_join := tgg_private.world_join_location(v_canonical_key);
    v_character_synced := true;
  elsif v_canonical_id is not null then
    update public.world_characters
    set current_location_id=v_canonical_id,updated_at=now()
    where user_id=v_uid and character_status='active';
    v_character_synced := found;
  end if;

  return jsonb_build_object(
    'ok',true,
    'location_id',v_location.id,
    'location_key',v_location.location_key,
    'name',v_location.name,
    'canonical_location_id',v_canonical_id,
    'canonical_location_key',v_canonical_key,
    'character_synced',v_character_synced,
    'instance_id',v_join->>'instance_id',
    'population',v_join->'population',
    'capacity',v_join->'capacity'
  );
end
$$;

create or replace function private.tgg_world_v11_6_presence_bootstrap_impl()
returns jsonb
language plpgsql
security definer
set search_path to ''
as $$
declare
  v_uid uuid := auth.uid();
  v_character public.world_characters%rowtype;
  v_location_key text;
  v_join jsonb;
  v_hb jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_character
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_character.id is null then
    return jsonb_build_object('ok',true,'character_ready',false,'joined',false);
  end if;

  select location_key into v_location_key
  from public.tgg_world_locations
  where id=v_character.current_location_id and enabled=true;
  if v_location_key is null then raise exception 'CURRENT_LOCATION_UNAVAILABLE'; end if;

  v_join := tgg_private.world_join_location(v_location_key);
  v_hb := tgg_private.world_presence_heartbeat(
    jsonb_build_object('x',0,'y',0,'z',0),
    jsonb_build_object('location_key',v_location_key,'source','artist-world-v11.6')
  );

  return jsonb_build_object(
    'ok',true,
    'character_ready',true,
    'joined',true,
    'location_key',v_location_key,
    'instance_id',v_join->>'instance_id',
    'population',v_join->'population',
    'capacity',v_join->'capacity',
    'heartbeat',v_hb
  );
end
$$;
revoke all on function private.tgg_world_v11_6_presence_bootstrap_impl() from public,anon;
grant execute on function private.tgg_world_v11_6_presence_bootstrap_impl() to authenticated;

create or replace function public.tgg_world_v11_6_presence_bootstrap()
returns jsonb
language sql
security invoker
set search_path to ''
as $$ select private.tgg_world_v11_6_presence_bootstrap_impl(); $$;
revoke all on function public.tgg_world_v11_6_presence_bootstrap() from public,anon;
grant execute on function public.tgg_world_v11_6_presence_bootstrap() to authenticated;

create or replace function private.tgg_world_v11_6_presence_bundle_impl()
returns jsonb
language plpgsql
stable
security definer
set search_path to ''
as $$
declare
  v_uid uuid := auth.uid();
  v_presence public.world_presence%rowtype;
  v_instance public.world_instances%rowtype;
  v_location_key text;
  v_players jsonb := '[]'::jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select * into v_presence
  from public.world_presence
  where user_id=v_uid and left_at is null and heartbeat_at > now()-interval '2 minutes'
  order by heartbeat_at desc
  limit 1;

  if v_presence.id is null then
    return jsonb_build_object('ok',true,'present',false,'players','[]'::jsonb,'population',0);
  end if;

  select * into v_instance from public.world_instances where id=v_presence.instance_id;
  select l.location_key into v_location_key from public.tgg_world_locations l where l.id=v_instance.location_id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'stage_name',c.stage_name,
    'active_career',c.active_career,
    'avatar',jsonb_build_object(
      'accent',coalesce(ap.profile->>'accent',c.avatar_config->>'accent','#e50914'),
      'build',coalesce(ap.profile->>'build',c.avatar_config->>'build','balanced'),
      'vibe',coalesce(ap.profile->>'vibe',c.avatar_config->>'vibe','street')
    ),
    'position',coalesce(p.position,'{}'::jsonb),
    'activity',coalesce(p.activity,'{}'::jsonb),
    'presence_state',p.presence_state,
    'is_me',p.user_id=v_uid,
    'heartbeat_at',p.heartbeat_at
  ) order by p.joined_at),'[]'::jsonb)
  into v_players
  from public.world_presence p
  join public.world_characters c on c.id=p.character_id
  left join public.tgg_world_avatar_profiles ap on ap.user_id=p.user_id
  where p.instance_id=v_presence.instance_id
    and p.left_at is null
    and p.heartbeat_at > now()-interval '2 minutes';

  return jsonb_build_object(
    'ok',true,
    'version','WORLD-V11.6-PRESENCE',
    'present',true,
    'instance',jsonb_build_object(
      'key',v_instance.instance_key,
      'status',v_instance.status,
      'capacity',v_instance.capacity,
      'location_key',v_location_key
    ),
    'population',jsonb_array_length(v_players),
    'players',v_players,
    'privacy',jsonb_build_object('user_ids_exposed',false,'character_ids_exposed',false)
  );
end
$$;
revoke all on function private.tgg_world_v11_6_presence_bundle_impl() from public,anon;
grant execute on function private.tgg_world_v11_6_presence_bundle_impl() to authenticated;

