create or replace function public.tgg_studio_control_acquire(p_project_id uuid,p_client_id text,p_mode text default 'transport')
returns jsonb language plpgsql security definer set search_path to 'public','pg_catalog' as $$
declare
  v_uid uuid:=auth.uid(); v_client text:=left(btrim(coalesce(p_client_id,'')),120); v_mode text:=lower(btrim(coalesce(p_mode,'transport')));
  v_owner boolean:=false; v_can_edit boolean:=false; v_can_record boolean:=false; v_rows integer; v_lease public.tgg_studio_control_leases;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if v_client='' then raise exception 'CLIENT_ID_REQUIRED' using errcode='22023'; end if;
  if v_mode not in ('transport','edit','record') then raise exception 'CONTROL_MODE_INVALID' using errcode='22023'; end if;
  select exists(select 1 from public.tgg_studio_projects p where p.id=p_project_id and p.user_id=v_uid) into v_owner;
  select v_owner or exists(select 1 from public.tgg_studio_project_members m where m.project_id=p_project_id and m.user_id=v_uid and m.left_at is null and m.can_edit),
         v_owner or exists(select 1 from public.tgg_studio_project_members m where m.project_id=p_project_id and m.user_id=v_uid and m.left_at is null and m.can_record)
  into v_can_edit,v_can_record;
  if not v_owner and not exists(select 1 from public.tgg_studio_project_members m where m.project_id=p_project_id and m.user_id=v_uid and m.left_at is null) then raise exception 'PROJECT_ACCESS_DENIED' using errcode='42501'; end if;
  if v_mode in ('transport','edit') and not v_can_edit then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  if v_mode='record' and not v_can_record then raise exception 'RECORD_PERMISSION_REQUIRED' using errcode='42501'; end if;

  insert into public.tgg_studio_control_leases(project_id,user_id,client_id,control_mode,expires_at,updated_at)
  values(p_project_id,v_uid,v_client,v_mode,now()+interval '20 seconds',now())
  on conflict(project_id) do update set user_id=excluded.user_id,client_id=excluded.client_id,control_mode=excluded.control_mode,expires_at=excluded.expires_at,updated_at=now()
  where public.tgg_studio_control_leases.expires_at<=now()
     or (public.tgg_studio_control_leases.user_id=v_uid and public.tgg_studio_control_leases.client_id=v_client);
  get diagnostics v_rows=row_count;
  select * into v_lease from public.tgg_studio_control_leases where project_id=p_project_id;
  if v_rows=0 then
    return jsonb_build_object('ok',false,'code','CONTROL_HELD','project_id',p_project_id,'holder_user_id',v_lease.user_id,'holder_client_id',v_lease.client_id,'control_mode',v_lease.control_mode,'expires_at',v_lease.expires_at);
  end if;
  return jsonb_build_object('ok',true,'project_id',p_project_id,'user_id',v_uid,'client_id',v_client,'control_mode',v_mode,'expires_at',v_lease.expires_at);
end$$;

create or replace function public.tgg_studio_control_release(p_project_id uuid,p_client_id text)
returns jsonb language plpgsql security definer set search_path to 'public','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_count integer;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 delete from public.tgg_studio_control_leases where project_id=p_project_id and user_id=v_uid and client_id=left(btrim(coalesce(p_client_id,'')),120);
 get diagnostics v_count=row_count;
 return jsonb_build_object('ok',true,'released',v_count>0,'project_id',p_project_id);
end$$;

create or replace function public.tgg_studio_transport_set(p_project_id uuid,p_client_id text,p_state jsonb)
returns jsonb language plpgsql security definer set search_path to 'public','pg_catalog' as $$
declare
 v_uid uuid:=auth.uid(); v_client text:=left(btrim(coalesce(p_client_id,'')),120); v_lease public.tgg_studio_control_leases;
 v_play boolean:=coalesce((p_state->>'is_playing')::boolean,false); v_record boolean:=coalesce((p_state->>'is_recording')::boolean,false);
 v_head numeric:=greatest(0,least(86400,coalesce((p_state->>'playhead_seconds')::numeric,0))); v_loop boolean:=coalesce((p_state->>'loop_enabled')::boolean,false); v_met boolean:=coalesce((p_state->>'metronome_enabled')::boolean,false);
 v_can_record boolean:=false;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into v_lease from public.tgg_studio_control_leases where project_id=p_project_id and expires_at>now();
 if v_lease.project_id is null or v_lease.user_id<>v_uid or v_lease.client_id<>v_client then raise exception 'CONTROL_LEASE_REQUIRED' using errcode='42501'; end if;
 select exists(select 1 from public.tgg_studio_projects p where p.id=p_project_id and p.user_id=v_uid)
     or exists(select 1 from public.tgg_studio_project_members m where m.project_id=p_project_id and m.user_id=v_uid and m.left_at is null and m.can_record) into v_can_record;
 if v_record and not v_can_record then raise exception 'RECORD_PERMISSION_REQUIRED' using errcode='42501'; end if;
 insert into public.tgg_studio_transport_state(project_id,controller_user_id,controller_client_id,is_playing,is_recording,playhead_seconds,loop_enabled,metronome_enabled,updated_at)
 values(p_project_id,v_uid,v_client,v_play,v_record,v_head,v_loop,v_met,now())
 on conflict(project_id) do update set controller_user_id=excluded.controller_user_id,controller_client_id=excluded.controller_client_id,is_playing=excluded.is_playing,is_recording=excluded.is_recording,playhead_seconds=excluded.playhead_seconds,loop_enabled=excluded.loop_enabled,metronome_enabled=excluded.metronome_enabled,updated_at=now();
 update public.tgg_studio_control_leases set expires_at=now()+interval '20 seconds',updated_at=now() where project_id=p_project_id and user_id=v_uid and client_id=v_client;
 return jsonb_build_object('ok',true,'project_id',p_project_id,'state',jsonb_build_object('is_playing',v_play,'is_recording',v_record,'playhead_seconds',v_head,'loop_enabled',v_loop,'metronome_enabled',v_met,'controller_user_id',v_uid,'controller_client_id',v_client,'updated_at',now()));
end$$;

create or replace function public.tgg_studio_session_message_send(p_project_id uuid,p_body text,p_display_name text default null)
returns jsonb language plpgsql security definer set search_path to 'public','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_body text:=left(btrim(coalesce(p_body,'')),2000); v_id bigint;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if v_body='' then raise exception 'MESSAGE_REQUIRED' using errcode='22023'; end if;
 if not (exists(select 1 from public.tgg_studio_projects p where p.id=p_project_id and p.user_id=v_uid) or exists(select 1 from public.tgg_studio_project_members m where m.project_id=p_project_id and m.user_id=v_uid and m.left_at is null)) then raise exception 'PROJECT_ACCESS_DENIED' using errcode='42501'; end if;
 insert into public.tgg_studio_session_messages(project_id,user_id,display_name,body) values(p_project_id,v_uid,left(nullif(btrim(coalesce(p_display_name,'')),''),80),v_body) returning id into v_id;
 return jsonb_build_object('ok',true,'id',v_id,'project_id',p_project_id);
end$$;

create or replace function public.tgg_studio_take_request_create(p_project_id uuid,p_note text default null,p_display_name text default null)
returns jsonb language plpgsql security definer set search_path to 'public','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_can_record boolean:=false; v_id uuid;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select exists(select 1 from public.tgg_studio_projects p where p.id=p_project_id and p.user_id=v_uid) or exists(select 1 from public.tgg_studio_project_members m where m.project_id=p_project_id and m.user_id=v_uid and m.left_at is null and m.can_record) into v_can_record;
 if not v_can_record then raise exception 'RECORD_PERMISSION_REQUIRED' using errcode='42501'; end if;
 insert into public.tgg_studio_take_requests(project_id,requester_id,display_name,note) values(p_project_id,v_uid,left(nullif(btrim(coalesce(p_display_name,'')),''),80),left(nullif(btrim(coalesce(p_note,'')),''),500)) returning id into v_id;
 return jsonb_build_object('ok',true,'request_id',v_id,'project_id',p_project_id,'status','pending');
end$$;

create or replace function public.tgg_studio_take_request_respond(p_request_id uuid,p_accept boolean)
returns jsonb language plpgsql security definer set search_path to 'public','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_req public.tgg_studio_take_requests; v_can_edit boolean:=false; v_status text;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into v_req from public.tgg_studio_take_requests where id=p_request_id and status='pending' for update;
 if v_req.id is null then raise exception 'REQUEST_UNAVAILABLE'; end if;
 select exists(select 1 from public.tgg_studio_projects p where p.id=v_req.project_id and p.user_id=v_uid) or exists(select 1 from public.tgg_studio_project_members m where m.project_id=v_req.project_id and m.user_id=v_uid and m.left_at is null and m.can_edit) into v_can_edit;
 if not v_can_edit then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
 v_status:=case when coalesce(p_accept,false) then 'accepted' else 'declined' end;
 update public.tgg_studio_take_requests set status=v_status,responded_at=now(),responded_by=v_uid where id=v_req.id;
 return jsonb_build_object('ok',true,'request_id',v_req.id,'project_id',v_req.project_id,'status',v_status);
end$$;

create or replace function tgg_private.collab_project_runtime(p_project_id uuid)
returns jsonb language plpgsql stable security definer set search_path to '' as $$
declare v_uid uuid:=auth.uid();v_owner boolean;v_member public.tgg_studio_project_members;v_project public.tgg_studio_projects;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 select * into v_project from public.tgg_studio_projects where id=p_project_id;
 if v_project.id is null then raise exception 'PROJECT_NOT_FOUND'; end if;
 v_owner:=v_project.user_id=v_uid;
 select * into v_member from public.tgg_studio_project_members where project_id=p_project_id and user_id=v_uid and left_at is null;
 if not v_owner and v_member.user_id is null then raise exception 'PROJECT_ACCESS_DENIED'; end if;
 return jsonb_build_object(
  'ok',true,'version','COLLAB-RUNTIME-1.1',
  'project',jsonb_build_object('id',v_project.id,'title',v_project.title,'project_type',v_project.project_type,'revision',v_project.revision,'project_data',v_project.project_data,'owner_user_id',v_project.user_id),
  'permission',jsonb_build_object('role',case when v_owner then 'owner' else v_member.role end,'can_edit',case when v_owner then true else coalesce(v_member.can_edit,false) end,'can_record',case when v_owner then true else coalesce(v_member.can_record,false) end,'can_publish',case when v_owner then true else coalesce(v_member.can_publish,false) end),
  'members',coalesce((select jsonb_agg(jsonb_build_object('user_id',m.user_id,'role',m.role,'can_edit',m.can_edit,'can_record',m.can_record,'can_publish',m.can_publish) order by m.joined_at) from public.tgg_studio_project_members m where m.project_id=p_project_id and m.left_at is null),'[]'::jsonb),
  'presence',coalesce((select jsonb_agg(jsonb_build_object('user_id',p.user_id,'client_id',p.client_id,'display_name',p.display_name,'active_surface',p.active_surface,'cursor_state',p.cursor_state,'control_state',p.control_state,'last_seen_at',p.last_seen_at) order by p.last_seen_at desc) from public.tgg_studio_project_presence p where p.project_id=p_project_id and p.last_seen_at>now()-interval '2 minutes'),'[]'::jsonb),
  'active_control',(select jsonb_build_object('user_id',l.user_id,'client_id',l.client_id,'control_mode',l.control_mode,'expires_at',l.expires_at,'updated_at',l.updated_at) from public.tgg_studio_control_leases l where l.project_id=p_project_id and l.expires_at>now()),
  'transport',(select jsonb_build_object('controller_user_id',t.controller_user_id,'controller_client_id',t.controller_client_id,'is_playing',t.is_playing,'is_recording',t.is_recording,'playhead_seconds',t.playhead_seconds,'loop_enabled',t.loop_enabled,'metronome_enabled',t.metronome_enabled,'updated_at',t.updated_at) from public.tgg_studio_transport_state t where t.project_id=p_project_id),
  'session_messages',coalesce((select jsonb_agg(x.obj order by x.id) from (select m.id,jsonb_build_object('id',m.id,'user_id',m.user_id,'display_name',m.display_name,'body',m.body,'created_at',m.created_at) obj from public.tgg_studio_session_messages m where m.project_id=p_project_id order by m.id desc limit 50) x),'[]'::jsonb),
  'take_requests',coalesce((select jsonb_agg(x.obj order by x.requested_at desc) from (select r.requested_at,jsonb_build_object('id',r.id,'requester_id',r.requester_id,'display_name',r.display_name,'note',r.note,'status',r.status,'requested_at',r.requested_at,'responded_at',r.responded_at,'responded_by',r.responded_by) obj from public.tgg_studio_take_requests r where r.project_id=p_project_id order by r.requested_at desc limit 20) x),'[]'::jsonb),
  'events',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'user_id',e.user_id,'event_type',e.event_type,'entity_type',e.entity_type,'entity_id',e.entity_id,'patch',e.patch,'base_revision',e.base_revision,'revision',e.revision,'created_at',e.created_at) order by e.id) from (select * from public.tgg_studio_project_events where project_id=p_project_id order by id desc limit 40) e),'[]'::jsonb),
  'generated_at',now()
 );
end$$;

do $$ begin
 if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='tgg_studio_control_leases') then alter publication supabase_realtime add table public.tgg_studio_control_leases; end if;
 if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='tgg_studio_transport_state') then alter publication supabase_realtime add table public.tgg_studio_transport_state; end if;
 if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='tgg_studio_session_messages') then alter publication supabase_realtime add table public.tgg_studio_session_messages; end if;
 if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='tgg_studio_take_requests') then alter publication supabase_realtime add table public.tgg_studio_take_requests; end if;
end $$;

