create or replace function public.tgg_studio_call_room_ensure(p_project_id uuid,p_room_type text default 'video')
returns jsonb language plpgsql security definer set search_path to 'public','pg_catalog' as $$
declare
 v_uid uuid:=auth.uid(); v_type text:=lower(btrim(coalesce(p_room_type,'video'))); v_room uuid; v_created boolean:=false; v_title text; v_count integer;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if v_type not in ('video','audio') then raise exception 'ROOM_TYPE_INVALID' using errcode='22023'; end if;
 if not (exists(select 1 from public.tgg_studio_projects p where p.id=p_project_id and p.user_id=v_uid) or exists(select 1 from public.tgg_studio_project_members m where m.project_id=p_project_id and m.user_id=v_uid and m.left_at is null)) then raise exception 'PROJECT_ACCESS_DENIED' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_project_id::text,0));
 select r.id into v_room from public.tgg_call_rooms r where r.studio_project_id=p_project_id and r.status='active' order by r.created_at desc limit 1;
 if v_room is null then
   select coalesce(p.title,'Studio Session') into v_title from public.tgg_studio_projects p where p.id=p_project_id;
   insert into public.tgg_call_rooms(created_by,title,room_type,status,is_group,studio_project_id) values(v_uid,left(v_title||' · Studio Call',160),v_type,'active',true,p_project_id) returning id into v_room;
   v_created:=true;
   insert into public.tgg_call_participants(room_id,user_id,mic_enabled,camera_enabled,left_at)
   select v_room,x.user_id,true,(v_type='video'),null
   from (
     select p.user_id from public.tgg_studio_projects p where p.id=p_project_id
     union
     select m.user_id from public.tgg_studio_project_members m where m.project_id=p_project_id and m.left_at is null
   ) x
   on conflict(room_id,user_id) do update set left_at=null;
 else
   insert into public.tgg_call_participants(room_id,user_id,mic_enabled,camera_enabled,left_at) values(v_room,v_uid,true,(v_type='video'),null)
   on conflict(room_id,user_id) do update set left_at=null;
 end if;
 select count(*) into v_count from public.tgg_call_participants p where p.room_id=v_room and p.left_at is null;
 return jsonb_build_object('ok',true,'room_id',v_room,'studio_project_id',p_project_id,'room_type',v_type,'created',v_created,'participant_count',v_count);
end$$;

create or replace function public.tgg_studio_call_room_leave(p_room_id uuid)
returns jsonb language plpgsql security definer set search_path to 'public','pg_catalog' as $$
declare v_uid uuid:=auth.uid(); v_count integer;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 update public.tgg_call_participants set left_at=now() where room_id=p_room_id and user_id=v_uid and left_at is null;
 get diagnostics v_count=row_count;
 return jsonb_build_object('ok',true,'room_id',p_room_id,'left',v_count>0);
end$$;

create or replace function public.tgg_call_room_bundle(p_room_id uuid)
returns jsonb language plpgsql stable set search_path to 'public','pg_catalog' as $$
declare v_uid uuid:=auth.uid();
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
 if not exists(select 1 from public.tgg_call_participants where room_id=p_room_id and user_id=v_uid and left_at is null) then raise exception 'ROOM_ACCESS_DENIED'; end if;
 return jsonb_build_object(
  'ok',true,
  'room',(select jsonb_build_object('id',r.id,'title',r.title,'room_type',r.room_type,'status',r.status,'is_group',r.is_group,'created_by',r.created_by,'created_at',r.created_at,'studio_project_id',r.studio_project_id) from public.tgg_call_rooms r where r.id=p_room_id),
  'participants',coalesce((select jsonb_agg(jsonb_build_object('user_id',p.user_id,'mic_enabled',p.mic_enabled,'camera_enabled',p.camera_enabled,'joined_at',p.joined_at,'left_at',p.left_at)) from public.tgg_call_participants p where p.room_id=p_room_id and p.left_at is null),'[]'::jsonb),
  'generated_at',now()
 );
end$$;

