insert into public.tgg_world_contacts(contact_key,contact_type,display_name,specialty,reputation_required,availability,metadata)
select i.contact_key,
       case i.contact_key
         when 'contact-dre-kingsley' then 'producer'
         when 'contact-maya-reed' then 'label_contact'
         when 'contact-kilo-verse' then 'npc'
         when 'contact-zara-stone' then 'promoter'
         when 'contact-lens-carter' then 'director'
         when 'contact-nia-volt' then 'promoter'
         when 'contact-jules-martin' then 'manager'
         when 'contact-rico-banks' then 'label_contact'
         else 'npc' end,
       i.display_name,
       concat_ws(' · ',i.role_title,i.organization),
       i.reputation_required,
       'available',
       jsonb_build_object('source','WORLD-V12.2-CONTACT-BRIDGE','industry_role',i.role_title,'organization',i.organization)
from public.tgg_world_industry_contacts i
where i.enabled=true
on conflict(contact_key) do update set
  display_name=excluded.display_name,
  specialty=excluded.specialty,
  reputation_required=excluded.reputation_required,
  metadata=public.tgg_world_contacts.metadata||excluded.metadata,
  updated_at=now();

create index if not exists tgg_world_contact_offers_contact_fk_idx on public.tgg_world_contact_offers(contact_id);
create index if not exists tgg_world_contact_offers_contract_pending_idx on public.tgg_world_contact_offers(user_id,status,(terms->>'contract_key')) where status='pending';

create or replace function private.tgg_world_v12_generate_contact_offer(p_contact_key text)
returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_uid uuid:=auth.uid();
  v_char public.world_characters%rowtype;
  v_ind public.tgg_world_industry_contacts%rowtype;
  v_contact public.tgg_world_contacts%rowtype;
  v_rel public.tgg_world_contact_relationships%rowtype;
  v_contract public.tgg_world_career_contracts%rowtype;
  v_career_rep integer:=0;
  v_offer public.tgg_world_contact_offers%rowtype;
  v_offer_type text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_char from public.world_characters where user_id=v_uid and character_status='active' order by updated_at desc limit 1;
  if v_char.id is null or nullif(v_char.active_career,'') is null then return null; end if;
  select * into v_ind from public.tgg_world_industry_contacts where contact_key=p_contact_key and enabled=true;
  if v_ind.contact_key is null then return null; end if;
  select * into v_contact from public.tgg_world_contacts where contact_key=p_contact_key;
  if v_contact.id is null then return null; end if;
  select * into v_rel from public.tgg_world_contact_relationships where character_id=v_char.id and contact_key=p_contact_key;
  if v_rel.character_id is null or v_rel.meetings_completed<1 or v_rel.trust_score<8 then return null; end if;
  v_career_rep:=coalesce((select reputation from public.tgg_world_career_reputation where character_id=v_char.id and career_key=v_char.active_career),0);

  select c.* into v_contract
  from jsonb_array_elements_text(coalesce(v_ind.unlocks->'contracts','[]'::jsonb)) with ordinality u(contract_key,ord)
  join public.tgg_world_career_contracts c on c.contract_key=u.contract_key and c.enabled=true
  left join public.tgg_world_character_contracts cc on cc.character_id=v_char.id and cc.contract_key=c.contract_key
  where c.career_key=v_char.active_career
    and v_career_rep>=c.reputation_required
    and (cc.id is null or cc.status='abandoned' or (cc.status='completed' and c.repeatable))
    and not exists(
      select 1 from public.tgg_world_contract_chain_steps s
      where s.contract_key=c.contract_key and (
        (s.unlock_condition ? 'previous_contract' and not exists(
          select 1 from public.tgg_world_character_contracts pc
          where pc.character_id=v_char.id and pc.contract_key=s.unlock_condition->>'previous_contract' and pc.status='completed'))
        or (s.unlock_condition ? 'reputation' and v_career_rep<coalesce((s.unlock_condition->>'reputation')::integer,0))
        or (s.unlock_condition ? 'relationship_contact' and coalesce((select r.trust_score from public.tgg_world_contact_relationships r where r.character_id=v_char.id and r.contact_key=s.unlock_condition->>'relationship_contact'),0)<coalesce((s.unlock_condition->>'trust_score')::integer,0))
      )
    )
  order by u.ord
  limit 1;
  if v_contract.contract_key is null then return null; end if;

  select * into v_offer from public.tgg_world_contact_offers
  where user_id=v_uid and status='pending' and terms->>'contract_key'=v_contract.contract_key
  order by created_at desc limit 1;
  if v_offer.id is not null then
    return jsonb_build_object('offer_id',v_offer.id,'status',v_offer.status,'title',v_offer.title,'contact_key',p_contact_key,'contract_key',v_contract.contract_key,'offer_type',v_offer.offer_type,'expires_at',v_offer.expires_at,'existing',true);
  end if;

  v_offer_type:=case v_contract.contract_type
    when 'showcase' then 'show_booking'
    when 'booking' then 'show_booking'
    when 'visual' then 'video_shoot'
    when 'service' then 'mix_master'
    when 'placement' then 'studio_session'
    when 'media' then 'promotion'
    when 'development' then 'management'
    when 'business' then 'management'
    else 'mission' end;

  insert into public.tgg_world_contact_offers(user_id,contact_id,offer_type,title,body,status,terms,expires_at)
  values(v_uid,v_contact.id,v_offer_type,v_contract.title,
         v_ind.display_name||' has an opportunity for your '||v_char.active_career||' career.','pending',
         jsonb_build_object('source','WORLD-V12.2-CONTACT-OFFER','contact_key',p_contact_key,'contract_key',v_contract.contract_key,'contract_type',v_contract.contract_type,'objectives',v_contract.objectives,'rewards',v_contract.rewards,'career_key',v_contract.career_key),
         now()+interval '7 days')
  returning * into v_offer;

  insert into public.tgg_world_contact_messages(user_id,contact_id,direction,message_type,body,payload)
  values(v_uid,v_contact.id,'inbound','offer',v_ind.display_name||': '||v_contract.title,
         jsonb_build_object('offer_id',v_offer.id,'contract_key',v_contract.contract_key,'source','WORLD-V12.2-CONTACT-OFFER'));
  insert into public.tgg_world_notifications(user_id,notification_type,title,body,action_type,action_payload,priority)
  values(v_uid,'contact','New industry offer',v_ind.display_name||' sent: '||v_contract.title,'open',jsonb_build_object('surface','artist-world','offer_id',v_offer.id,'contact_key',p_contact_key),'normal');

  return jsonb_build_object('offer_id',v_offer.id,'status','pending','title',v_offer.title,'contact_key',p_contact_key,'contract_key',v_contract.contract_key,'offer_type',v_offer.offer_type,'expires_at',v_offer.expires_at,'existing',false);
end
$$;

create or replace function private.tgg_world_v12_meet_industry_contact(p_contact_key text,p_idempotency_key text)
returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_uid uuid:=auth.uid(); v_character_id uuid; v_rep bigint:=0; v_required integer; v_meeting_id uuid; v_rel record; v_existing jsonb; v_offer jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(p_idempotency_key)>160 then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  select result into v_existing from private.tgg_world_v12_contact_meetings where user_id=v_uid and idempotency_key=p_idempotency_key limit 1;
  if v_existing is not null then return v_existing||jsonb_build_object('idempotent',true); end if;
  select id into v_character_id from public.world_characters where user_id=v_uid and character_status='active' order by updated_at desc limit 1;
  if v_character_id is null then raise exception 'WORLD_CHARACTER_REQUIRED' using errcode='22023'; end if;
  v_rep:=coalesce((select reputation from public.tgg_world_players where user_id=v_uid limit 1),0);
  select reputation_required into v_required from public.tgg_world_industry_contacts where contact_key=p_contact_key and enabled=true;
  if v_required is null then raise exception 'CONTACT_NOT_FOUND' using errcode='22023'; end if;
  if v_rep<v_required then raise exception 'REPUTATION_REQUIRED:%',v_required using errcode='22023'; end if;
  if exists(select 1 from private.tgg_world_v12_contact_meetings where user_id=v_uid and contact_key=p_contact_key and created_at>now()-interval '30 minutes') then raise exception 'CONTACT_MEETING_COOLDOWN' using errcode='22023'; end if;
  insert into public.tgg_world_contact_relationships(character_id,contact_key,relationship_xp,relationship_level,trust_score,meetings_completed,last_interaction_at,memory,updated_at)
  values(v_character_id,p_contact_key,20,1,8,1,now(),jsonb_build_object('last_meeting','v12_intro'),now())
  on conflict(character_id,contact_key) do update set relationship_xp=public.tgg_world_contact_relationships.relationship_xp+20,
    relationship_level=greatest(public.tgg_world_contact_relationships.relationship_level,1+((public.tgg_world_contact_relationships.relationship_xp+20)/100)),
    trust_score=least(100,public.tgg_world_contact_relationships.trust_score+5),meetings_completed=public.tgg_world_contact_relationships.meetings_completed+1,
    last_interaction_at=now(),memory=coalesce(public.tgg_world_contact_relationships.memory,'{}'::jsonb)||jsonb_build_object('last_meeting','v12_intro','last_meeting_at',now()),updated_at=now()
  returning relationship_xp,relationship_level,trust_score,meetings_completed into v_rel;
  insert into private.tgg_world_v12_contact_meetings(user_id,character_id,contact_key,relationship_xp_delta,trust_delta,idempotency_key)
  values(v_uid,v_character_id,p_contact_key,20,5,p_idempotency_key) returning id into v_meeting_id;
  v_offer:=private.tgg_world_v12_generate_contact_offer(p_contact_key);
  v_existing:=jsonb_build_object('ok',true,'version','WORLD-V12.2-RELATIONSHIP-OFFERS','meeting_id',v_meeting_id,'contact_key',p_contact_key,
    'relationship',jsonb_build_object('xp',v_rel.relationship_xp,'level',v_rel.relationship_level,'trust',v_rel.trust_score,'meetings',v_rel.meetings_completed),'offer',v_offer,'idempotent',false);
  update private.tgg_world_v12_contact_meetings set result=v_existing where id=v_meeting_id;
  return v_existing;
end
$$;

create or replace function private.tgg_world_v12_contact_offers_bundle()
returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare v_uid uuid:=auth.uid(); begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  update public.tgg_world_contact_offers set status='expired',responded_at=coalesce(responded_at,now()) where user_id=v_uid and status='pending' and expires_at is not null and expires_at<now();
  return jsonb_build_object('ok',true,'version','WORLD-V12.2-RELATIONSHIP-OFFERS','offers',coalesce((
    select jsonb_agg(jsonb_build_object('offer_id',o.id,'status',o.status,'offer_type',o.offer_type,'title',o.title,'body',o.body,'terms',o.terms,'expires_at',o.expires_at,'created_at',o.created_at,'responded_at',o.responded_at,'contact_key',c.contact_key,'contact_name',c.display_name) order by o.created_at desc)
    from (select * from public.tgg_world_contact_offers where user_id=v_uid order by created_at desc limit 20) o join public.tgg_world_contacts c on c.id=o.contact_id
  ),'[]'::jsonb));
end
$$;

create or replace function private.tgg_world_v12_accept_contact_offer_impl(p_offer_id uuid,p_idempotency_key text)
returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_uid uuid:=auth.uid(); v_offer public.tgg_world_contact_offers%rowtype; v_contract_key text; v_contract jsonb; v_contact public.tgg_world_contacts%rowtype; v_result jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if p_offer_id is null then raise exception 'OFFER_ID_REQUIRED' using errcode='22023'; end if;
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(p_idempotency_key)>160 then raise exception 'IDEMPOTENCY_KEY_REQUIRED' using errcode='22023'; end if;
  select * into v_offer from public.tgg_world_contact_offers where id=p_offer_id and user_id=v_uid for update;
  if v_offer.id is null then raise exception 'OFFER_NOT_FOUND' using errcode='22023'; end if;
  if v_offer.status='accepted' then return jsonb_build_object('ok',true,'version','WORLD-V12.2-RELATIONSHIP-OFFERS','offer_id',v_offer.id,'status','accepted','contract_key',v_offer.terms->>'contract_key','idempotent',true); end if;
  if v_offer.status<>'pending' then raise exception 'OFFER_NOT_PENDING' using errcode='22023'; end if;
  if v_offer.expires_at is not null and v_offer.expires_at<now() then update public.tgg_world_contact_offers set status='expired',responded_at=now() where id=v_offer.id; raise exception 'OFFER_EXPIRED' using errcode='22023'; end if;
  v_contract_key:=nullif(v_offer.terms->>'contract_key','');
  if v_contract_key is null then raise exception 'OFFER_CONTRACT_MISSING' using errcode='22023'; end if;
  v_contract:=private.tgg_world_v12_accept_career_contract_impl(v_contract_key,'offer:'||v_offer.id::text||':'||p_idempotency_key);
  update public.tgg_world_contact_offers set status='accepted',responded_at=now(),terms=terms||jsonb_build_object('accepted_via','WORLD-V12.2','accepted_at',now()) where id=v_offer.id;
  select * into v_contact from public.tgg_world_contacts where id=v_offer.contact_id;
  insert into public.tgg_world_contact_messages(user_id,contact_id,direction,message_type,body,payload)
  values(v_uid,v_offer.contact_id,'system','offer','Offer accepted: '||v_offer.title,jsonb_build_object('offer_id',v_offer.id,'contract_key',v_contract_key,'source','WORLD-V12.2'));
  insert into public.tgg_world_notifications(user_id,notification_type,title,body,action_type,action_payload,priority)
  values(v_uid,'contact','Offer accepted',v_offer.title,'open',jsonb_build_object('surface','artist-world','contract_key',v_contract_key,'contact_key',v_contact.contact_key),'normal');
  v_result:=jsonb_build_object('ok',true,'version','WORLD-V12.2-RELATIONSHIP-OFFERS','offer_id',v_offer.id,'status','accepted','contract_key',v_contract_key,'contract',v_contract,'idempotent',false);
  return v_result;
end
$$;

create or replace function public.tgg_world_v12_contact_offers_bundle()
returns jsonb language sql security invoker set search_path='' as $$ select private.tgg_world_v12_contact_offers_bundle() $$;
create or replace function public.tgg_world_v12_accept_contact_offer(p_offer_id uuid,p_idempotency_key text)
returns jsonb language sql security invoker set search_path='' as $$ select private.tgg_world_v12_accept_contact_offer_impl(p_offer_id,p_idempotency_key) $$;

revoke all on function private.tgg_world_v12_generate_contact_offer(text) from public,anon;
revoke all on function private.tgg_world_v12_contact_offers_bundle() from public,anon;
revoke all on function private.tgg_world_v12_accept_contact_offer_impl(uuid,text) from public,anon;
revoke all on function public.tgg_world_v12_contact_offers_bundle() from public,anon;
revoke all on function public.tgg_world_v12_accept_contact_offer(uuid,text) from public,anon;
grant usage on schema private to authenticated;
grant execute on function private.tgg_world_v12_contact_offers_bundle() to authenticated;
grant execute on function private.tgg_world_v12_accept_contact_offer_impl(uuid,text) to authenticated;
grant execute on function public.tgg_world_v12_contact_offers_bundle() to authenticated;
grant execute on function public.tgg_world_v12_accept_contact_offer(uuid,text) to authenticated;

