create table public.tgg_control_room_routing_scenes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  scene_name text not null check (char_length(scene_name) between 1 and 80),
  settings jsonb not null default '{}'::jsonb,
  track_settings jsonb not null default '{}'::jsonb,
  is_default boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, scene_name)
);

alter table public.tgg_control_room_routing_scenes enable row level security;

grant select, insert, update, delete on public.tgg_control_room_routing_scenes to authenticated;

create policy "control room routing scenes select own"
on public.tgg_control_room_routing_scenes
for select to authenticated
using ((select auth.uid()) = user_id);

create policy "control room routing scenes insert own"
on public.tgg_control_room_routing_scenes
for insert to authenticated
with check ((select auth.uid()) = user_id);

create policy "control room routing scenes update own"
on public.tgg_control_room_routing_scenes
for update to authenticated
using ((select auth.uid()) = user_id)
with check ((select auth.uid()) = user_id);

create policy "control room routing scenes delete own"
on public.tgg_control_room_routing_scenes
for delete to authenticated
using ((select auth.uid()) = user_id);

create index tgg_control_room_routing_scenes_user_updated_idx
on public.tgg_control_room_routing_scenes (user_id, updated_at desc);

-- ============================================================
-- MIGRATION 20260910184724 world_v11_7_realtime_movement
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

-- V11.7: authenticated, instance-scoped Realtime Broadcast for cosmetic movement.
-- Authoritative location/presence remains in public.world_presence.

drop policy if exists "tgg world instance movement receive" on realtime.messages;
drop policy if exists "tgg world instance movement send" on realtime.messages;

create policy "tgg world instance movement receive"
on realtime.messages
for select
to authenticated
using (
  realtime.messages.extension = 'broadcast'
  and exists (
    select 1
    from tgg_private.current_world_instance_ids() as i(instance_id)
    where (select realtime.topic()) = ('world:' || i.instance_id::text || ':moves')
  )
);

create policy "tgg world instance movement send"
on realtime.messages
for insert
to authenticated
with check (
  realtime.messages.extension = 'broadcast'
  and exists (
    select 1
    from tgg_private.current_world_instance_ids() as i(instance_id)
    where (select realtime.topic()) = ('world:' || i.instance_id::text || ':moves')
  )
);

create or replace function private.tgg_world_v11_6_presence_bootstrap_impl()
returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_uid uuid := auth.uid();
  v_character public.world_characters%rowtype;
  v_location_key text;
  v_join jsonb;
  v_hb jsonb;
  v_presence_key text;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_character
  from public.world_characters
  where user_id=v_uid and character_status='active'
  limit 1;
  if v_character.id is null then
    return jsonb_build_object('ok',true,'character_ready',false,'joined',false);
  end if;

  select location_key into v_location_key
  from public.tgg_world_locations
  where id=v_character.current_location_id and enabled=true;
  if v_location_key is null then raise exception 'CURRENT_LOCATION_UNAVAILABLE'; end if;

  v_join := tgg_private.world_join_location(v_location_key);
  v_hb := tgg_private.world_presence_heartbeat(
    jsonb_build_object('x',0,'y',0,'z',0),
    jsonb_build_object('location_key',v_location_key,'source','artist-world-v11.7')
  );

  select replace(p.id::text,'-','') into v_presence_key
  from public.world_presence p
  where p.user_id=v_uid
    and p.instance_id=(v_join->>'instance_id')::uuid
    and p.left_at is null
  order by p.heartbeat_at desc
  limit 1;

  return jsonb_build_object(
    'ok',true,
    'character_ready',true,
    'joined',true,
    'location_key',v_location_key,
    'instance_id',v_join->>'instance_id',
    'presence_key',v_presence_key,
    'population',v_join->'population',
    'capacity',v_join->'capacity',
    'heartbeat',v_hb,
    'realtime',jsonb_build_object(
      'movement_topic','world:' || (v_join->>'instance_id') || ':moves',
      'private',true,
      'authoritative',false
    )
  );
end
$$;

create or replace function private.tgg_world_v11_6_presence_bundle_impl()
returns jsonb
language plpgsql
stable
security definer
set search_path=''
as $$
declare
  v_uid uuid := auth.uid();
  v_presence public.world_presence%rowtype;
  v_instance public.world_instances%rowtype;
  v_location_key text;
  v_players jsonb := '[]'::jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;

  select * into v_presence
  from public.world_presence
  where user_id=v_uid and left_at is null and heartbeat_at > now()-interval '2 minutes'
  order by heartbeat_at desc
  limit 1;

  if v_presence.id is null then
    return jsonb_build_object('ok',true,'present',false,'players','[]'::jsonb,'population',0);
  end if;

  select * into v_instance from public.world_instances where id=v_presence.instance_id;
  select l.location_key into v_location_key from public.tgg_world_locations l where l.id=v_instance.location_id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'presence_key',replace(p.id::text,'-',''),
    'stage_name',c.stage_name,
    'active_career',c.active_career,
    'avatar',jsonb_build_object(
      'accent',coalesce(ap.profile->>'accent',c.avatar_config->>'accent','#e50914'),
      'build',coalesce(ap.profile->>'build',c.avatar_config->>'build','balanced'),
      'vibe',coalesce(ap.profile->>'vibe',c.avatar_config->>'vibe','street')
    ),
    'position',coalesce(p.position,'{}'::jsonb),
    'activity',coalesce(p.activity,'{}'::jsonb),
    'presence_state',p.presence_state,
    'is_me',p.user_id=v_uid,
    'heartbeat_at',p.heartbeat_at
  ) order by p.joined_at),'[]'::jsonb)
  into v_players
  from public.world_presence p
  join public.world_characters c on c.id=p.character_id
  left join public.tgg_world_avatar_profiles ap on ap.user_id=p.user_id
  where p.instance_id=v_presence.instance_id
    and p.left_at is null
    and p.heartbeat_at > now()-interval '2 minutes';

  return jsonb_build_object(
    'ok',true,
    'version','WORLD-V11.7-REALTIME-MOVEMENT',
    'present',true,
    'presence_key',replace(v_presence.id::text,'-',''),
    'instance',jsonb_build_object(
      'key',v_instance.instance_key,
      'status',v_instance.status,
      'capacity',v_instance.capacity,
      'location_key',v_location_key
    ),
    'realtime',jsonb_build_object(
      'movement_topic','world:' || v_presence.instance_id::text || ':moves',
      'private',true,
      'authoritative',false
    ),
    'population',jsonb_array_length(v_players),
    'players',v_players,
    'privacy',jsonb_build_object(
      'user_ids_exposed',false,
      'character_ids_exposed',false,
      'presence_key_pseudonymous',true
    )
  );
end
$$;


-- ============================================================
-- MIGRATION 20260910185013 lock_game_status_transitions
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

create or replace function public.tgg_game_set_status(p_game_id uuid, p_status text)
returns jsonb
language plpgsql
set search_path to 'public', 'pg_catalog'
as $function$
declare
  v_uid uuid := auth.uid();
  v_status text := lower(btrim(coalesce(p_status,'')));
  v_current text;
  v_id uuid;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  if v_status not in ('draft','open','live','ended') then
    raise exception 'STATUS_INVALID';
  end if;

  select status into v_current
  from public.tgg_games
  where id=p_game_id and created_by=v_uid
  for update;

  if v_current is null then
    raise exception 'GAME_NOT_FOUND_OR_NOT_OWNED';
  end if;

  if v_current = v_status then
    return jsonb_build_object('ok',true,'game_id',p_game_id,'status',v_status,'unchanged',true);
  end if;

  if not (
    (v_current='draft' and v_status='open') or
    (v_current='open' and v_status='live') or
    (v_current='live' and v_status='ended')
  ) then
    raise exception 'INVALID_STATUS_TRANSITION' using detail=concat('Cannot transition game from ',v_current,' to ',v_status);
  end if;

  update public.tgg_games
  set status=v_status
  where id=p_game_id and created_by=v_uid
  returning id into v_id;

  if v_id is null then
    raise exception 'GAME_NOT_FOUND_OR_NOT_OWNED';
  end if;

  return jsonb_build_object('ok',true,'game_id',v_id,'status',v_status);
end
$function$;

