-- MIGRATION 20260910185138 harden_game_status_direct_writes
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

create or replace function public.tgg_enforce_game_status_transition()
returns trigger
language plpgsql
set search_path to 'public','pg_catalog'
as $$
begin
  if new.status = old.status then
    return new;
  end if;
  if not (
    (old.status='draft' and new.status='open') or
    (old.status='open' and new.status='live') or
    (old.status='live' and new.status='ended')
  ) then
    raise exception 'INVALID_STATUS_TRANSITION' using detail=concat('Cannot transition game from ',old.status,' to ',new.status);
  end if;
  return new;
end;
$$;

create or replace function public.tgg_enforce_game_session_status_transition()
returns trigger
language plpgsql
set search_path to 'public','pg_catalog'
as $$
begin
  if new.status = old.status then
    return new;
  end if;
  if not (
    (old.status='open' and new.status='active') or
    (old.status='active' and new.status='ended')
  ) then
    raise exception 'INVALID_SESSION_STATUS_TRANSITION' using detail=concat('Cannot transition session from ',old.status,' to ',new.status);
  end if;
  return new;
end;
$$;

drop trigger if exists tgg_games_status_transition_guard on public.tgg_games;
create trigger tgg_games_status_transition_guard
before update of status on public.tgg_games
for each row execute function public.tgg_enforce_game_status_transition();

drop trigger if exists tgg_game_sessions_status_transition_guard on public.tgg_game_sessions;
create trigger tgg_game_sessions_status_transition_guard
before update of status on public.tgg_game_sessions
for each row execute function public.tgg_enforce_game_session_status_transition();

revoke execute on function public.tgg_enforce_game_status_transition() from public, anon, authenticated;
revoke execute on function public.tgg_enforce_game_session_status_transition() from public, anon, authenticated;

-- ============================================================
-- MIGRATION 20260910185208 harden_game_score_reward_integrity
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

CREATE OR REPLACE FUNCTION public.tgg_enforce_game_score_integrity()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public','pg_catalog'
AS $$
BEGIN
  IF NEW.score < 0 OR NEW.wins < 0 THEN
    RAISE EXCEPTION 'INVALID_SCORE_STATE';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.session_id <> OLD.session_id OR NEW.user_id <> OLD.user_id THEN
      RAISE EXCEPTION 'SCORE_IDENTITY_IMMUTABLE';
    END IF;
    IF NEW.score < OLD.score THEN
      RAISE EXCEPTION 'SCORE_CANNOT_DECREASE';
    END IF;
    IF NEW.wins < OLD.wins THEN
      RAISE EXCEPTION 'WINS_CANNOT_DECREASE';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS tgg_game_scores_integrity_guard ON public.tgg_game_scores;
CREATE TRIGGER tgg_game_scores_integrity_guard
BEFORE INSERT OR UPDATE ON public.tgg_game_scores
FOR EACH ROW EXECUTE FUNCTION public.tgg_enforce_game_score_integrity();

CREATE OR REPLACE FUNCTION public.tgg_enforce_game_session_status_transition()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public','pg_catalog'
AS $$
BEGIN
  IF NEW.status = OLD.status THEN RETURN NEW; END IF;
  IF NOT ((OLD.status='open' AND NEW.status='active') OR (OLD.status='active' AND NEW.status='ended')) THEN
    RAISE EXCEPTION 'INVALID_SESSION_STATUS_TRANSITION' USING DETAIL=concat('Cannot transition session from ',OLD.status,' to ',NEW.status);
  END IF;
  RETURN NEW;
END;
$$;

