-- MIGRATION 20260910185858 world_v11_7_real_multiplayer_witness
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

create table if not exists private.tgg_world_multiplayer_witness (
  witness_key text primary key,
  status text not null default 'pending' check (status in ('pending','passed')),
  required_players integer not null default 2 check (required_players >= 2),
  peak_population integer not null default 0 check (peak_population >= 0),
  last_current_population integer not null default 0 check (last_current_population >= 0),
  observed_instance_id uuid references public.world_instances(id) on delete set null,
  first_passed_at timestamptz,
  last_observed_at timestamptz,
  last_checked_at timestamptz not null default now(),
  evidence jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);

revoke all on private.tgg_world_multiplayer_witness from public, anon, authenticated;

create or replace function private.tgg_world_v11_7_multiplayer_witness_eval()
returns jsonb
language plpgsql
security definer
set search_path=''
as $$
declare
  v_uid uuid := auth.uid();
  v_instance uuid;
  v_population integer := 0;
  v_peak integer := 0;
  v_status text := 'pending';
  v_passed_at timestamptz;
  v_last_checked timestamptz;
  v_location_key text;
  v_instance_type text;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select x.instance_id,x.population,x.location_key,x.instance_type
  into v_instance,v_population,v_location_key,v_instance_type
  from (
    select p.instance_id,
           count(distinct p.user_id)::integer as population,
           l.location_key,
           i.instance_type
    from public.world_presence p
    join auth.users u on u.id=p.user_id
    join public.world_characters c on c.id=p.character_id and c.user_id=p.user_id and c.character_status='active'
    join public.world_instances i on i.id=p.instance_id and i.status in ('active','draining')
    join public.tgg_world_locations l on l.id=i.location_id and l.enabled=true
    where p.left_at is null
      and p.presence_state <> 'offline'
      and p.heartbeat_at > now()-interval '2 minutes'
    group by p.instance_id,l.location_key,i.instance_type
    order by count(distinct p.user_id) desc,p.instance_id
    limit 1
  ) x;

  v_population := coalesce(v_population,0);

  insert into private.tgg_world_multiplayer_witness(
    witness_key,status,required_players,peak_population,last_current_population,
    observed_instance_id,first_passed_at,last_observed_at,last_checked_at,evidence,updated_at
  ) values (
    'same_instance_two_real_users',
    case when v_population>=2 then 'passed' else 'pending' end,
    2,
    v_population,
    v_population,
    case when v_population>=2 then v_instance else null end,
    case when v_population>=2 then now() else null end,
    case when v_population>=2 then now() else null end,
    now(),
    jsonb_build_object(
      'source','server_observed_world_presence',
      'freshness_seconds',120,
      'distinct_authenticated_users',v_population,
      'character_user_binding_required',true,
      'instance_status_required',jsonb_build_array('active','draining'),
      'location_enabled_required',true,
      'client_presence_mutation_allowed',false,
      'location_key',v_location_key,
      'instance_type',v_instance_type
    ),
    now()
  )
  on conflict(witness_key) do update
  set status=case when private.tgg_world_multiplayer_witness.status='passed' or excluded.status='passed' then 'passed' else 'pending' end,
      peak_population=greatest(private.tgg_world_multiplayer_witness.peak_population,excluded.peak_population),
      last_current_population=excluded.last_current_population,
      observed_instance_id=case when excluded.status='passed' then excluded.observed_instance_id else private.tgg_world_multiplayer_witness.observed_instance_id end,
      first_passed_at=coalesce(private.tgg_world_multiplayer_witness.first_passed_at,excluded.first_passed_at),
      last_observed_at=case when excluded.status='passed' then excluded.last_observed_at else private.tgg_world_multiplayer_witness.last_observed_at end,
      last_checked_at=excluded.last_checked_at,
      evidence=excluded.evidence,
      updated_at=now();

  select status,peak_population,first_passed_at,last_checked_at
  into v_status,v_peak,v_passed_at,v_last_checked
  from private.tgg_world_multiplayer_witness
  where witness_key='same_instance_two_real_users';

  return jsonb_build_object(
    'ok',true,
    'version','WORLD-V11.7.1-REAL-MULTIPLAYER-WITNESS',
    'status',v_status,
    'passed',v_status='passed',
    'required_players',2,
    'current_max_population',v_population,
    'peak_population',v_peak,
    'passed_at',v_passed_at,
    'last_checked_at',v_last_checked,
    'evidence_source','server_observed_world_presence',
    'freshness_seconds',120,
    'synthetic_client_presence_possible',false,
    'privacy',jsonb_build_object('user_ids_exposed',false,'character_ids_exposed',false,'instance_id_exposed',false)
  );
end
$$;

revoke all on function private.tgg_world_v11_7_multiplayer_witness_eval() from public, anon;
grant execute on function private.tgg_world_v11_7_multiplayer_witness_eval() to authenticated;

create or replace function public.tgg_world_v11_7_multiplayer_proof()
returns jsonb
language sql
set search_path=''
as $$
  select private.tgg_world_v11_7_multiplayer_witness_eval();
$$;

revoke all on function public.tgg_world_v11_7_multiplayer_proof() from public, anon;
grant execute on function public.tgg_world_v11_7_multiplayer_proof() to authenticated;


