-- MIGRATION 20260910191527 quarantine_synthetic_new_player_failure
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

DO $$
DECLARE
  v_step uuid;
BEGIN
  SELECT st.id INTO v_step
  FROM public.tgg_playtest_steps st
  JOIN public.tgg_playtest_scenarios s ON s.id = st.scenario_id
  WHERE s.scenario_key = 'alpha.new-player'
    AND st.action_key = 'character.create'
  LIMIT 1;

  IF v_step IS NOT NULL THEN
    DELETE FROM public.tgg_playtest_step_results r
    WHERE r.step_id = v_step
      AND COALESCE((r.detail->>'synthetic')::boolean,false) = true
      AND r.status = 'failed'
      AND r.evidence_uri = 'qa://ab009/fail/character';
  END IF;
END $$;

-- ============================================================
-- MIGRATION 20260910194010 harden_tgg_private_security_definer_anon_exposure
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

do $$
declare r record;
begin
  for r in
    select p.oid,
           n.nspname,
           p.proname,
           pg_get_function_identity_arguments(p.oid) as args,
           has_function_privilege('authenticated', p.oid, 'EXECUTE') as auth_had_exec,
           has_function_privilege('service_role', p.oid, 'EXECUTE') as service_had_exec
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'tgg_private'
      and p.prosecdef
      and has_function_privilege('anon', p.oid, 'EXECUTE')
  loop
    execute format('REVOKE ALL ON FUNCTION %I.%I(%s) FROM PUBLIC', r.nspname, r.proname, r.args);
    execute format('REVOKE ALL ON FUNCTION %I.%I(%s) FROM anon', r.nspname, r.proname, r.args);
    if r.auth_had_exec then
      execute format('GRANT EXECUTE ON FUNCTION %I.%I(%s) TO authenticated', r.nspname, r.proname, r.args);
    end if;
    if r.service_had_exec then
      execute format('GRANT EXECUTE ON FUNCTION %I.%I(%s) TO service_role', r.nspname, r.proname, r.args);
    end if;
  end loop;
end $$;

