create or replace function private.tgg_world_v12_credit_label_meeting()
returns trigger
language plpgsql
security definer
set search_path=''
as $$
declare
  v_role text;
  v_org text;
begin
  select lower(coalesce(i.role_title,'')),lower(coalesce(i.organization,''))
  into v_role,v_org
  from public.tgg_world_industry_contacts i
  where i.contact_key=new.contact_key
    and i.enabled=true;

  if coalesce(v_role,'') like '%a&r%'
     or coalesce(v_role,'') like '%label%'
     or coalesce(v_org,'') like '%records%'
  then
    perform private.tgg_world_credit_contract_event(
      new.character_id,
      'label_meeting',
      'v12_contact_meeting',
      new.id::text,
      jsonb_build_object(
        'contact_key',new.contact_key,
        'meeting_id',new.id,
        'industry_role',v_role,
        'organization',v_org,
        'world_layer','v12.3'
      )
    );
  end if;
  return new;
end
$$;

revoke all on function private.tgg_world_v12_credit_label_meeting() from public,anon,authenticated;

drop trigger if exists tgg_world_v12_credit_label_meeting on private.tgg_world_v12_contact_meetings;
