create or replace function private.tgg_world_v12_close_offer_on_contract_completion()
returns trigger
language plpgsql
security definer
set search_path=''
as $$
declare
  v_uid uuid;
begin
  if new.status='completed' and old.status is distinct from 'completed' then
    select wc.user_id into v_uid
    from public.world_characters wc
    where wc.id=new.character_id;

    if v_uid is not null then
      update public.tgg_world_contact_offers o
      set status='completed',
          terms=coalesce(o.terms,'{}'::jsonb)||jsonb_build_object(
            'contract_completed_via','WORLD-V12.3',
            'contract_completed_at',coalesce(new.completed_at,now()),
            'character_contract_id',new.id
          )
      where o.user_id=v_uid
        and o.status='accepted'
        and o.terms->>'source'='WORLD-V12.2-CONTACT-OFFER'
        and o.terms->>'contract_key'=new.contract_key;
    end if;
  end if;
  return new;
end
$$;

revoke all on function private.tgg_world_v12_close_offer_on_contract_completion() from public,anon,authenticated;

drop trigger if exists tgg_world_v12_close_offer_on_contract_completion on public.tgg_world_character_contracts;
create trigger tgg_world_v12_close_offer_on_contract_completion
after update of status on public.tgg_world_character_contracts
for each row execute function private.tgg_world_v12_close_offer_on_contract_completion();

