-- MIGRATION 20260910210615 harden_control_room_engineer_sync_private_broadcast
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

create or replace function tgg_private.studio_realtime_topic_allowed(p_topic text)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_project uuid;
begin
  if v_uid is null or p_topic is null or p_topic !~ '^cr-engineer-[0-9a-fA-F-]{36}$' then
    return false;
  end if;
  begin
    v_project := substring(p_topic from length('cr-engineer-') + 1)::uuid;
  exception when others then
    return false;
  end;
  return exists (
    select 1 from public.tgg_studio_projects p
    where p.id = v_project and p.user_id = v_uid
  ) or exists (
    select 1 from public.tgg_studio_project_members m
    where m.project_id = v_project and m.user_id = v_uid and m.left_at is null
  );
end
$$;
revoke all on function tgg_private.studio_realtime_topic_allowed(text) from public, anon;
grant execute on function tgg_private.studio_realtime_topic_allowed(text) to authenticated;

drop policy if exists "tgg control room engineer sync receive" on realtime.messages;
create policy "tgg control room engineer sync receive"
on realtime.messages for select to authenticated
using (
  extension = 'broadcast'
  and tgg_private.studio_realtime_topic_allowed((select realtime.topic()))
);

drop policy if exists "tgg control room engineer sync send" on realtime.messages;
create policy "tgg control room engineer sync send"
on realtime.messages for insert to authenticated
with check (
  extension = 'broadcast'
  and tgg_private.studio_realtime_topic_allowed((select realtime.topic()))
);

