-- ============================================================
-- MIGRATION 20260910210834 tgg_world_v12_4_persisted_contract_objective_reconciliation
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

create or replace function private.tgg_world_v12_reconcile_persisted_contract_objectives()
returns jsonb
language plpgsql
security definer
set search_path to ''
as $function$
declare
  v_uid uuid := auth.uid();
  v_char record;
  v_state record;
  v_event record;
  v_result jsonb;
  v_credited integer := 0;
  v_completed integer := 0;
  v_scanned integer := 0;
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  select wc.id, wc.active_career
  into v_char
  from public.world_characters wc
  where wc.user_id=v_uid
    and wc.character_status='active'
  order by wc.updated_at desc
  limit 1;

  if v_char.id is null then
    return jsonb_build_object(
      'ok',true,
      'version','WORLD-V12.4-PERSISTED-OBJECTIVE-RECONCILIATION',
      'character_present',false,
      'scanned',0,
      'credited',0,
      'completed',0
    );
  end if;

  for v_state in
    select cc.id as contract_id,
           cc.contract_key,
           cc.accepted_at,
           c.objectives
    from public.tgg_world_character_contracts cc
    join public.tgg_world_career_contracts c
      on c.contract_key=cc.contract_key
     and c.enabled=true
    where cc.character_id=v_char.id
      and cc.status='active'
      and c.career_key=v_char.active_career
    order by cc.accepted_at,cc.id
  loop
    if exists (
      select 1 from jsonb_array_elements(v_state.objectives) o
      where o->>'type'='radio_session'
    ) then
      for v_event in
        select r.id,r.published_at,r.title,r.show_type
        from public.tgg_radio_shows r
        where r.user_id=v_uid
          and r.status='published'
          and r.published_at is not null
          and r.published_at>=v_state.accepted_at
        order by r.published_at,r.id
      loop
        v_scanned:=v_scanned+1;
        v_result:=private.tgg_world_credit_contract_event(
          v_char.id,
          'radio_session',
          'radio_show_published',
          v_event.id::text,
          jsonb_build_object(
            'show_id',v_event.id,
            'title',v_event.title,
            'show_type',v_event.show_type,
            'published_at',v_event.published_at,
            'world_layer','v12.4'
          )
        );
        v_credited:=v_credited+coalesce((v_result->>'credited')::integer,0);
        v_completed:=v_completed+coalesce((v_result->>'completed')::integer,0);
      end loop;
    end if;

    if exists (
      select 1 from jsonb_array_elements(v_state.objectives) o
      where o->>'type'='metadata_review'
    ) then
      for v_event in
        select d.release_id,d.updated_at,d.primary_language,d.territories
        from public.tgg_distribution_release_metadata d
        where d.owner_user_id=v_uid
          and d.updated_at>=v_state.accepted_at
          and nullif(btrim(coalesce(d.label_name,'')),'') is not null
          and nullif(btrim(coalesce(d.copyright_line,'')),'') is not null
          and nullif(btrim(coalesce(d.publishing_line,'')),'') is not null
          and nullif(btrim(coalesce(d.primary_language,'')),'') is not null
          and jsonb_typeof(d.territories)='array'
          and jsonb_array_length(d.territories)>0
        order by d.updated_at,d.release_id
      loop
        v_scanned:=v_scanned+1;
        v_result:=private.tgg_world_credit_contract_event(
          v_char.id,
          'metadata_review',
          'distribution_metadata_review',
          v_event.release_id::text,
          jsonb_build_object(
            'release_id',v_event.release_id,
            'metadata_updated_at',v_event.updated_at,
            'primary_language',v_event.primary_language,
            'territory_count',jsonb_array_length(v_event.territories),
            'world_layer','v12.4'
          )
        );
        v_credited:=v_credited+coalesce((v_result->>'credited')::integer,0);
        v_completed:=v_completed+coalesce((v_result->>'completed')::integer,0);
      end loop;
    end if;

    if exists (
      select 1 from jsonb_array_elements(v_state.objectives) o
      where o->>'type'='rights_review'
    ) then
      for v_event in
        select d.release_id,d.rights_confirmed_at,d.updated_at
        from public.tgg_distribution_release_metadata d
        where d.owner_user_id=v_uid
          and d.rights_confirmed=true
          and d.rights_confirmed_at is not null
          and d.rights_confirmed_at>=v_state.accepted_at
          and nullif(btrim(coalesce(d.label_name,'')),'') is not null
          and nullif(btrim(coalesce(d.copyright_line,'')),'') is not null
          and nullif(btrim(coalesce(d.publishing_line,'')),'') is not null
          and jsonb_typeof(d.territories)='array'
          and jsonb_array_length(d.territories)>0
          and not exists (
            select 1
            from public.tgg_clearance_items ci
            where ci.owner_user_id=v_uid
              and ci.release_id=d.release_id
              and lower(coalesce(ci.permission_status,'needs_review'))
                  not in ('cleared','approved','licensed','not_required')
          )
        order by d.rights_confirmed_at,d.release_id
      loop
        v_scanned:=v_scanned+1;
        v_result:=private.tgg_world_credit_contract_event(
          v_char.id,
          'rights_review',
          'distribution_rights_review',
          v_event.release_id::text,
          jsonb_build_object(
            'release_id',v_event.release_id,
            'rights_confirmed_at',v_event.rights_confirmed_at,
            'metadata_updated_at',v_event.updated_at,
            'clearances_resolved',true,
            'world_layer','v12.4'
          )
        );
        v_credited:=v_credited+coalesce((v_result->>'credited')::integer,0);
        v_completed:=v_completed+coalesce((v_result->>'completed')::integer,0);
      end loop;
    end if;

    if exists (
      select 1 from jsonb_array_elements(v_state.objectives) o
      where o->>'type'='producer_session'
    ) then
      for v_event in
        select sl.id as launch_id,
               sl.project_id,
               sl.session_id,
               sl.updated_at
        from public.tgg_world_session_launches sl
        join public.tgg_beat_patterns bp
          on bp.id=sl.session_id
         and bp.project_id=sl.project_id
         and bp.user_id=v_uid
        join public.tgg_studio_projects sp
          on sp.id=bp.project_id
         and sp.user_id=v_uid
        where sl.user_id=v_uid
          and sl.status='saved'
          and sl.session_id is not null
          and sl.project_id is not null
          and coalesce(sl.handoff_payload->>'tool',sl.requested_tool)='beat'
          and coalesce((sl.handoff_payload->>'creator_session_provenance_verified')::boolean,false)=true
          and sl.updated_at>=v_state.accepted_at
        order by sl.updated_at,sl.id
      loop
        v_scanned:=v_scanned+1;
        v_result:=private.tgg_world_credit_contract_event(
          v_char.id,
          'producer_session',
          'world_beat_provenance_save',
          v_event.session_id::text,
          jsonb_build_object(
            'launch_id',v_event.launch_id,
            'project_id',v_event.project_id,
            'beat_pattern_id',v_event.session_id,
            'saved_at',v_event.updated_at,
            'creator_session_provenance_verified',true,
            'world_layer','v12.4'
          )
        );
        v_credited:=v_credited+coalesce((v_result->>'credited')::integer,0);
        v_completed:=v_completed+coalesce((v_result->>'completed')::integer,0);
      end loop;
    end if;

    if exists (
      select 1 from jsonb_array_elements(v_state.objectives) o
      where o->>'type'='video_shoot'
    ) then
      for v_event in
        select j.id as render_job_id,
               j.project_id,
               j.finished_at,
               j.output_format,
               j.output_preset
        from public.tgg_video_studio_render_jobs j
        where j.user_id=v_uid
          and j.status='ready'
          and j.job_type='master'
          and j.finished_at is not null
          and j.finished_at>=v_state.accepted_at
          and exists (
            select 1
            from public.tgg_video_studio_render_outputs ro
            where ro.render_job_id=j.id
              and ro.user_id=v_uid
              and ro.status='ready'
              and nullif(btrim(coalesce(ro.storage_path,'')),'') is not null
          )
        order by j.finished_at,j.id
      loop
        v_scanned:=v_scanned+1;
        v_result:=private.tgg_world_credit_contract_event(
          v_char.id,
          'video_shoot',
          'video_master_render',
          v_event.project_id::text,
          jsonb_build_object(
            'project_id',v_event.project_id,
            'render_job_id',v_event.render_job_id,
            'finished_at',v_event.finished_at,
            'output_format',v_event.output_format,
            'output_preset',v_event.output_preset,
            'world_layer','v12.4'
          )
        );
        v_credited:=v_credited+coalesce((v_result->>'credited')::integer,0);
        v_completed:=v_completed+coalesce((v_result->>'completed')::integer,0);
      end loop;
    end if;
  end loop;

  return jsonb_build_object(
    'ok',true,
    'version','WORLD-V12.4-PERSISTED-OBJECTIVE-RECONCILIATION',
    'character_present',true,
    'character_id',v_char.id,
    'active_career',v_char.active_career,
    'scanned',v_scanned,
    'credited',v_credited,
    'completed',v_completed
  );
end;
$function$;

revoke all on function private.tgg_world_v12_reconcile_persisted_contract_objectives() from public, anon, authenticated;

