create or replace function tgg_private.studio_project_permission(p_project_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path=''
as $function$
declare
  v_uid uuid:=auth.uid();
  v_project public.tgg_studio_projects;
  v_member public.tgg_studio_project_members;
  v_owner boolean:=false;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  select * into v_project from public.tgg_studio_projects where id=p_project_id;
  if v_project.id is null then raise exception 'PROJECT_NOT_FOUND'; end if;
  v_owner:=v_project.user_id=v_uid;
  select * into v_member from public.tgg_studio_project_members
  where project_id=p_project_id and user_id=v_uid and left_at is null;
  if not v_owner and v_member.user_id is null then raise exception 'PROJECT_ACCESS_DENIED' using errcode='42501'; end if;
  return jsonb_build_object(
    'allowed',true,
    'is_owner',v_owner,
    'role',case when v_owner then 'owner' else v_member.role end,
    'can_edit',case when v_owner then true else coalesce(v_member.can_edit,false) end,
    'can_record',case when v_owner then true else coalesce(v_member.can_record,false) end,
    'can_publish',case when v_owner then true else coalesce(v_member.can_publish,false) end
  );
end
$function$;

create or replace function tgg_private.studio_checkpoint_create(p_project_id uuid,p_label text default null)
returns jsonb
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_uid uuid:=auth.uid();
  v_perm jsonb;
  v_project public.tgg_studio_projects;
  v_transport public.tgg_studio_transport_state;
  v_next integer;
  v_id uuid;
  v_label text;
  v_snapshot jsonb;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_perm:=tgg_private.studio_project_permission(p_project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;

  select * into v_project from public.tgg_studio_projects where id=p_project_id for update;
  select * into v_transport from public.tgg_studio_transport_state where project_id=p_project_id;
  select coalesce(max(version_number),0)+1 into v_next from public.tgg_studio_versions where project_id=p_project_id;
  v_label:=coalesce(nullif(left(btrim(coalesce(p_label,'')),120),''),'Checkpoint '||v_next::text);

  v_snapshot:=jsonb_build_object(
    'project',to_jsonb(v_project),
    'transport',case when v_transport.project_id is null then null else to_jsonb(v_transport) end,
    'checkpoint_meta',jsonb_build_object('created_by',v_uid,'created_at',now(),'kind','collab_session_recall'),
    'schema_version',4
  );

  insert into public.tgg_studio_versions(project_id,user_id,version_number,label,snapshot)
  values(p_project_id,v_uid,v_next,v_label,v_snapshot)
  returning id into v_id;

  return jsonb_build_object('ok',true,'id',v_id,'project_id',p_project_id,'version_number',v_next,'label',v_label,'revision',v_project.revision,'created_at',now());
end
$function$;

create or replace function tgg_private.studio_version_list(p_project_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path=''
as $function$
declare
  v_perm jsonb;
begin
  v_perm:=tgg_private.studio_project_permission(p_project_id);
  return jsonb_build_object(
    'ok',true,
    'project_id',p_project_id,
    'permission',v_perm,
    'versions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',v.id,
        'version_number',v.version_number,
        'label',v.label,
        'created_at',v.created_at,
        'created_by_stage_name',coalesce((select a.stage_name from public.artists a where a.user_id=v.user_id order by a.created_at limit 1),'Creator'),
        'saved_revision',coalesce((v.snapshot#>>'{project,revision}')::bigint,0),
        'schema_version',coalesce((v.snapshot->>'schema_version')::int,1),
        'has_transport',v.snapshot ? 'transport'
      ) order by v.version_number desc)
      from (select * from public.tgg_studio_versions where project_id=p_project_id order by version_number desc limit 30) v
    ),'[]'::jsonb),
    'generated_at',now()
  );
end
$function$;

create or replace function tgg_private.studio_recall_project_state(
  p_project_id uuid,
  p_version_id uuid,
  p_client_id text,
  p_base_revision bigint default null
)
returns jsonb
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_uid uuid:=auth.uid();
  v_perm jsonb;
  v_project public.tgg_studio_projects;
  v_version public.tgg_studio_versions;
  v_lease public.tgg_studio_control_leases;
  v_saved_data jsonb;
  v_saved_transport jsonb;
  v_new_revision bigint;
  v_event_id bigint;
  v_client text:=left(btrim(coalesce(p_client_id,'')),120);
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if v_client='' then raise exception 'CLIENT_ID_REQUIRED' using errcode='22023'; end if;
  v_perm:=tgg_private.studio_project_permission(p_project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;

  select * into v_project from public.tgg_studio_projects where id=p_project_id for update;
  if p_base_revision is not null and p_base_revision<>v_project.revision then raise exception 'REVISION_CONFLICT'; end if;

  select * into v_lease from public.tgg_studio_control_leases where project_id=p_project_id and expires_at>now();
  if v_lease.project_id is not null and (v_lease.user_id<>v_uid or v_lease.client_id<>v_client) then
    raise exception 'CONTROL_HELD_BY_COLLABORATOR' using errcode='55000';
  end if;

  select * into v_version from public.tgg_studio_versions where id=p_version_id and project_id=p_project_id;
  if v_version.id is null then raise exception 'VERSION_NOT_FOUND'; end if;

  v_saved_data:=coalesce(v_version.snapshot#>'{project,project_data}','{}'::jsonb);
  v_saved_transport:=v_version.snapshot->'transport';

  update public.tgg_studio_projects
  set project_data=v_saved_data,revision=revision+1,updated_at=now()
  where id=p_project_id
  returning revision into v_new_revision;

  if v_saved_transport is not null and jsonb_typeof(v_saved_transport)='object' then
    insert into public.tgg_studio_transport_state(
      project_id,controller_user_id,controller_client_id,is_playing,is_recording,playhead_seconds,loop_enabled,metronome_enabled,updated_at
    ) values(
      p_project_id,v_uid,v_client,false,false,
      greatest(0,least(86400,coalesce((v_saved_transport->>'playhead_seconds')::numeric,0))),
      coalesce((v_saved_transport->>'loop_enabled')::boolean,false),
      coalesce((v_saved_transport->>'metronome_enabled')::boolean,false),now()
    )
    on conflict(project_id) do update set
      controller_user_id=excluded.controller_user_id,
      controller_client_id=excluded.controller_client_id,
      is_playing=false,
      is_recording=false,
      playhead_seconds=excluded.playhead_seconds,
      loop_enabled=excluded.loop_enabled,
      metronome_enabled=excluded.metronome_enabled,
      updated_at=now();
  else
    update public.tgg_studio_transport_state set is_playing=false,is_recording=false,updated_at=now() where project_id=p_project_id;
  end if;

  insert into public.tgg_studio_project_events(project_id,user_id,event_type,entity_type,entity_id,patch,base_revision,revision)
  values(
    p_project_id,v_uid,'session_recall','checkpoint',v_version.id::text,
    jsonb_build_object(
      'controls',coalesce(v_saved_data->'controls','{}'::jsonb),
      'session_recall',jsonb_build_object('version_id',v_version.id,'version_number',v_version.version_number,'label',v_version.label)
    ),
    v_project.revision,v_new_revision
  ) returning id into v_event_id;

  return jsonb_build_object(
    'ok',true,'project_id',p_project_id,'version_id',v_version.id,'version_number',v_version.version_number,
    'label',v_version.label,'revision',v_new_revision,'event_id',v_event_id,'project_data',v_saved_data,
    'transport',(select jsonb_build_object('is_playing',t.is_playing,'is_recording',t.is_recording,'playhead_seconds',t.playhead_seconds,'loop_enabled',t.loop_enabled,'metronome_enabled',t.metronome_enabled,'updated_at',t.updated_at) from public.tgg_studio_transport_state t where t.project_id=p_project_id)
  );
end
$function$;

