create or replace function tgg_private.studio_producer_bundle(p_project_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path=''
as $function$
declare
  v_uid uuid:=auth.uid();
  v_perm jsonb;
  v_project public.tgg_studio_projects;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  v_perm:=tgg_private.studio_project_permission(p_project_id);
  select * into v_project from public.tgg_studio_projects where id=p_project_id;
  if v_project.id is null then raise exception 'PROJECT_NOT_FOUND'; end if;

  return jsonb_build_object(
    'ok',true,
    'project_id',p_project_id,
    'revision',v_project.revision,
    'permission',v_perm,
    'producer_board',coalesce(v_project.project_data->'producer_board','{}'::jsonb),
    'people',coalesce((
      select jsonb_agg(x.obj order by x.sort_owner desc,x.stage_name)
      from (
        select
          1 as sort_owner,
          coalesce((select a.stage_name from public.artists a where a.user_id=v_project.user_id order by a.created_at limit 1),'Owner') as stage_name,
          jsonb_build_object(
            'user_id',v_project.user_id,
            'stage_name',coalesce((select a.stage_name from public.artists a where a.user_id=v_project.user_id order by a.created_at limit 1),'Owner'),
            'avatar_url',(select a.avatar_url from public.artists a where a.user_id=v_project.user_id order by a.created_at limit 1),
            'role','owner','can_edit',true,'can_record',true,'can_publish',true,
            'online',exists(select 1 from public.tgg_studio_project_presence p where p.project_id=p_project_id and p.user_id=v_project.user_id and p.last_seen_at>now()-interval '2 minutes')
          ) as obj
        union all
        select
          0,
          coalesce((select a.stage_name from public.artists a where a.user_id=m.user_id order by a.created_at limit 1),'Collaborator'),
          jsonb_build_object(
            'user_id',m.user_id,
            'stage_name',coalesce((select a.stage_name from public.artists a where a.user_id=m.user_id order by a.created_at limit 1),'Collaborator'),
            'avatar_url',(select a.avatar_url from public.artists a where a.user_id=m.user_id order by a.created_at limit 1),
            'role',m.role,'can_edit',m.can_edit,'can_record',m.can_record,'can_publish',m.can_publish,
            'online',exists(select 1 from public.tgg_studio_project_presence p where p.project_id=p_project_id and p.user_id=m.user_id and p.last_seen_at>now()-interval '2 minutes')
          )
        from public.tgg_studio_project_members m
        where m.project_id=p_project_id and m.left_at is null and m.user_id<>v_project.user_id
      ) x
    ),'[]'::jsonb),
    'sessions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',s.id,'title',s.title,'status',s.status,'sample_rate',s.sample_rate,'bit_depth',s.bit_depth,
        'recorder_user_id',s.user_id,'recorder_stage_name',coalesce((select a.stage_name from public.artists a where a.user_id=s.user_id order by a.created_at limit 1),'Creator'),
        'started_at',s.started_at,'ended_at',s.ended_at
      ) order by s.created_at desc)
      from (select * from public.tgg_recording_sessions where project_id=p_project_id order by created_at desc limit 12) s
    ),'[]'::jsonb),
    'takes',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',t.id,'session_id',t.session_id,'take_number',t.take_number,'name',t.name,
        'duration_seconds',t.duration_seconds,'is_selected',t.is_selected,
        'recorder_user_id',t.user_id,'recorder_stage_name',coalesce((select a.stage_name from public.artists a where a.user_id=t.user_id order by a.created_at limit 1),'Creator'),
        'created_at',t.created_at
      ) order by t.created_at desc)
      from (select * from public.tgg_recording_takes where project_id=p_project_id order by created_at desc limit 40) t
    ),'[]'::jsonb),
    'generated_at',now()
  );
end
$function$;

create or replace function tgg_private.studio_producer_assign(
  p_project_id uuid,
  p_assignment_key text,
  p_user_id uuid,
  p_duty text,
  p_label text default null,
  p_base_revision bigint default null
)
returns jsonb
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_uid uuid:=auth.uid();
  v_perm jsonb;
  v_project public.tgg_studio_projects;
  v_key text:=lower(left(btrim(coalesce(p_assignment_key,'')),120));
  v_duty text:=lower(left(btrim(coalesce(p_duty,'')),40));
  v_label text:=left(nullif(btrim(coalesce(p_label,'')),''),160);
  v_name text;
  v_board jsonb;
  v_assignments jsonb;
  v_new_revision bigint;
  v_event_id bigint;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if v_key='' or v_key !~ '^[a-z0-9:_-]+$' then raise exception 'ASSIGNMENT_KEY_INVALID' using errcode='22023'; end if;
  if v_duty not in ('producer','mix','record','vocal','edit','review','perform','listen') then raise exception 'DUTY_INVALID' using errcode='22023'; end if;
  v_perm:=tgg_private.studio_project_permission(p_project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;

  select * into v_project from public.tgg_studio_projects where id=p_project_id for update;
  if p_base_revision is not null and p_base_revision<>v_project.revision then raise exception 'REVISION_CONFLICT'; end if;
  if not (
    v_project.user_id=p_user_id or exists(select 1 from public.tgg_studio_project_members m where m.project_id=p_project_id and m.user_id=p_user_id and m.left_at is null)
  ) then raise exception 'ASSIGNEE_NOT_IN_PROJECT' using errcode='22023'; end if;

  select coalesce((select a.stage_name from public.artists a where a.user_id=p_user_id order by a.created_at limit 1),'Creator') into v_name;
  v_board:=coalesce(v_project.project_data->'producer_board','{}'::jsonb);
  v_assignments:=coalesce(v_board->'assignments','{}'::jsonb);
  v_assignments:=jsonb_set(v_assignments,array[v_key],jsonb_build_object(
    'user_id',p_user_id,'display_name',v_name,'duty',v_duty,'label',v_label,'assigned_by',v_uid,'updated_at',now()
  ),true);
  v_board:=jsonb_set(v_board,'{assignments}',v_assignments,true);
  v_board:=jsonb_set(v_board,'{updated_at}',to_jsonb(now()),true);

  update public.tgg_studio_projects
  set project_data=jsonb_set(coalesce(project_data,'{}'::jsonb),'{producer_board}',v_board,true),revision=revision+1,updated_at=now()
  where id=p_project_id returning revision into v_new_revision;

  insert into public.tgg_studio_project_events(project_id,user_id,event_type,entity_type,entity_id,patch,base_revision,revision)
  values(p_project_id,v_uid,'producer_assignment','producer_desk',v_key,
    jsonb_build_object('producer_board',v_board),v_project.revision,v_new_revision)
  returning id into v_event_id;

  return jsonb_build_object('ok',true,'project_id',p_project_id,'assignment_key',v_key,'revision',v_new_revision,'event_id',v_event_id,'producer_board',v_board);
end
$function$;

create or replace function tgg_private.studio_producer_unassign(
  p_project_id uuid,
  p_assignment_key text,
  p_base_revision bigint default null
)
returns jsonb
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_uid uuid:=auth.uid();
  v_perm jsonb;
  v_project public.tgg_studio_projects;
  v_key text:=lower(left(btrim(coalesce(p_assignment_key,'')),120));
  v_board jsonb;
  v_assignments jsonb;
  v_new_revision bigint;
  v_event_id bigint;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED' using errcode='42501'; end if;
  if v_key='' or v_key !~ '^[a-z0-9:_-]+$' then raise exception 'ASSIGNMENT_KEY_INVALID' using errcode='22023'; end if;
  v_perm:=tgg_private.studio_project_permission(p_project_id);
  if not coalesce((v_perm->>'can_edit')::boolean,false) then raise exception 'EDIT_PERMISSION_REQUIRED' using errcode='42501'; end if;
  select * into v_project from public.tgg_studio_projects where id=p_project_id for update;
  if p_base_revision is not null and p_base_revision<>v_project.revision then raise exception 'REVISION_CONFLICT'; end if;
  v_board:=coalesce(v_project.project_data->'producer_board','{}'::jsonb);
  v_assignments:=coalesce(v_board->'assignments','{}'::jsonb)-v_key;
  v_board:=jsonb_set(v_board,'{assignments}',v_assignments,true);
  v_board:=jsonb_set(v_board,'{updated_at}',to_jsonb(now()),true);
  update public.tgg_studio_projects
  set project_data=jsonb_set(coalesce(project_data,'{}'::jsonb),'{producer_board}',v_board,true),revision=revision+1,updated_at=now()
  where id=p_project_id returning revision into v_new_revision;
  insert into public.tgg_studio_project_events(project_id,user_id,event_type,entity_type,entity_id,patch,base_revision,revision)
  values(p_project_id,v_uid,'producer_unassignment','producer_desk',v_key,jsonb_build_object('producer_board',v_board),v_project.revision,v_new_revision)
  returning id into v_event_id;
  return jsonb_build_object('ok',true,'project_id',p_project_id,'assignment_key',v_key,'revision',v_new_revision,'event_id',v_event_id,'producer_board',v_board);
end
$function$;

