  vault_item_id uuid null references public.tgg_vault_items(id) on delete set null,
  title text not null check (char_length(title) between 1 and 200),
  format text not null check (format in ('pcm16','pcm24','float32')),
  sample_rate integer not null check (sample_rate between 8000 and 384000),
  file_size_bytes bigint null check (file_size_bytes is null or file_size_bytes >= 0),
  delivery_target_lufs numeric null check (delivery_target_lufs is null or delivery_target_lufs between -40 and -4),
  metrics jsonb not null default '{}'::jsonb check (jsonb_typeof(metrics)='object'),
  status text not null default 'saved' check (status in ('saved','vault_ready','vault_published')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.tgg_control_room_mastering_reports enable row level security;

drop policy if exists "control room mastering reports select own" on public.tgg_control_room_mastering_reports;
create policy "control room mastering reports select own" on public.tgg_control_room_mastering_reports
for select to authenticated using ((select auth.uid()) = user_id);

drop policy if exists "control room mastering reports insert own" on public.tgg_control_room_mastering_reports;
create policy "control room mastering reports insert own" on public.tgg_control_room_mastering_reports
for insert to authenticated with check (
  (select auth.uid()) = user_id
  and exists (
    select 1 from public.tgg_studio_projects p
    where p.id=project_id and (
      p.user_id=(select auth.uid())
      or exists (
        select 1 from public.tgg_studio_project_members m
        where m.project_id=p.id and m.user_id=(select auth.uid()) and m.left_at is null and (m.can_edit or m.can_record)
      )
    )
  )
);

drop policy if exists "control room mastering reports update own" on public.tgg_control_room_mastering_reports;
create policy "control room mastering reports update own" on public.tgg_control_room_mastering_reports
for update to authenticated
using ((select auth.uid()) = user_id)
with check ((select auth.uid()) = user_id);

drop policy if exists "control room mastering reports delete own" on public.tgg_control_room_mastering_reports;
create policy "control room mastering reports delete own" on public.tgg_control_room_mastering_reports
for delete to authenticated using ((select auth.uid()) = user_id);

grant select,insert,update,delete on public.tgg_control_room_mastering_reports to authenticated;

create index if not exists tgg_control_room_mastering_reports_user_project_idx
on public.tgg_control_room_mastering_reports(user_id, project_id, created_at desc);

