-- ============================================================
-- MIGRATION 20260910232711 fix_direct_call_room_participant_rls_v12_8
-- created_by: trugmusicgroup@gmail.com
-- statement_count: 1

create or replace function public.tgg_start_call_room(
  p_conversation_id uuid,
  p_room_type text default 'video'::text
)
returns uuid
language plpgsql
security definer
set search_path to ''
as $function$
declare
  v_uid uuid := auth.uid();
  v_room uuid;
  v_type text := lower(btrim(coalesce(p_room_type,'video')));
begin
  if v_uid is null then
    raise exception 'AUTH_REQUIRED' using errcode='42501';
  end if;

  if v_type not in ('audio','video','listening','studio','drop') then
    raise exception 'ROOM_TYPE_INVALID' using errcode='22023';
  end if;

  if not exists(
    select 1
    from public.tgg_conversation_members m
    where m.conversation_id=p_conversation_id
      and m.user_id=v_uid
  ) then
    raise exception 'CONVERSATION_ACCESS_DENIED' using errcode='42501';
  end if;

  perform private.tgg_creator_rate_limit_gate('calls.room_start.rpc',60,600);
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_conversation_id::text||':'||v_type,0));

  select r.id
  into v_room
  from public.tgg_call_rooms r
  where r.conversation_id=p_conversation_id
    and r.room_type=v_type
    and r.status='active'
    and r.ended_at is null
  order by r.created_at desc
  limit 1;

  if v_room is null then
    insert into public.tgg_call_rooms(
      created_by,conversation_id,title,room_type,status,is_group,created_at
    )
    select
      v_uid,
      p_conversation_id,
      coalesce(nullif(btrim(c.title),''),'TGG Room'),
      v_type,
      'active',
      (select count(*)>2 from public.tgg_conversation_members m where m.conversation_id=p_conversation_id),
      now()
    from public.tgg_conversations c
    where c.id=p_conversation_id
    returning id into v_room;

    if v_room is null then
      raise exception 'CONVERSATION_NOT_FOUND';
    end if;
  end if;

  insert into public.tgg_call_participants(
    room_id,user_id,mic_enabled,camera_enabled,joined_at,left_at
  )
  select
    v_room,
    m.user_id,
    true,
    (v_type<>'audio'),
    now(),
    null
  from public.tgg_conversation_members m
  where m.conversation_id=p_conversation_id
  on conflict(room_id,user_id) do update
  set left_at=null,
      mic_enabled=true,
      camera_enabled=(v_type<>'audio'),
      joined_at=case
        when public.tgg_call_participants.left_at is not null then now()
        else public.tgg_call_participants.joined_at
      end;

  perform private.tgg_creator_mutation_audit_log(
    'calls.room_start',
    v_room::text,
    jsonb_build_object(
      'conversation_id',p_conversation_id,
      'room_type',v_type,
      'participant_count',(
        select count(*)
        from public.tgg_call_participants p
        where p.room_id=v_room and p.left_at is null
      )
    )
  );

  return v_room;
end;
$function$;

revoke all on function public.tgg_start_call_room(uuid,text) from public;
revoke all on function public.tgg_start_call_room(uuid,text) from anon;
grant execute on function public.tgg_start_call_room(uuid,text) to authenticated;

